    const escapeHtml = (value) => String(value ?? '').replace(/[&<>"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));

    function delay(ms) {
      return new Promise((resolve) => window.setTimeout(resolve, ms));
    }

    function perfEnabled() {
      try {
        return localStorage.getItem(PERF_STORAGE_KEY) === '1';
      } catch (_) {
        return false;
      }
    }

    function apiReadTimeoutMs() {
      return perfEnabled() ? API_PERF_READ_TIMEOUT_MS : API_READ_TIMEOUT_MS;
    }

    function perfNow() {
      return window.performance?.now ? window.performance.now() : Date.now();
    }

    function perfStart(name) {
      if (!perfEnabled()) return null;
      const token = {
        name,
        startedAt: perfNow(),
        startMark: name + ':start:' + Date.now() + ':' + Math.random().toString(16).slice(2),
      };
      try {
        window.performance?.mark?.(token.startMark);
      } catch (_) {
      }
      return token;
    }

    function perfEnd(token, detail = {}) {
      if (!token) return;
      const endedAt = perfNow();
      const durationMs = Math.max(0, endedAt - token.startedAt);
      const entry = { name: token.name, duration_ms: Math.round(durationMs * 10) / 10, detail, at: new Date().toISOString() };
      window.__AUTOSTOP_PERF__ = Array.isArray(window.__AUTOSTOP_PERF__) ? window.__AUTOSTOP_PERF__ : [];
      window.__AUTOSTOP_PERF__.push(entry);
      if (window.__AUTOSTOP_PERF__.length > 250) window.__AUTOSTOP_PERF__.shift();
      try {
        const endMark = token.startMark + ':end';
        window.performance?.mark?.(endMark);
        window.performance?.measure?.(token.name, token.startMark, endMark);
      } catch (_) {
      }
      if (window.console?.debug) window.console.debug('[autostop-perf]', entry);
    }

    async function perfMeasureAsync(name, callback) {
      const token = perfStart(name);
      try {
        return await callback();
      } finally {
        perfEnd(token);
      }
    }

    function stripDescriptionFormatting(value) {
      let text = String(value || '');
      for (let index = 0; index < 4; index += 1) {
        const previous = text;
        text = text
          .replace(/\+\+([\s\S]+?)\+\+/g, '$1')
          .replace(/\*\*([\s\S]+?)\*\*/g, '$1')
          .replace(/(^|[^*])\*([^*\n]+?)\*(?!\*)/g, '$1$2');
        if (text === previous) break;
      }
      return text;
    }

    const DESCRIPTION_MAX_LENGTH = 20000;
    const DESCRIPTION_BLOCK_TAGS = new Set(['DIV', 'P', 'LI']);

    function descriptionMarkdownToHtml(value) {
      let html = escapeHtml(String(value || ''));
      html = html
        .replace(/\+\+([\s\S]+?)\+\+/g, '<u>$1</u>')
        .replace(/\*\*([\s\S]+?)\*\*/g, '<strong>$1</strong>')
        .replace(/(^|[^*])\*([^*\n]+?)\*(?!\*)/g, '$1<em>$2</em>');
      return html.replace(/\r\n|\r|\n/g, '<br>');
    }

    function descriptionFormatTagName(kind) {
      if (kind === 'bold') return 'strong';
      if (kind === 'italic') return 'em';
      if (kind === 'underline') return 'u';
      return null;
    }

    function descriptionElementHasStyle(element, kind) {
      const tag = element.tagName || '';
      const style = element.style || {};
      if (kind === 'bold') {
        const rawWeight = String(style.fontWeight || '').trim();
        return tag === 'B' || tag === 'STRONG' || rawWeight === 'bold' || finiteNumber(rawWeight) >= 600;
      }
      if (kind === 'italic') return tag === 'I' || tag === 'EM' || String(style.fontStyle || '').trim() === 'italic';
      if (kind === 'underline') return tag === 'U' || String(style.textDecorationLine || style.textDecoration || '').includes('underline');
      return false;
    }

    function wrapDescriptionMarkdown(text, kind) {
      if (!text) return '';
      if (kind === 'bold') return '**' + text + '**';
      if (kind === 'italic') return '*' + text + '*';
      if (kind === 'underline') return '++' + text + '++';
      return text;
    }

    function descriptionNodeToMarkdown(node) {
      if (!node) return '';
      if (node.nodeType === Node.TEXT_NODE) return String(node.nodeValue || '');
      if (node.nodeType !== Node.ELEMENT_NODE) return '';
      const element = node;
      const tag = element.tagName || '';
      if (tag === 'BR') return '\n';
      let text = Array.from(element.childNodes || []).map(descriptionNodeToMarkdown).join('');
      if (descriptionElementHasStyle(element, 'bold')) text = wrapDescriptionMarkdown(text, 'bold');
      if (descriptionElementHasStyle(element, 'italic')) text = wrapDescriptionMarkdown(text, 'italic');
      if (descriptionElementHasStyle(element, 'underline')) text = wrapDescriptionMarkdown(text, 'underline');
      if (tag === 'LI') text = '- ' + text;
      if (DESCRIPTION_BLOCK_TAGS.has(tag)) text += '\n';
      return text;
    }

    function descriptionEditorToMarkdown(editor) {
      if (!editor) return '';
      return Array.from(editor.childNodes || [])
        .map(descriptionNodeToMarkdown)
        .join('')
        .replace(/\u00a0/g, ' ')
        .replace(/\n{3,}/g, '\n\n');
    }

    function syncCardDescriptionSourceFromEditor() {
      if (!els.cardDescription || !els.cardDescriptionEditor) return;
      const maxLength = Math.max(0, finiteNumber(els.cardDescription.maxLength, DESCRIPTION_MAX_LENGTH));
      els.cardDescription.value = descriptionEditorToMarkdown(els.cardDescriptionEditor).slice(0, maxLength);
    }

    function setCardDescriptionValue(value) {
      const maxLength = Math.max(0, finiteNumber(els.cardDescription?.maxLength, DESCRIPTION_MAX_LENGTH));
      const nextValue = String(value || '').slice(0, maxLength);
      if (els.cardDescription) els.cardDescription.value = nextValue;
      state.cardDescriptionLoading = false;
      if (els.cardDescriptionEditor) {
        els.cardDescriptionEditor.innerHTML = descriptionMarkdownToHtml(nextValue);
        els.cardDescriptionEditor.contentEditable = 'true';
        els.cardDescriptionEditor.classList.remove('is-loading');
        els.cardDescriptionEditor.removeAttribute('aria-busy');
      }
      els.cardDescriptionToolbar?.querySelectorAll('[data-description-format]').forEach((button) => {
        button.disabled = false;
      });
      if (els.saveCardButton && !state.cardSaveInFlight) els.saveCardButton.disabled = false;
      syncCardDescriptionHeight();
    }

    function getCardDescriptionValue() {
      syncCardDescriptionSourceFromEditor();
      return String(els.cardDescription?.value || '');
    }

    function setCardDescriptionLoading(isLoading, message = 'Загрузка описания...') {
      state.cardDescriptionLoading = Boolean(isLoading);
      if (!els.cardDescriptionEditor) return;
      if (isLoading) {
        if (els.cardDescription) els.cardDescription.value = '';
        els.cardDescriptionEditor.textContent = message;
        els.cardDescriptionEditor.contentEditable = 'false';
        els.cardDescriptionEditor.classList.add('is-loading');
        els.cardDescriptionEditor.setAttribute('aria-busy', 'true');
        els.cardDescriptionToolbar?.querySelectorAll('[data-description-format]').forEach((button) => {
          button.disabled = true;
        });
        if (els.saveCardButton) els.saveCardButton.disabled = true;
      } else {
        els.cardDescriptionEditor.contentEditable = 'true';
        els.cardDescriptionEditor.classList.remove('is-loading');
        els.cardDescriptionEditor.removeAttribute('aria-busy');
        els.cardDescriptionToolbar?.querySelectorAll('[data-description-format]').forEach((button) => {
          button.disabled = false;
        });
        if (els.saveCardButton && !state.cardSaveInFlight) els.saveCardButton.disabled = false;
      }
      syncCardDescriptionHeight();
    }

    function handleCardDescriptionInput() {
      if (state.cardDescriptionLoading) return;
      syncCardDescriptionSourceFromEditor();
      syncCardDescriptionHeight();
      scheduleCardSaveDirtyStateSync();
    }

    function descriptionSelectionRange() {
      const editor = els.cardDescriptionEditor;
      const selection = window.getSelection();
      if (!editor || !selection || !selection.rangeCount) return null;
      const range = selection.getRangeAt(0);
      if (!editor.contains(range.commonAncestorContainer) && range.commonAncestorContainer !== editor) return null;
      return range;
    }

    function descriptionSelectionCoversEditor() {
      const editor = els.cardDescriptionEditor;
      const range = descriptionSelectionRange();
      if (!editor || !range) return false;
      const fullRange = document.createRange();
      fullRange.selectNodeContents(editor);
      return range.compareBoundaryPoints(Range.START_TO_START, fullRange) <= 0
        && range.compareBoundaryPoints(Range.END_TO_END, fullRange) >= 0;
    }

    function descriptionPlainTextFragment(value) {
      const fragment = document.createDocumentFragment();
      const marker = document.createTextNode('');
      String(value || '').split(/\r\n|\r|\n/).forEach((line, index) => {
        if (index > 0) fragment.appendChild(document.createElement('br'));
        fragment.appendChild(document.createTextNode(line));
      });
      fragment.appendChild(marker);
      return { fragment, marker };
    }

    function insertDescriptionPlainText(value) {
      const editor = els.cardDescriptionEditor;
      if (!editor) return;
      editor.focus();
      let range = descriptionSelectionRange();
      if (!range) {
        range = document.createRange();
        range.selectNodeContents(editor);
        range.collapse(false);
      }
      range.deleteContents();
      const { fragment, marker } = descriptionPlainTextFragment(value);
      range.insertNode(fragment);
      const selection = window.getSelection();
      const nextRange = document.createRange();
      nextRange.setStartBefore(marker);
      nextRange.collapse(true);
      marker.remove();
      selection.removeAllRanges();
      selection.addRange(nextRange);
      handleCardDescriptionInput();
    }

    function handleDescriptionBeforeInput(event) {
      if (event.inputType !== 'insertText' || typeof event.data !== 'string') return;
      if (!descriptionSelectionCoversEditor()) return;
      event.preventDefault();
      insertDescriptionPlainText(event.data);
    }

    function handleDescriptionPaste(event) {
      const text = String(event.clipboardData?.getData('text/plain') || '');
      if (!text) return;
      event.preventDefault();
      insertDescriptionPlainText(text);
    }

    function applyDescriptionFormat(kind) {
      const editor = els.cardDescriptionEditor;
      const tagName = descriptionFormatTagName(kind);
      if (!editor || !tagName) return;
      editor.focus();
      const range = descriptionSelectionRange();
      if (!range) return;
      const wrapper = document.createElement(tagName);
      if (range.collapsed) {
        wrapper.appendChild(document.createTextNode(''));
        range.insertNode(wrapper);
      } else {
        wrapper.appendChild(range.extractContents());
        range.insertNode(wrapper);
      }
      const selection = window.getSelection();
      const nextRange = document.createRange();
      nextRange.selectNodeContents(wrapper);
      if (range.collapsed) nextRange.collapse(false);
      selection.removeAllRanges();
      selection.addRange(nextRange);
      handleCardDescriptionInput();
    }

    function handleDescriptionToolbarMouseDown(event) {
      if (event.target.closest('[data-description-format]')) event.preventDefault();
    }

    function handleDescriptionFormatClick(event) {
      const button = event.target.closest('[data-description-format]');
      if (!button) return;
      event.preventDefault();
      applyDescriptionFormat(button.dataset.descriptionFormat);
    }

    function handleDescriptionKeyboardShortcut(event) {
      if (!event.ctrlKey || event.altKey || event.metaKey) return;
      const key = String(event.key || '').toLowerCase();
      const format = { b: 'bold', i: 'italic', u: 'underline' }[key];
      if (!format) return;
      event.preventDefault();
      applyDescriptionFormat(format);
    }

