    function repairOrderParseNumber(value) {
      const normalized = String(value ?? '')
        .trim()
        .replace(/\s+/g, '')
        .replace(',', '.')
        .replace(/[^0-9.-]/g, '');
      if (!normalized) return null;
      const parsed = Number(normalized);
      return Number.isFinite(parsed) ? parsed : null;
    }

    function repairOrderRoundMoney(value) {
      return Math.round(value * 100) / 100;
    }

    function repairOrderNumberToRaw(value) {
      const rounded = repairOrderRoundMoney(value);
      if (Math.abs(rounded % 1) < 0.000001) return String(Math.trunc(rounded));
      return rounded.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
    }

    function repairOrderNormalizeNonNegativeRaw(value) {
      const parsed = repairOrderParseNumber(value);
      if (parsed === null) return '';
      return repairOrderNumberToRaw(Math.max(parsed, 0));
    }

    function repairOrderNormalizePercentRaw(value) {
      const parsed = repairOrderParseNumber(value);
      if (parsed === null) return '';
      return repairOrderNumberToRaw(Math.min(Math.max(parsed, 0), 100));
    }

    function repairOrderNormalizeBool(value) {
      if (value === true) return 'true';
      const normalized = String(value ?? '').trim().toLowerCase();
      return ['1', 'true', 'yes', 'on', 'да'].includes(normalized) ? 'true' : '';
    }

    function repairOrderFormatMoney(value) {
      const normalized = typeof value === 'number' ? value : repairOrderParseNumber(value);
      const safeValue = normalized === null ? 0 : normalized;
      const rounded = repairOrderRoundMoney(safeValue);
      return new Intl.NumberFormat('ru-RU', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(rounded).replace(/,00$/, '') + ' ₽';
    }

    function repairOrderFormatRubles(value) {
      const normalized = typeof value === 'number' ? value : repairOrderParseNumber(value);
      const safeValue = normalized === null ? 0 : normalized;
      return new Intl.NumberFormat('ru-RU', {
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
      }).format(Math.round(safeValue)) + ' ₽';
    }

    function normalizeRepairOrderPaymentMethod(value) {
      const normalized = String(value ?? '').trim().toLowerCase();
      if (['card', 'card_transfer', 'card-transfer', 'bank_card', 'на карту', 'карта', 'перевод', 'мария'].includes(normalized)) return 'card';
      if (['cashless', 'wire', 'bank', 'безнал', 'безналичный'].includes(normalized)) return 'cashless';
      return 'cash';
    }

    function repairOrderPaymentMethodFromCashboxName(value, fallback = 'cash') {
      const normalized = String(value ?? '').trim().toLowerCase();
      if (!normalized) return normalizeRepairOrderPaymentMethod(fallback);
      if (normalized.includes('безнал') || normalized.includes('cashless') || normalized.includes('wire') || normalized.includes('bank')) {
        return 'cashless';
      }
      if (normalized.includes('на карту') || normalized.includes('карта') || normalized.includes('card') || normalized.includes('мария')) {
        return 'card';
      }
      return 'cash';
    }

    function repairOrderPaymentCashboxBucket(name) {
      const normalized = String(name ?? '').trim().toLowerCase();
      if (normalized.includes('безнал') || normalized.includes('cashless') || normalized.includes('wire') || normalized.includes('bank')) return 'cashless';
      if (normalized.includes('карта') || normalized.includes('мария')) return 'card';
      return 'cash';
    }

    function repairOrderPaymentCashboxLabel(bucket) {
      if (bucket === 'cashless') return 'Безналичные';
      if (bucket === 'card') return 'На карту';
      return 'Наличные';
    }

    function repairOrderPaymentCashboxItems() {
      const items = (Array.isArray(state.cashboxes) ? state.cashboxes : [])
        .slice()
        .sort((a, b) => String(a?.name || '').localeCompare(String(b?.name || ''), 'ru'));
      const buckets = ['cash', 'cashless', 'card'];
      const preferredItems = [];
      const usedIds = new Set();
      for (const bucket of buckets) {
        const match = items.find((item) => {
          const itemId = String(item?.id || '').trim();
          if (!itemId || usedIds.has(itemId)) return false;
          return repairOrderPaymentCashboxBucket(item?.name || '') === bucket;
        });
        if (match) {
          const matchId = String(match?.id || '').trim();
          if (matchId && !usedIds.has(matchId)) {
            preferredItems.push(match);
            usedIds.add(matchId);
          }
        }
      }
      return preferredItems;
    }

    function selectedRepairOrderPaymentCashbox() {
      const cashboxId = String(els.repairOrderPaymentCashbox?.value || '').trim();
      if (!cashboxId) return null;
      return (Array.isArray(state.cashboxes) ? state.cashboxes : []).find((item) => String(item?.id || '').trim() === cashboxId) || null;
    }

    function repairOrderPaymentMethodFromPayments(payments, fallback = 'cash') {
      const normalizedPayments = Array.isArray(payments) ? payments : [];
      if (!normalizedPayments.length) return normalizeRepairOrderPaymentMethod(fallback);
      let hasCardPayment = false;
      for (const item of normalizedPayments) {
        const resolved = repairOrderPaymentMethodFromCashboxName(
          item?.cashbox_name || '',
          item?.payment_method || fallback
        );
        if (resolved === 'cashless') return 'cashless';
        if (resolved === 'card') hasCardPayment = true;
      }
      return hasCardPayment ? 'card' : normalizeRepairOrderPaymentMethod(fallback);
    }

    function emptyRepairOrderPayment() {
      return {
        id: '',
        amount: '',
        paid_at: '',
        note: '',
        payment_method: 'cash',
        actor_name: '',
        cashbox_id: '',
        cashbox_name: '',
        cash_transaction_id: '',
      };
    }

    function normalizeRepairOrderPayment(payment, fallbackId = '') {
      const source = payment && typeof payment === 'object' ? payment : {};
      const amountValue = repairOrderParseNumber(source.amount ?? source.value);
      return {
        id: String(source.id ?? fallbackId ?? '').trim() || fallbackId || ('payment-' + Date.now()),
        amount: amountValue === null ? String(source.amount ?? source.value ?? '').trim() : repairOrderNumberToRaw(amountValue),
        paid_at: String(source.paid_at ?? source.paidAt ?? source.date ?? '').trim(),
        note: String(source.note ?? source.comment ?? source.description ?? '').trim(),
        payment_method: repairOrderPaymentMethodFromCashboxName(
          source.cashbox_name ?? source.cashboxName ?? '',
          source.payment_method ?? source.paymentMethod ?? 'cash'
        ),
        actor_name: String(source.actor_name ?? source.actorName ?? '').trim(),
        cashbox_id: String(source.cashbox_id ?? source.cashboxId ?? '').trim(),
        cashbox_name: String(source.cashbox_name ?? source.cashboxName ?? '').trim(),
        cash_transaction_id: String(source.cash_transaction_id ?? source.cashTransactionId ?? '').trim(),
      };
    }

    function normalizeRepairOrderPayments(payments, legacyPrepayment = '', defaultPaidAt = '') {
      const normalizedItems = Array.isArray(payments)
        ? payments.map((item, index) => normalizeRepairOrderPayment(item, 'payment-' + (index + 1))).filter((item) => item.amount || item.note || item.paid_at)
        : [];
      if (normalizedItems.length) return normalizedItems;
      const legacyAmount = repairOrderParseNumber(legacyPrepayment);
      if (legacyAmount === null || legacyAmount === 0) return [];
      return [
        normalizeRepairOrderPayment(
          {
            id: 'legacy-prepayment',
            amount: repairOrderNumberToRaw(legacyAmount),
            paid_at: defaultPaidAt || currentRepairOrderDateTime(),
            note: 'Перенесено из предоплаты',
            payment_method: 'cash',
          },
          'legacy-prepayment'
        ),
      ];
    }

    function repairOrderPaymentsTotalValue(payments) {
      return repairOrderRoundMoney((Array.isArray(payments) ? payments : []).reduce((total, item) => {
        return total + (repairOrderParseNumber(item?.amount) ?? 0);
      }, 0));
    }

    function repairOrderPaymentsValueByMethod(payments, method) {
      return repairOrderRoundMoney((Array.isArray(payments) ? payments : []).reduce((total, item) => {
        const paymentMethod = repairOrderPaymentMethodFromCashboxName(
          item?.cashbox_name ?? item?.cashboxName ?? '',
          item?.payment_method ?? item?.paymentMethod ?? 'cash'
        );
        if (paymentMethod !== method) return total;
        return total + (repairOrderParseNumber(item?.amount) ?? 0);
      }, 0));
    }

    function repairOrderCashPaymentsValue(payments) {
      return repairOrderPaymentsValueByMethod(payments, 'cash');
    }

    function repairOrderCardPaymentsValue(payments) {
      return repairOrderPaymentsValueByMethod(payments, 'card');
    }

    function repairOrderCashlessPaymentsValue(payments) {
      return repairOrderPaymentsValueByMethod(payments, 'cashless');
    }

    function repairOrderSummaryValue(baseTotal, payments) {
      const normalizedBaseTotal = repairOrderRoundMoney(repairOrderParseNumber(baseTotal) ?? 0);
      const normalizedPayments = Array.isArray(payments) ? payments : [];
      const basePaidCash = repairOrderCashPaymentsValue(normalizedPayments);
      const basePaidCard = repairOrderCardPaymentsValue(normalizedPayments);
      const basePaidNoncash = repairOrderCashlessPaymentsValue(normalizedPayments);
      const baseRemaining = repairOrderRoundMoney(Math.max(normalizedBaseTotal - basePaidCash - basePaidCard - basePaidNoncash, 0));
      const taxesAndFees = repairOrderRoundMoney(basePaidNoncash * repairOrderTaxRate('cashless'));
      const totalPaid = repairOrderRoundMoney(basePaidCash + basePaidCard + basePaidNoncash);
      const cashDue = repairOrderRoundMoney(Math.max(normalizedBaseTotal + taxesAndFees - totalPaid, 0));
      return {
        base_total: normalizedBaseTotal,
        base_paid_cash_only: basePaidCash,
        base_paid_cash: repairOrderRoundMoney(basePaidCash + basePaidCard),
        base_paid_card: basePaidCard,
        base_paid_noncash: basePaidNoncash,
        base_remaining: baseRemaining,
        cash_due: cashDue,
        noncash_due: repairOrderCashlessGrossValue(cashDue),
        taxes_and_fees: taxesAndFees,
        total_paid: totalPaid,
        grand_total: repairOrderRoundMoney(normalizedBaseTotal + taxesAndFees),
        due_total: cashDue,
      };
    }

    function repairOrderPaymentMethodLabel(value) {
      const normalized = normalizeRepairOrderPaymentMethod(value);
      if (normalized === 'cashless') return 'Безналичный';
      if (normalized === 'card') return 'На карту';
      return 'Наличный';
    }

    function repairOrderTaxRate(value) {
      return normalizeRepairOrderPaymentMethod(value) === 'cashless' ? 0.15 : 0;
    }

    function repairOrderCashlessNetRate() {
      return 1 - repairOrderTaxRate('cashless');
    }

    function repairOrderCashlessGrossValue(netAmount) {
      const normalized = repairOrderRoundMoney(repairOrderParseNumber(netAmount) ?? 0);
      const netRate = repairOrderCashlessNetRate();
      if (normalized <= 0 || netRate <= 0) return 0;
      return repairOrderRoundMoney(normalized / netRate);
    }

    function syncRepairOrderPaymentMethod(value) {
      const normalized = normalizeRepairOrderPaymentMethod(value);
      if (els.repairOrderPaymentMethod) els.repairOrderPaymentMethod.value = normalized;
      return normalized;
    }

    function syncRepairOrderPaymentMethodFromPayments() {
      return syncRepairOrderPaymentMethod(
        repairOrderPaymentMethodFromPayments(
          state.repairOrderPayments,
          els.repairOrderPaymentMethod?.value || 'cash'
        )
      );
    }

    function repairOrderProjectedTaxesValue(subtotal, paymentMethod) {
      if (normalizeRepairOrderPaymentMethod(paymentMethod) !== 'cashless') return 0;
      return repairOrderRoundMoney(
        repairOrderCashlessGrossValue(subtotal) - repairOrderRoundMoney(subtotal)
      );
    }

    function renderRepairOrderPaymentCashboxOptions(selectedId = '') {
      if (!els.repairOrderPaymentCashbox) return;
      const selected = String(selectedId || '').trim();
      const preferredItems = repairOrderPaymentCashboxItems();
      const options = ['<option value="">ВЫБЕРИ КАССУ</option>'].concat(preferredItems.map((item) => {
        const itemId = String(item?.id || '').trim();
        const isSelected = itemId && itemId === selected ? ' selected' : '';
        return '<option value="' + escapeHtml(itemId) + '"' + isSelected + '>' + escapeHtml(repairOrderPaymentCashboxLabel(repairOrderPaymentCashboxBucket(item?.name || ''))) + '</option>';
      }));
      els.repairOrderPaymentCashbox.innerHTML = options.join('');
      if (!selected && preferredItems.length && !els.repairOrderPaymentCashbox.value) {
        els.repairOrderPaymentCashbox.value = String(preferredItems[0]?.id || '').trim();
      }
    }

    async function ensureRepairOrderPaymentCashboxes() {
      if (state.cashboxesLoaded && Array.isArray(state.cashboxes) && state.cashboxes.length) {
        renderRepairOrderPaymentCashboxOptions(els.repairOrderPaymentCashbox?.value || '');
        return;
      }
      const data = await api('/api/list_cashboxes?limit=200');
      state.cashboxes = Array.isArray(data?.cashboxes) ? data.cashboxes : [];
      state.cashboxesLoaded = true;
      renderRepairOrderPaymentCashboxOptions(els.repairOrderPaymentCashbox?.value || '');
    }

    function repairOrderRowHasAnyData(row) {
      return ['name', 'catalog_number', 'quantity', 'cost_price', 'price', 'total'].some((fieldName) => String(row?.[fieldName] ?? '').trim());
    }

    function repairOrderResolvedRowTotalValue(row) {
      const quantity = repairOrderParseNumber(row?.quantity);
      const price = repairOrderParseNumber(row?.price);
      const fallback = repairOrderParseNumber(row?.total);
      const roundedFallback = fallback === null ? null : repairOrderRoundMoney(fallback);
      if (quantity !== null && price !== null) {
        const computed = repairOrderRoundMoney(quantity * price);
        if (
          roundedFallback !== null
          && Math.abs(roundedFallback - computed) <= REPAIR_ORDER_ROW_TOTAL_ROUNDING_TOLERANCE
        ) {
          return roundedFallback;
        }
        return computed;
      }
      return roundedFallback;
    }

    function repairOrderRowsTotalValue(rows) {
      const normalizedRows = Array.isArray(rows) ? rows.map(normalizeRepairOrderRow).filter(repairOrderRowHasAnyData) : [];
      return repairOrderRoundMoney(normalizedRows.reduce((subtotal, row) => {
        return subtotal + (repairOrderResolvedRowTotalValue(row) ?? 0);
      }, 0));
    }

    function normalizeRepairOrderRow(row) {
      const source = row && typeof row === 'object' ? row : {};
      const fallbackTotal = String(source.total ?? '').trim();
      const totalValue = repairOrderResolvedRowTotalValue({
        quantity: source.quantity,
        price: source.price,
        total: fallbackTotal,
      });
      return {
        name: String(source.name ?? '').trim(),
        catalog_number: String(source.catalog_number ?? source.part_number ?? source.catalogNumber ?? source.partNumber ?? '').trim(),
        quantity: String(source.quantity ?? '').trim(),
        cost_price: String(source.cost_price ?? source.costPrice ?? source.purchase_price ?? source.cost ?? '').trim(),
        price: String(source.price ?? '').trim(),
        total: totalValue === null ? fallbackTotal : repairOrderNumberToRaw(totalValue),
        executor_id: String(source.executor_id ?? source.employee_id ?? '').trim(),
        executor_name: String(source.executor_name ?? source.employee_name ?? '').trim(),
        work_executor_id_snapshot: String(source.work_executor_id_snapshot ?? '').trim(),
        work_executor_name_snapshot: String(source.work_executor_name_snapshot ?? '').trim(),
        work_quantity_snapshot: String(source.work_quantity_snapshot ?? '').trim(),
        work_price_snapshot: String(source.work_price_snapshot ?? '').trim(),
        work_total_snapshot: String(source.work_total_snapshot ?? '').trim(),
        salary_mode_snapshot: String(source.salary_mode_snapshot ?? '').trim(),
        base_salary_snapshot: String(source.base_salary_snapshot ?? '').trim(),
        work_percent_snapshot: String(source.work_percent_snapshot ?? '').trim(),
        salary_amount: String(source.salary_amount ?? '').trim(),
        salary_accrued_at: String(source.salary_accrued_at ?? '').trim(),
        work_salary_override_enabled: repairOrderNormalizeBool(source.work_salary_override_enabled ?? ''),
        work_salary_guarantee: repairOrderNormalizeNonNegativeRaw(source.work_salary_guarantee ?? ''),
        work_salary_percent_override: repairOrderNormalizePercentRaw(source.work_salary_percent_override ?? ''),
        work_salary_cost_price: repairOrderNormalizeNonNegativeRaw(source.work_salary_cost_price ?? ''),
        work_salary_note: String(source.work_salary_note ?? '').trim(),
        material_executor_id_snapshot: String(source.material_executor_id_snapshot ?? '').trim(),
        material_executor_name_snapshot: String(source.material_executor_name_snapshot ?? '').trim(),
        material_quantity_snapshot: String(source.material_quantity_snapshot ?? '').trim(),
        material_price_snapshot: String(source.material_price_snapshot ?? '').trim(),
        material_cost_price_snapshot: String(source.material_cost_price_snapshot ?? '').trim(),
        material_percent_snapshot: String(source.material_percent_snapshot ?? '').trim(),
        material_profit: String(source.material_profit ?? '').trim(),
        material_salary_amount: String(source.material_salary_amount ?? '').trim(),
        material_salary_accrued_at: String(source.material_salary_accrued_at ?? '').trim(),
        inventory_item_id: String(source.inventory_item_id ?? source.inventoryItemId ?? '').trim(),
        inventory_movement_id: String(source.inventory_movement_id ?? source.inventoryMovementId ?? '').trim(),
        inventory_unit: String(source.inventory_unit ?? source.inventoryUnit ?? '').trim(),
      };
    }

    function normalizeRepairOrder(order) {
      const source = order && typeof order === 'object' ? order : {};
      const normalizeRows = (rows) => Array.isArray(rows) ? rows.map(normalizeRepairOrderRow).filter(repairOrderRowHasAnyData) : [];
      const payments = normalizeRepairOrderPayments(
        source.payments ?? source.payment_history ?? [],
        source.prepayment ?? source.advance_payment ?? source.advancePayment ?? '',
        String(source.opened_at ?? source.openedAt ?? source.date ?? '').trim()
      );
      const works = normalizeRows(source.works);
      const materials = normalizeRows(source.materials);
      const paymentMethod = repairOrderPaymentMethodFromPayments(
        payments,
        source.payment_method ?? source.paymentMethod ?? 'cash'
      );
      const subtotal = repairOrderRoundMoney(
        repairOrderRowsTotalValue(works) + repairOrderRowsTotalValue(materials)
      );
      const summary = repairOrderSummaryValue(subtotal, payments);
      return {
        number: String(source.number ?? '').trim(),
        date: String(source.date ?? '').trim(),
        status: normalizeRepairOrderStatus(source.status),
        opened_at: String(source.opened_at ?? source.openedAt ?? '').trim(),
        closed_at: String(source.closed_at ?? source.closedAt ?? '').trim(),
        client: String(source.client ?? '').trim(),
        phone: String(source.phone ?? '').trim(),
        vehicle: String(source.vehicle ?? '').trim(),
        license_plate: String(source.license_plate ?? '').trim(),
        vin: String(source.vin ?? '').trim(),
        mileage: String(source.mileage ?? source.odometer ?? '').trim(),
        payment_method: paymentMethod,
        prepayment: repairOrderNumberToRaw(repairOrderPaymentsTotalValue(payments)),
        payments,
        reason: String(source.reason ?? '').trim(),
        comment: String(source.client_information ?? source.comment ?? '').trim(),
        note: String(source.note ?? source.master_comment ?? source.masterComment ?? source.internal_comment ?? source.internalComment ?? '').trim(),
        tags: normalizeRepairOrderTags(source.tags),
        works,
        materials,
        payment_summary: summary,
      };
    }

    function repairOrderHasAnyData(order) {
      const normalized = normalizeRepairOrder(order);
      return Boolean(
        repairOrderTextHasMeaning(normalized.number) ||
        repairOrderTextHasMeaning(normalized.date) ||
        repairOrderTextHasMeaning(normalized.opened_at) ||
        repairOrderTextHasMeaning(normalized.closed_at) ||
        repairOrderTextHasMeaning(normalized.client) ||
        repairOrderTextHasMeaning(normalized.phone) ||
        repairOrderTextHasMeaning(normalized.vehicle) ||
        repairOrderTextHasMeaning(normalized.license_plate) ||
        repairOrderTextHasMeaning(normalized.vin) ||
        repairOrderTextHasMeaning(normalized.mileage) ||
        repairOrderMoneyHasValue(normalized.prepayment) ||
        normalized.payments.length ||
        repairOrderTextHasMeaning(normalized.reason) ||
        repairOrderTextHasMeaning(normalized.comment) ||
        repairOrderTextHasMeaning(normalized.note) ||
        normalized.tags.length ||
        normalized.works.length ||
        normalized.materials.length
      );
    }

    function repairOrderTextHasMeaning(value) {
      const normalized = String(value ?? '').trim();
      return Boolean(normalized && normalized !== '-' && normalized !== '—');
    }

    function repairOrderMoneyHasValue(value) {
      const parsed = repairOrderParseNumber(value);
      return parsed !== null && Math.abs(parsed) > 0.000001;
    }

    function repairOrderIsEmptyForArchive(order) {
      if (order?.is_empty_for_archive === true) return true;
      const normalized = normalizeRepairOrder(order);
      return !normalized.works.length
        && !normalized.materials.length
        && !normalized.payments.length
        && !repairOrderMoneyHasValue(normalized.prepayment)
        && !repairOrderMoneyHasValue(order?.subtotal_total)
        && !repairOrderMoneyHasValue(order?.due_total);
    }

    function cardArchiveAvailability(card) {
      if (!card?.id || card?.archived) return false;
      if (!repairOrderHasAnyData(card?.repair_order) || repairOrderIsEmptyForArchive(card?.repair_order)) return true;
      return normalizeRepairOrderStatus(card?.repair_order?.status) === 'closed'
        && repairOrderIsFullyPaid(card?.repair_order);
    }

    function cardArchiveUnavailableTitle(card) {
      if (!card?.id || card?.archived) return '';
      if (!repairOrderHasAnyData(card?.repair_order) || repairOrderIsEmptyForArchive(card?.repair_order)) return '';
      const number = String(card?.repair_order?.number || '').trim();
      const suffix = number ? (' №' + number) : '';
      if (normalizeRepairOrderStatus(card?.repair_order?.status) !== 'closed') {
        return 'Заказ-наряд' + suffix + ' открыт. Закройте его перед архивированием.';
      }
      if (!repairOrderIsFullyPaid(card?.repair_order)) {
        return 'Заказ-наряд' + suffix + ' закрыт, но не оплачен.';
      }
      return '';
    }

    function ensureRepairOrderRows(rows) {
      const normalized = Array.isArray(rows) ? rows.map(normalizeRepairOrderRow).filter(repairOrderRowHasAnyData) : [];
      return normalized.length ? normalized : [emptyRepairOrderRow()];
    }

    function repairOrderRowsBody(section) {
      return section === 'materials' ? els.repairOrderMaterialsBody : els.repairOrderWorksBody;
    }

    function repairOrderPadDatePart(value) {
      return String(value).padStart(2, '0');
    }

    function repairOrderCanonicalDateValue(value) {
      const normalized = String(value ?? '').trim();
      if (!normalized) return '';
      const inlineMatch = normalized.match(/^(\d{2})\.(\d{2})\.(\d{2}|\d{4})(?:[,\s]+(\d{2}):(\d{2})(?::\d{2})?)?$/);
      if (inlineMatch) {
        const yearValue = Number(inlineMatch[3]);
        const resolvedYear = inlineMatch[3].length === 2
          ? (yearValue >= 70 ? 1900 + yearValue : 2000 + yearValue)
          : yearValue;
        const hour = inlineMatch[4] || '00';
        const minute = inlineMatch[5] || '00';
        return [
          inlineMatch[1],
          inlineMatch[2],
          String(resolvedYear).padStart(4, '0'),
        ].join('.') + ' ' + hour + ':' + minute;
      }
      const parsed = new Date(normalized);
      if (Number.isNaN(parsed.getTime())) return normalized;
      return [
        repairOrderPadDatePart(parsed.getDate()),
        repairOrderPadDatePart(parsed.getMonth() + 1),
        parsed.getFullYear(),
      ].join('.') + ' ' + repairOrderPadDatePart(parsed.getHours()) + ':' + repairOrderPadDatePart(parsed.getMinutes());
    }

    function repairOrderFormDateDisplayValue(value) {
      const canonical = repairOrderCanonicalDateValue(value);
      if (!canonical) return '';
      return canonical.replace(/^(\d{2}\.\d{2}\.)\d{2}(\d{2}\s+\d{2}:\d{2})$/, '$1$2');
    }

    function currentRepairOrderDateTime() {
      const now = new Date();
      return [
        repairOrderPadDatePart(now.getDate()),
        repairOrderPadDatePart(now.getMonth() + 1),
        now.getFullYear(),
      ].join('.') + ' ' + repairOrderPadDatePart(now.getHours()) + ':' + repairOrderPadDatePart(now.getMinutes());
    }

    function repairOrderDateDisplayValue(value) {
      return repairOrderCanonicalDateValue(value);
    }

    function repairOrderListDateDisplayValue(value) {
      const canonical = repairOrderCanonicalDateValue(value);
      if (!canonical) return '';
      const datePart = canonical.split(' ')[0] || canonical;
      const parts = datePart.split('.');
      if (parts.length === 3 && parts[2].length === 4) {
        return parts[0] + '.' + parts[1] + '.' + parts[2].slice(-2);
      }
      return datePart;
    }

    function repairOrderStatusLabel(status) {
      const normalized = normalizeRepairOrderStatus(status);
      if (normalized === 'closed') return 'Закрыт';
      if (normalized === 'ready') return 'Готов';
      return 'Открыт';
    }

    function normalizeRepairOrderStatus(status) {
      const normalized = String(status || '').trim().toLowerCase();
      if (normalized === 'closed') return 'closed';
      if (normalized === 'ready') return 'ready';
      return 'open';
    }

    function repairOrderCloseBlockedMessage() {
      return 'Для закрытия заказ-наряда необходимо выполнить оплату.';
    }

    function repairOrderIsFullyPaid(order) {
      const normalized = normalizeRepairOrder(order);
      const subtotal = repairOrderRoundMoney(
        repairOrderRowsTotalValue(normalized.works) + repairOrderRowsTotalValue(normalized.materials)
      );
      const summary = repairOrderSummaryValue(subtotal, normalized.payments);
      return summary.cash_due <= 0;
    }

    function syncRepairOrderCloseButtonState(order = null) {
      const normalized = normalizeRepairOrder(order || readRepairOrderFromForm());
      const closeAvailable = normalized.status === 'closed' || repairOrderIsFullyPaid(normalized);
      els.repairOrderCloseButton.disabled = !closeAvailable;
      els.repairOrderCloseButton.dataset.closeAvailable = closeAvailable ? 'true' : 'false';
      els.repairOrderCloseButton.title = closeAvailable ? '' : repairOrderCloseBlockedMessage();
    }

    function repairOrderCardDefaults(card) {
      const currentCard = card && typeof card === 'object' ? card : {};
      const profile = currentCard.vehicle_profile && typeof currentCard.vehicle_profile === 'object' ? currentCard.vehicle_profile : {};
      const openedAt = formatDate(currentCard.created_at || '') || currentRepairOrderDateTime();
      return normalizeRepairOrder({
        date: openedAt,
        opened_at: openedAt,
        client: profile.customer_name || '',
        phone: profile.customer_phone || '',
        vehicle: currentCard.vehicle || vehicleDisplayFromProfile(profile),
        license_plate: currentCard.repair_order?.license_plate || profile.registration_plate || profile.license_plate || '',
        vin: profile.vin || currentCard.repair_order?.vin || '',
        mileage: currentCard.repair_order?.mileage || (profile.mileage ?? ''),
        payment_method: currentCard.repair_order?.payment_method || 'cash',
        prepayment: currentCard.repair_order?.prepayment || '',
        payments: currentCard.repair_order?.payments || [],
        reason: currentCard.title || '',
        comment: currentCard.repair_order?.comment || '',
        note: currentCard.repair_order?.note || '',
        tags: currentCard.repair_order?.tags || [],
      });
    }

    function repairOrderCardDraft(card, order = {}) {
      const source = order && typeof order === 'object' ? order : {};
      const defaults = repairOrderCardDefaults(card);
      const normalized = normalizeRepairOrder(source);
      const hasField = (fieldName, aliases = []) => [fieldName].concat(aliases).some((key) => Object.prototype.hasOwnProperty.call(source, key));
      const resolvedField = (fieldName, aliases = []) => hasField(fieldName, aliases) ? normalized[fieldName] : defaults[fieldName];
      return normalizeRepairOrder({
        ...normalized,
        date: resolvedField('date'),
        opened_at: resolvedField('opened_at', ['openedAt']),
        closed_at: resolvedField('closed_at', ['closedAt']),
        client: resolvedField('client'),
        phone: resolvedField('phone'),
        vehicle: resolvedField('vehicle'),
        license_plate: resolvedField('license_plate', ['licensePlate']),
        vin: resolvedField('vin'),
        mileage: resolvedField('mileage', ['odometer']),
        payment_method: resolvedField('payment_method', ['paymentMethod']),
        prepayment: resolvedField('prepayment', ['advance_payment', 'advancePayment']),
        payments: hasField('payments', ['payment_history']) ? normalized.payments : defaults.payments,
        reason: resolvedField('reason'),
        comment: resolvedField('comment', ['client_information', 'clientInformation']),
        note: resolvedField('note', ['master_comment', 'masterComment', 'internal_comment', 'internalComment']),
        tags: hasField('tags') ? normalized.tags : defaults.tags,
        works: normalized.works,
        materials: normalized.materials,
      });
    }

    function repairOrderHeadingLegacy(number) {
      const normalizedNumber = String(number ?? '').trim();
      return normalizedNumber ? ('ЗАКАЗ-НАРЯД №' + normalizedNumber) : 'ЗАКАЗ-НАРЯД';
    }

    function repairOrderCardRequiredMessageLegacy() {
      return 'Сначала сохраните карточку, чтобы открыть заказ-наряд.';
    }

    function repairOrderHeading(number) {
      const normalizedNumber = String(number ?? '').trim();
      return normalizedNumber ? ('ЗАКАЗ-НАРЯД №' + normalizedNumber) : 'ЗАКАЗ-НАРЯД';
    }

    function repairOrderHeadingHtml(number) {
      const normalizedNumber = String(number ?? '').trim();
      return normalizedNumber
        ? ('ЗАКАЗ-НАРЯД <span class="repair-order-number-badge">№' + escapeHtml(normalizedNumber) + '</span>')
        : 'ЗАКАЗ-НАРЯД';
    }

    function repairOrderNumberHtml(number) {
      const normalizedNumber = String(number ?? '').trim();
      return '<span class="repair-order-number-badge">№' + escapeHtml(normalizedNumber || '-') + '</span>';
    }

    function repairOrderCardRequiredMessage() {
      return 'Сначала сохраните карточку, чтобы открыть заказ-наряд.';
    }

    function repairOrderResponseCard(data, fallbackOrder = {}) {
      return data?.card || {
        ...(state.activeCard || {}),
        id: state.editingId,
        repair_order: data?.repair_order || fallbackOrder,
      };
    }

    async function ensureRepairOrderCard() {
      if (state.editingId && state.activeCard?.id) return state.activeCard;
      if (state.editingId) return { id: state.editingId, repair_order: state.activeCard?.repair_order || {} };
      const payload = currentCardPayload();
      if (!payload.title) {
        const repairOrder = readRepairOrderFromForm();
        payload.title = repairOrder.reason || repairOrder.vehicle || 'Заказ-наряд';
        if (!payload.vehicle && repairOrder.vehicle) payload.vehicle = repairOrder.vehicle;
      }
      if (!payload.title) {
        setStatus(CARD_TITLE_REQUIRED_MESSAGE, true);
        els.cardTitle.focus();
        return null;
      }
      const data = await persistCardPayload(payload);
      const savedCard = data?.card || null;
      if (!savedCard?.id) {
        setStatus(repairOrderCardRequiredMessage(), true);
        return null;
      }
      applyCardModalState(savedCard);
      await refreshSnapshot(true);
      return savedCard;
    }

    async function requireRepairOrderCardId() {
      if (state.editingId) return state.editingId;
      const preparedCard = await ensureRepairOrderCard();
      return preparedCard?.id || '';
    }

    function applyRepairOrderCardUpdate(updatedCard, fallbackOrder = {}) {
      state.activeCard = updatedCard;
      const nextOrder = repairOrderCardDraft(updatedCard, updatedCard?.repair_order || fallbackOrder);
      applyRepairOrderToForm(nextOrder);
      refreshRepairOrderEntry(updatedCard);
      return nextOrder;
    }

    function repairOrderRowInputHtml(fieldName, value, placeholder = '') {
      const isNumeric = fieldName === 'quantity' || fieldName === 'cost_price' || fieldName === 'price';
      return '<input class="repair-order-table__input' + (isNumeric ? ' repair-order-table__input--num' : '') + '" type="text"' + (isNumeric ? ' inputmode="decimal"' : '') + ' data-repair-order-cell="' + escapeHtml(fieldName) + '" value="' + escapeHtml(value) + '">';
    }

    function repairOrderExecutorOptionsHtml(selectedId, selectedName = '') {
      const options = ['<option value="">—</option>'];
      const employees = Array.isArray(state.employees) ? state.employees.filter((item) => item && item.is_active) : [];
      const rendered = new Set();
      employees.forEach((employee) => {
        const employeeId = String(employee.id || '').trim();
        if (!employeeId || rendered.has(employeeId)) return;
        rendered.add(employeeId);
        options.push(
          '<option value="' + escapeHtml(employeeId) + '"' + (employeeId === selectedId ? ' selected' : '') + '>' + escapeHtml(employee.name || 'Сотрудник') + '</option>'
        );
      });
      if (selectedId && !rendered.has(selectedId)) {
        options.push('<option value="' + escapeHtml(selectedId) + '" selected>' + escapeHtml(selectedName || 'Сотрудник') + '</option>');
      }
      return options.join('');
    }

    function repairOrderWorkExecutorCellHtml(normalized) {
      const activeClass = normalized.work_salary_override_enabled === 'true' ? ' is-active' : '';
      return '<div class="repair-order-executor-cell">'
        + '<select class="repair-order-table__select" data-repair-order-cell="executor_id">' + repairOrderExecutorOptionsHtml(normalized.executor_id, normalized.executor_name) + '</select>'
        + '<button class="repair-order-work-salary-gear' + activeClass + '" type="button" title="НАСТРОИТЬ НАЧИСЛЕНИЕ" aria-label="НАСТРОИТЬ НАЧИСЛЕНИЕ" data-repair-order-work-salary-gear>⚙</button>'
        + '</div>';
    }

    function repairOrderRowHtml(section, row, index) {
      const normalized = normalizeRepairOrderRow(row);
      const totalValue = repairOrderResolvedRowTotalValue(normalized);
      const hasDisplayTotal = totalValue !== null || Boolean(normalized.total);
      const catalogCell = section === 'materials'
        ? ('<td>' + repairOrderRowInputHtml('catalog_number', normalized.catalog_number, 'Артикул / OEM') + '</td>')
        : '';
      const executorCell = section === 'works'
        ? '<td>' + repairOrderWorkExecutorCellHtml(normalized) + '</td>'
        : '';
      const materialCostCell = section === 'materials'
        ? '<td class="repair-order-table__numeric">' + repairOrderRowInputHtml('cost_price', normalized.cost_price, '0') + '</td>'
        : '';
      const materialExecutorCell = section === 'materials'
        ? '<td><select class="repair-order-table__select" data-repair-order-cell="executor_id">' + repairOrderExecutorOptionsHtml(normalized.executor_id, normalized.executor_name) + '</select></td>'
        : '';
      const inventoryHiddenFields = section === 'materials'
        ? '<input type="hidden" data-repair-order-row-field="inventory_item_id" value="' + escapeHtml(normalized.inventory_item_id) + '">'
          + '<input type="hidden" data-repair-order-row-field="inventory_movement_id" value="' + escapeHtml(normalized.inventory_movement_id) + '">'
          + '<input type="hidden" data-repair-order-row-field="inventory_unit" value="' + escapeHtml(normalized.inventory_unit) + '">'
        : '';
      return '<tr data-repair-order-row="' + escapeHtml(section) + '" data-repair-order-total-raw="' + escapeHtml(normalized.total) + '" data-repair-order-work-executor-id="' + escapeHtml(normalized.work_executor_id_snapshot) + '" data-repair-order-work-executor-name="' + escapeHtml(normalized.work_executor_name_snapshot) + '" data-repair-order-work-quantity="' + escapeHtml(normalized.work_quantity_snapshot) + '" data-repair-order-work-price="' + escapeHtml(normalized.work_price_snapshot) + '" data-repair-order-work-total="' + escapeHtml(normalized.work_total_snapshot) + '" data-repair-order-salary-mode="' + escapeHtml(normalized.salary_mode_snapshot) + '" data-repair-order-base-salary="' + escapeHtml(normalized.base_salary_snapshot) + '" data-repair-order-work-percent="' + escapeHtml(normalized.work_percent_snapshot) + '" data-repair-order-salary-amount="' + escapeHtml(normalized.salary_amount) + '" data-repair-order-salary-accrued-at="' + escapeHtml(normalized.salary_accrued_at) + '" data-repair-order-work-salary-override-enabled="' + escapeHtml(normalized.work_salary_override_enabled) + '" data-repair-order-work-salary-guarantee="' + escapeHtml(normalized.work_salary_guarantee) + '" data-repair-order-work-salary-percent-override="' + escapeHtml(normalized.work_salary_percent_override) + '" data-repair-order-work-salary-cost-price="' + escapeHtml(normalized.work_salary_cost_price) + '" data-repair-order-work-salary-note="' + escapeHtml(normalized.work_salary_note) + '" data-repair-order-material-executor-id="' + escapeHtml(normalized.material_executor_id_snapshot) + '" data-repair-order-material-executor-name="' + escapeHtml(normalized.material_executor_name_snapshot) + '" data-repair-order-material-quantity="' + escapeHtml(normalized.material_quantity_snapshot) + '" data-repair-order-material-price="' + escapeHtml(normalized.material_price_snapshot) + '" data-repair-order-material-cost-price="' + escapeHtml(normalized.material_cost_price_snapshot) + '" data-repair-order-material-percent="' + escapeHtml(normalized.material_percent_snapshot) + '" data-repair-order-material-profit="' + escapeHtml(normalized.material_profit) + '" data-repair-order-material-salary-amount="' + escapeHtml(normalized.material_salary_amount) + '" data-repair-order-material-salary-accrued-at="' + escapeHtml(normalized.material_salary_accrued_at) + '">' +
        '<td>' + inventoryHiddenFields + repairOrderRowInputHtml('name', normalized.name, 'Наименование') + '</td>' +
        materialExecutorCell +
        catalogCell +
        executorCell +
        '<td class="repair-order-table__numeric">' + repairOrderRowInputHtml('quantity', normalized.quantity, '1') + '</td>' +
        materialCostCell +
        '<td class="repair-order-table__numeric">' + repairOrderRowInputHtml('price', normalized.price, '0') + '</td>' +
        '<td class="repair-order-table__numeric"><div class="repair-order-cell-total" data-repair-order-row-total data-empty="' + (hasDisplayTotal ? 'false' : 'true') + '">' + escapeHtml(hasDisplayTotal ? repairOrderFormatRubles(totalValue ?? normalized.total) : '-') + '</div></td>' +
        '<td class="repair-order-table__action"><button class="btn btn--ghost repair-order-row-remove" type="button" data-remove-repair-order-row="' + escapeHtml(section) + '" data-row-index="' + escapeHtml(index) + '">&times;</button></td>' +
        '</tr>';
    }

    function readRepairOrderRowElement(row) {
      const executorSelect = row.querySelector('[data-repair-order-cell="executor_id"]');
      const selectedOption = executorSelect instanceof HTMLSelectElement ? executorSelect.options[executorSelect.selectedIndex] : null;
      const quantityValue = row.querySelector('[data-repair-order-cell="quantity"]')?.value;
      const priceValue = row.querySelector('[data-repair-order-cell="price"]')?.value;
      const quantityParsed = repairOrderParseNumber(quantityValue);
      const priceParsed = repairOrderParseNumber(priceValue);
      const effectiveQuantity = quantityParsed === null && !String(quantityValue ?? '').trim() ? 1 : quantityParsed;
      const existingTotalRaw = row.dataset.repairOrderTotalRaw || '';
      const liveTotalValue = effectiveQuantity !== null && priceParsed !== null
        ? repairOrderNumberToRaw(repairOrderResolvedRowTotalValue({
          quantity: repairOrderNumberToRaw(effectiveQuantity),
          price: priceValue,
          total: existingTotalRaw,
        }))
        : existingTotalRaw;
      return normalizeRepairOrderRow({
        name: row.querySelector('[data-repair-order-cell="name"]')?.value,
        catalog_number: row.querySelector('[data-repair-order-cell="catalog_number"]')?.value,
        quantity: quantityValue,
        cost_price: row.querySelector('[data-repair-order-cell="cost_price"]')?.value,
        price: priceValue,
        total: liveTotalValue,
        executor_id: executorSelect instanceof HTMLSelectElement ? executorSelect.value : '',
        executor_name: selectedOption ? selectedOption.textContent : '',
        work_executor_id_snapshot: row.dataset.repairOrderWorkExecutorId || '',
        work_executor_name_snapshot: row.dataset.repairOrderWorkExecutorName || '',
        work_quantity_snapshot: row.dataset.repairOrderWorkQuantity || '',
        work_price_snapshot: row.dataset.repairOrderWorkPrice || '',
        work_total_snapshot: row.dataset.repairOrderWorkTotal || '',
        salary_mode_snapshot: row.dataset.repairOrderSalaryMode || '',
        base_salary_snapshot: row.dataset.repairOrderBaseSalary || '',
        work_percent_snapshot: row.dataset.repairOrderWorkPercent || '',
        salary_amount: row.dataset.repairOrderSalaryAmount || '',
        salary_accrued_at: row.dataset.repairOrderSalaryAccruedAt || '',
        work_salary_override_enabled: row.dataset.repairOrderWorkSalaryOverrideEnabled || '',
        work_salary_guarantee: row.dataset.repairOrderWorkSalaryGuarantee || '',
        work_salary_percent_override: row.dataset.repairOrderWorkSalaryPercentOverride || '',
        work_salary_cost_price: row.dataset.repairOrderWorkSalaryCostPrice || '',
        work_salary_note: row.dataset.repairOrderWorkSalaryNote || '',
        material_executor_id_snapshot: row.dataset.repairOrderMaterialExecutorId || '',
        material_executor_name_snapshot: row.dataset.repairOrderMaterialExecutorName || '',
        material_quantity_snapshot: row.dataset.repairOrderMaterialQuantity || '',
        material_price_snapshot: row.dataset.repairOrderMaterialPrice || '',
        material_cost_price_snapshot: row.dataset.repairOrderMaterialCostPrice || '',
        material_percent_snapshot: row.dataset.repairOrderMaterialPercent || '',
        material_profit: row.dataset.repairOrderMaterialProfit || '',
        material_salary_amount: row.dataset.repairOrderMaterialSalaryAmount || '',
        material_salary_accrued_at: row.dataset.repairOrderMaterialSalaryAccruedAt || '',
        inventory_item_id: row.querySelector('[data-repair-order-row-field="inventory_item_id"]')?.value || '',
        inventory_movement_id: row.querySelector('[data-repair-order-row-field="inventory_movement_id"]')?.value || '',
        inventory_unit: row.querySelector('[data-repair-order-row-field="inventory_unit"]')?.value || '',
      });
    }

    function readRepairOrderRows(section) {
      const body = repairOrderRowsBody(section);
      return Array.from(body.querySelectorAll('tr[data-repair-order-row]')).map((row) => readRepairOrderRowElement(row)).filter(repairOrderRowHasAnyData);
    }

    function repairOrderEmployeeById(employeeId) {
      const normalizedId = String(employeeId || '').trim();
      if (!normalizedId) return null;
      return (Array.isArray(state.employees) ? state.employees : []).find((item) => String(item?.id || '').trim() === normalizedId) || null;
    }

    function operatorDefaultMaterialExecutor() {
      const employeeId = String(state.operatorProfile?.user?.employee_id || '').trim();
      const employee = repairOrderEmployeeById(employeeId);
      if (!employee || !employee.is_active) return {};
      return {
        executor_id: String(employee.id || '').trim(),
        executor_name: String(employee.name || '').trim(),
      };
    }

    function repairOrderWorkSalaryPercentForRow(rowData) {
      const overrideEnabled = repairOrderNormalizeBool(rowData?.work_salary_override_enabled || '') === 'true';
      const rawOverridePercent = rowData?.work_salary_percent_override ?? '';
      if (overrideEnabled) return repairOrderNormalizePercentRaw(rawOverridePercent || '0') || '0';
      const employee = repairOrderEmployeeById(rowData?.executor_id || '');
      return repairOrderNormalizePercentRaw(employee?.work_percent || '');
    }

    function repairOrderWorkSalaryPreview(rowData, guaranteeValue = null, percentValue = null, costPriceValue = null) {
      const normalized = normalizeRepairOrderRow(rowData || {});
      const total = repairOrderResolvedRowTotalValue(normalized) ?? 0;
      const guarantee = repairOrderParseNumber(guaranteeValue ?? normalized.work_salary_guarantee) ?? 0;
      const percent = repairOrderParseNumber(percentValue ?? repairOrderWorkSalaryPercentForRow(normalized)) ?? 0;
      const costPrice = repairOrderParseNumber(costPriceValue ?? normalized.work_salary_cost_price) ?? 0;
      const safeGuarantee = Math.max(guarantee, 0);
      const safePercent = Math.min(Math.max(percent, 0), 100);
      const safeCostPrice = Math.max(costPrice, 0);
      const percentBase = Math.max(total - safeGuarantee - safeCostPrice, 0);
      const accrued = safeGuarantee + (percentBase * safePercent / 100);
      return {
        total: repairOrderRoundMoney(total),
        guarantee: repairOrderRoundMoney(safeGuarantee),
        percent: repairOrderRoundMoney(safePercent),
        costPrice: repairOrderRoundMoney(safeCostPrice),
        percentBase: repairOrderRoundMoney(percentBase),
        servicePercent: repairOrderRoundMoney(100 - safePercent),
        accrued: repairOrderRoundMoney(accrued),
      };
    }

    function syncRepairOrderWorkSalaryGear(row) {
      if (!(row instanceof HTMLElement)) return;
      const gear = row.querySelector('[data-repair-order-work-salary-gear]');
      if (!(gear instanceof HTMLElement)) return;
      const active = repairOrderNormalizeBool(row.dataset.repairOrderWorkSalaryOverrideEnabled || '') === 'true';
      gear.classList.toggle('is-active', active);
      gear.setAttribute('aria-pressed', active ? 'true' : 'false');
    }

    function closeRepairOrderWorkSalaryPopover() {
      state.repairOrderWorkSalaryRow = null;
      if (!els.repairOrderWorkSalaryPopover) return;
      els.repairOrderWorkSalaryPopover.classList.remove('is-open');
      els.repairOrderWorkSalaryPopover.hidden = true;
    }

    function positionRepairOrderWorkSalaryPopover(anchor) {
      const popover = els.repairOrderWorkSalaryPopover;
      if (!popover || !(anchor instanceof HTMLElement)) return;
      const rect = anchor.getBoundingClientRect();
      const width = Math.min(380, Math.max(260, window.innerWidth - 24));
      popover.style.width = width + 'px';
      popover.style.left = '12px';
      popover.style.top = '12px';
      const measured = popover.getBoundingClientRect();
      const popoverWidth = measured.width || width;
      const popoverHeight = measured.height || 260;
      const left = Math.min(Math.max(rect.right - popoverWidth, 12), window.innerWidth - popoverWidth - 12);
      let top = rect.bottom + 6;
      if (top + popoverHeight > window.innerHeight - 12) {
        top = Math.max(12, rect.top - popoverHeight - 6);
      }
      popover.style.left = Math.round(left) + 'px';
      popover.style.top = Math.round(top) + 'px';
    }

    function syncRepairOrderWorkSalaryPopoverPreview() {
      const row = state.repairOrderWorkSalaryRow;
      if (!(row instanceof HTMLElement)) return;
      const rowData = readRepairOrderRowElement(row);
      const preview = repairOrderWorkSalaryPreview(
        rowData,
        els.repairOrderWorkSalaryGuarantee?.value || '',
        els.repairOrderWorkSalaryPercent?.value || '',
        els.repairOrderWorkSalaryCostPrice?.value || ''
      );
      if (els.repairOrderWorkSalaryTotal) els.repairOrderWorkSalaryTotal.textContent = repairOrderFormatRubles(preview.total);
      if (els.repairOrderWorkSalaryCostPreview) els.repairOrderWorkSalaryCostPreview.textContent = repairOrderFormatRubles(preview.costPrice);
      if (els.repairOrderWorkSalaryServicePercent) els.repairOrderWorkSalaryServicePercent.textContent = repairOrderNumberToRaw(preview.servicePercent) + '%';
      if (els.repairOrderWorkSalaryAmount) els.repairOrderWorkSalaryAmount.textContent = repairOrderFormatRubles(preview.accrued);
    }

    function openRepairOrderWorkSalaryPopover(button) {
      const row = button?.closest?.('tr[data-repair-order-row]');
      if (!(row instanceof HTMLElement)) return;
      const rowData = readRepairOrderRowElement(row);
      state.repairOrderWorkSalaryRow = row;
      if (els.repairOrderWorkSalaryTitle) {
        els.repairOrderWorkSalaryTitle.textContent = rowData.name || 'РАБОТА БЕЗ НАЗВАНИЯ';
      }
      if (els.repairOrderWorkSalaryMeta) {
        els.repairOrderWorkSalaryMeta.textContent = rowData.executor_name ? ('ИСПОЛНИТЕЛЬ: ' + rowData.executor_name) : 'ИСПОЛНИТЕЛЬ НЕ ВЫБРАН';
      }
      if (els.repairOrderWorkSalaryGuarantee) {
        els.repairOrderWorkSalaryGuarantee.value = rowData.work_salary_guarantee || '';
      }
      if (els.repairOrderWorkSalaryPercent) {
        els.repairOrderWorkSalaryPercent.value = repairOrderWorkSalaryPercentForRow(rowData);
      }
      if (els.repairOrderWorkSalaryCostPrice) {
        els.repairOrderWorkSalaryCostPrice.value = rowData.work_salary_cost_price || '';
      }
      if (els.repairOrderWorkSalaryPopover) {
        els.repairOrderWorkSalaryPopover.hidden = false;
        els.repairOrderWorkSalaryPopover.classList.add('is-open');
        syncRepairOrderWorkSalaryPopoverPreview();
        positionRepairOrderWorkSalaryPopover(button);
      }
      els.repairOrderWorkSalaryGuarantee?.focus?.({ preventScroll: true });
    }

    function applyRepairOrderWorkSalaryPopover() {
      const row = state.repairOrderWorkSalaryRow;
      if (!(row instanceof HTMLElement)) return;
      const guarantee = repairOrderNormalizeNonNegativeRaw(els.repairOrderWorkSalaryGuarantee?.value || '');
      const percent = repairOrderNormalizePercentRaw(els.repairOrderWorkSalaryPercent?.value || '');
      const costPrice = repairOrderNormalizeNonNegativeRaw(els.repairOrderWorkSalaryCostPrice?.value || '');
      row.dataset.repairOrderWorkSalaryOverrideEnabled = 'true';
      row.dataset.repairOrderWorkSalaryGuarantee = guarantee || '0';
      row.dataset.repairOrderWorkSalaryPercentOverride = percent || '0';
      row.dataset.repairOrderWorkSalaryCostPrice = costPrice || '0';
      row.dataset.repairOrderSalaryAmount = '';
      row.dataset.repairOrderSalaryAccruedAt = '';
      syncRepairOrderWorkSalaryGear(row);
      closeRepairOrderWorkSalaryPopover();
      setStatus('НАСТРОЙКА НАЧИСЛЕНИЯ СТРОКИ СОХРАНЕНА В ЧЕРНОВИКЕ.', false);
    }

    function resetRepairOrderWorkSalaryOverride() {
      const row = state.repairOrderWorkSalaryRow;
      if (!(row instanceof HTMLElement)) return;
      row.dataset.repairOrderWorkSalaryOverrideEnabled = '';
      row.dataset.repairOrderWorkSalaryGuarantee = '';
      row.dataset.repairOrderWorkSalaryPercentOverride = '';
      row.dataset.repairOrderWorkSalaryCostPrice = '';
      row.dataset.repairOrderWorkSalaryNote = '';
      row.dataset.repairOrderSalaryAmount = '';
      row.dataset.repairOrderSalaryAccruedAt = '';
      syncRepairOrderWorkSalaryGear(row);
      closeRepairOrderWorkSalaryPopover();
      setStatus('ИНДИВИДУАЛЬНОЕ НАЧИСЛЕНИЕ СТРОКИ СБРОШЕНО.', false);
    }

    function syncRepairOrderSectionTotals(section) {
      const body = repairOrderRowsBody(section);
      let subtotal = 0;
      Array.from(body.querySelectorAll('tr[data-repair-order-row]')).forEach((row) => {
        const normalized = readRepairOrderRowElement(row);
        const totalValue = repairOrderResolvedRowTotalValue(normalized);
        const hasDisplayTotal = totalValue !== null || Boolean(normalized.total);
        row.dataset.repairOrderTotalRaw = normalized.total;
        const totalCell = row.querySelector('[data-repair-order-row-total]');
        if (totalCell) {
          totalCell.textContent = hasDisplayTotal ? repairOrderFormatRubles(totalValue ?? normalized.total) : '-';
          totalCell.dataset.empty = hasDisplayTotal ? 'false' : 'true';
        }
        subtotal += totalValue ?? (repairOrderParseNumber(normalized.total) ?? 0);
      });
      const roundedSubtotal = repairOrderRoundMoney(subtotal);
      document.querySelectorAll('[data-repair-order-total="' + section + '"]').forEach((node) => {
        node.textContent = repairOrderFormatRubles(roundedSubtotal);
      });
      return roundedSubtotal;
    }

    function syncRepairOrderTotals() {
      const worksTotal = syncRepairOrderSectionTotals('works');
      const materialsTotal = syncRepairOrderSectionTotals('materials');
      const subtotal = repairOrderRoundMoney(worksTotal + materialsTotal);
      syncRepairOrderPaymentMethodFromPayments();
      const summary = repairOrderSummaryValue(subtotal, state.repairOrderPayments);
      state.repairOrderSummary = summary;
      if (els.repairOrderPrepayment) {
        els.repairOrderPrepayment.value = repairOrderNumberToRaw(summary.total_paid);
      }
      document.querySelectorAll('[data-repair-order-total="subtotal"]').forEach((node) => {
        node.textContent = repairOrderFormatMoney(summary.base_total);
      });
      document.querySelectorAll('[data-repair-order-total="cashless_due"]').forEach((node) => {
        node.textContent = repairOrderFormatMoney(summary.noncash_due);
      });
      document.querySelectorAll('[data-repair-order-total="cash_due"]').forEach((node) => {
        node.textContent = repairOrderFormatMoney(summary.cash_due);
      });
      document.querySelectorAll('[data-repair-order-total="taxes"]').forEach((node) => {
        node.textContent = repairOrderFormatMoney(summary.taxes_and_fees);
      });
      document.querySelectorAll('[data-repair-order-total="prepayment"]').forEach((node) => {
        node.textContent = repairOrderFormatMoney(summary.total_paid);
      });
      document.querySelectorAll('[data-repair-order-total-block="taxes"]').forEach((node) => {
        node.classList.toggle('is-hidden', summary.taxes_and_fees === 0);
      });
      syncRepairOrderCloseButtonState();
    }

    function renderRepairOrderPayments({ syncTotals = true } = {}) {
      const payments = Array.isArray(state.repairOrderPayments) ? state.repairOrderPayments : [];
      const paymentMethod = syncRepairOrderPaymentMethodFromPayments();
      const subtotal = repairOrderRoundMoney(syncRepairOrderSectionTotals('works') + syncRepairOrderSectionTotals('materials'));
      const summary = repairOrderSummaryValue(subtotal, payments);
      const total = summary.total_paid;
      const due = summary.cash_due;
      if (els.repairOrderPaymentsMeta) {
        const latestPayment = payments.length ? payments[payments.length - 1] : null;
        const latestText = latestPayment
          ? ('Последняя оплата: ' + (String(latestPayment?.paid_at || '').trim() || 'дата не указана') + ' | Кем: ' + (String(latestPayment?.actor_name || '').trim() || 'оператор не указан') + ' | Касса: ' + (String(latestPayment?.cashbox_name || '').trim() || 'касса не указана'))
          : '';
        els.repairOrderPaymentsMeta.innerHTML =
          '<div class="repair-order-payments-stats">'
            + '<div class="repair-order-payments-stat"><span>Оплат:</span><strong>' + escapeHtml(String(payments.length)) + '</strong></div>'
            + '<div class="repair-order-payments-stat"><span>Внесено:</span><strong>' + escapeHtml(repairOrderFormatMoney(total)) + '</strong></div>'
            + '<div class="repair-order-payments-stat"><span>К доплате:</span><strong>' + escapeHtml(repairOrderFormatMoney(due)) + '</strong></div>'
          + '</div>'
          + (latestText ? '<div class="repair-order-payments-subline">' + escapeHtml(latestText) + '</div>' : '');
      }
      if (els.repairOrderPaymentsList) {
        els.repairOrderPaymentsList.innerHTML = payments.length ? payments.slice().reverse().map((item) => {
          const note = String(item?.note || '').trim() || 'Без комментария';
          const paidAt = String(item?.paid_at || '').trim() || 'Дата не указана';
          const method = repairOrderPaymentMethodLabel(item?.payment_method || 'cash');
          const actorName = String(item?.actor_name || '').trim() || 'Оператор не указан';
          const cashboxName = String(item?.cashbox_name || '').trim() || 'Касса не указана';
          const cashTransactionId = String(item?.cash_transaction_id || '').trim();
          const paymentStatus = item?._saving
            ? 'черновик'
            : (item?._error ? 'ошибка записи' : (cashTransactionId ? 'сохранено в кассу' : 'legacy без движения'));
          const serviceHint = cashTransactionId ? (' | CT ' + cashTransactionId.slice(0, 8)) : '';
          return '<div class="repair-order-payment-row">'
            + '<div class="repair-order-payment-row__badge">' + escapeHtml(method) + '</div>'
            + '<div class="repair-order-payment-row__body">'
              + '<div class="repair-order-payment-row__line">' + escapeHtml(note) + '</div>'
              + '<div class="repair-order-payment-row__subline">' + escapeHtml('Когда: ' + paidAt + ' | Кем: ' + actorName + ' | Касса: ' + cashboxName + ' | ' + paymentStatus + serviceHint) + '</div>'
            + '</div>'
            + '<div class="repair-order-payment-row__amount">' + escapeHtml(repairOrderFormatMoney(item?.amount ?? 0)) + '</div>'
            + '<button class="btn btn--ghost repair-order-payment-row__remove" type="button" data-remove-repair-order-payment="' + escapeHtml(item.id) + '" aria-label="Удалить оплату">&times;</button>'
            + '</div>';
        }).join('') : '<div class="cashboxes-empty">Оплат пока нет.</div>';
      }
      if (syncTotals) syncRepairOrderTotals();
    }

    async function openRepairOrderPaymentsModal() {
      ensureRepairOrderPaymentsModalUi();
      bindRepairOrderPaymentsUiEvents();
      try {
        await ensureRepairOrderPaymentCashboxes();
      } catch (error) {
        setStatus(error.message, true);
      }
      renderRepairOrderPayments();
      pushModal('repair-order-payments', els.repairOrderPaymentsModal, { parentKey: 'repair-order' });
      window.setTimeout(() => els.repairOrderPaymentAmount?.focus(), 0);
    }

    function closeRepairOrderPaymentsModal() {
      popModal('repair-order-payments');
      if (els.repairOrderPaymentAmount) els.repairOrderPaymentAmount.value = '';
      if (els.repairOrderPaymentNote) els.repairOrderPaymentNote.value = '';
    }

    async function deleteRepairOrderPayment(paymentId) {
      const normalizedPaymentId = String(paymentId || '').trim();
      if (!normalizedPaymentId) return;
      const previousPayments = (state.repairOrderPayments || []).slice();
      const nextPayments = previousPayments.filter((item) => String(item?.id || '').trim() !== normalizedPaymentId);
      if (nextPayments.length === previousPayments.length) return;
      state.repairOrderPayments = nextPayments;
      renderRepairOrderPayments();
      scheduleRepairOrderSaveDirtyStateSync();
      try {
        const persisted = await persistRepairOrderRecord({ silent: true });
        if (!persisted) {
          state.repairOrderPayments = previousPayments;
          renderRepairOrderPayments();
          scheduleRepairOrderSaveDirtyStateSync();
          return;
        }
        applyRepairOrderToForm(persisted.repairOrder);
        setStatus('Оплата удалена из заказ-наряда и кассы.', false);
      } catch (error) {
        state.repairOrderPayments = previousPayments;
        renderRepairOrderPayments();
        scheduleRepairOrderSaveDirtyStateSync();
        setStatus(String(error?.message || 'Не удалось удалить оплату из кассы.'), true);
      }
    }

    async function addRepairOrderPayment() {
      const amount = String(els.repairOrderPaymentAmount?.value || '').trim();
      const parsedAmount = repairOrderParseNumber(amount);
      const cashboxId = String(els.repairOrderPaymentCashbox?.value || '').trim();
      if (parsedAmount === null || parsedAmount <= 0) {
        setStatus('Укажите сумму оплаты.', true);
        els.repairOrderPaymentAmount?.focus();
        return;
      }
      if (!cashboxId) {
        setStatus('Выберите кассу для оплаты.', true);
        els.repairOrderPaymentCashbox?.focus();
        return;
      }
      const selectedCashbox = selectedRepairOrderPaymentCashbox();
      const paymentMethod = repairOrderPaymentMethodFromCashboxName(selectedCashbox?.name || '', 'cash');
      const payment = normalizeRepairOrderPayment(
        {
          id: 'payment-' + Date.now(),
          amount: repairOrderNumberToRaw(parsedAmount),
          paid_at: currentRepairOrderDateTime(),
          note: String(els.repairOrderPaymentNote?.value || '').trim(),
          payment_method: paymentMethod,
          actor_name: state.actor || '',
          cashbox_id: cashboxId,
          cashbox_name: selectedCashbox?.name || '',
        },
        'payment-' + Date.now()
      );
      payment._saving = true;
      state.repairOrderPayments = (state.repairOrderPayments || []).concat([payment]);
      syncRepairOrderPaymentMethodFromPayments();
      renderRepairOrderPayments();
      scheduleRepairOrderSaveDirtyStateSync();
      try {
        const persisted = await persistRepairOrderRecord({ silent: true });
        if (!persisted) {
          state.repairOrderPayments = (state.repairOrderPayments || []).filter((item) => item.id !== payment.id);
          renderRepairOrderPayments();
          scheduleRepairOrderSaveDirtyStateSync();
          return;
        }
        applyRepairOrderToForm(persisted.repairOrder);
        if (els.repairOrderPaymentAmount) els.repairOrderPaymentAmount.value = '';
        if (els.repairOrderPaymentNote) els.repairOrderPaymentNote.value = '';
        setStatus('Оплата сохранена в заказ-наряде и кассе.', false);
      } catch (error) {
        state.repairOrderPayments = (state.repairOrderPayments || []).filter((item) => item.id !== payment.id);
        renderRepairOrderPayments();
        scheduleRepairOrderSaveDirtyStateSync();
        setStatus(String(error?.message || 'Не удалось записать оплату в кассу.'), true);
      } finally {
        els.repairOrderPaymentAmount?.focus();
      }
    }

    function handleRepairOrderPaymentsListClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const removeButton = target.closest('[data-remove-repair-order-payment]');
      if (!removeButton) return;
      deleteRepairOrderPayment(removeButton.dataset.removeRepairOrderPayment);
    }

    function handleRepairOrderPaymentsFormChange(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      if (target === els.repairOrderPaymentCashbox) {
        renderRepairOrderPayments();
      }
    }

    function syncRepairOrderStatusUi(status, orderForClose = null) {
      const normalizedStatus = normalizeRepairOrderStatus(status);
      els.repairOrderStatus.textContent = repairOrderStatusLabel(normalizedStatus);
      els.repairOrderStatus.dataset.status = normalizedStatus;
      els.repairOrderCloseButton.textContent = normalizedStatus === 'closed' ? 'ОТКРЫТЬ ЗАКАЗ-НАРЯД' : 'ЗАКРЫТЬ ЗАКАЗ-НАРЯД';
      syncRepairOrderCloseButtonState(orderForClose ? { ...orderForClose, status: normalizedStatus } : {
        ...readRepairOrderFromForm(),
        status: normalizedStatus,
      });
    }

    function applyRepairOrderToForm(order) {
      const normalized = repairOrderCardDraft(state.activeCard, order);
      els.repairOrderNumber.textContent = normalized.number || '-';
      els.repairOrderNumber.dataset.value = normalized.number;
      els.repairOrderDate.value = repairOrderFormDateDisplayValue(normalized.date || currentRepairOrderDateTime());
      els.repairOrderOpenedAt.value = repairOrderFormDateDisplayValue(normalized.opened_at || normalized.date || currentRepairOrderDateTime());
      els.repairOrderClosedAt.value = repairOrderFormDateDisplayValue(normalized.closed_at);
      els.repairOrderClient.value = normalized.client;
      els.repairOrderPhone.value = normalized.phone;
      els.repairOrderVehicle.value = normalized.vehicle;
      els.repairOrderLicensePlate.value = normalized.license_plate;
      els.repairOrderVin.value = normalized.vin;
      els.repairOrderMileage.value = normalized.mileage;
      state.repairOrderPayments = normalizeRepairOrderPayments(normalized.payments, normalized.prepayment, normalized.opened_at || normalized.date);
      syncRepairOrderPaymentMethod(repairOrderPaymentMethodFromPayments(state.repairOrderPayments, normalized.payment_method));
      renderRepairOrderPaymentCashboxOptions('');
      if (els.repairOrderPrepayment) {
        els.repairOrderPrepayment.value = repairOrderNumberToRaw(repairOrderPaymentsTotalValue(state.repairOrderPayments));
      }
      els.repairOrderReason.value = normalized.reason;
      els.repairOrderComment.value = normalized.comment;
      els.repairOrderNote.value = normalized.note;
      state.repairOrderTags = normalizeRepairOrderTags(normalized.tags);
      state.repairOrderTagColor = state.repairOrderTags[0]?.color || 'green';
      renderRepairOrderTags();
      renderRepairOrderPayments({ syncTotals: false });
      renderRepairOrderRows('works', normalized.works, { syncTotals: false });
      renderRepairOrderRows('materials', normalized.materials, { syncTotals: false });
      const heading = repairOrderHeading(normalized.number);
      els.repairOrderModalTitle.innerHTML = repairOrderHeadingHtml(normalized.number);
      els.repairOrderModalTitle.title = heading;
      syncRepairOrderStatusUi(normalized.status, normalized);
      syncRepairOrderTotals();
      rememberRepairOrderModalCleanState(normalized);
    }

    function readRepairOrderFromForm() {
      const paymentMethod = repairOrderPaymentMethodFromPayments(state.repairOrderPayments, 'cash');
      syncRepairOrderPaymentMethod(paymentMethod);
      return normalizeRepairOrder({
        number: state.activeCard?.repair_order?.number || '',
        date: repairOrderCanonicalDateValue(els.repairOrderDate.value),
        status: els.repairOrderStatus.dataset.status || 'open',
        opened_at: repairOrderCanonicalDateValue(els.repairOrderOpenedAt.value),
        closed_at: repairOrderCanonicalDateValue(els.repairOrderClosedAt.value),
        client: els.repairOrderClient.value,
        phone: els.repairOrderPhone.value,
        vehicle: els.repairOrderVehicle.value,
        license_plate: els.repairOrderLicensePlate.value,
        vin: els.repairOrderVin.value,
        mileage: els.repairOrderMileage.value,
        payment_method: paymentMethod,
        prepayment: repairOrderNumberToRaw(repairOrderPaymentsTotalValue(state.repairOrderPayments)),
        payments: (state.repairOrderPayments || []).map((item, index) => normalizeRepairOrderPayment({
          ...item,
        }, item?.id || ('payment-' + (index + 1)))),
        reason: els.repairOrderReason.value,
        comment: els.repairOrderComment.value,
        client_information: els.repairOrderComment.value,
        note: els.repairOrderNote.value,
        tags: state.repairOrderTags,
        works: readRepairOrderRows('works'),
        materials: readRepairOrderRows('materials'),
      });
    }

    function refreshRepairOrderEntry(card = state.activeCard) {
      const currentCard = card || null;
      const order = repairOrderCardDraft(currentCard, currentCard?.repair_order || {});
      els.repairOrderButton.disabled = false;
      els.repairOrderButton.innerHTML = repairOrderHeadingHtml(order.number);
    }

    async function openRepairOrderModal({ preloadedRepairOrderData = null } = {}) {
      let order = repairOrderCardDraft(state.activeCard, preloadedRepairOrderData?.repair_order || state.activeCard?.repair_order || {});
      const cardId = String(state.activeCard?.id || state.editingId || '').trim();
      if (!state.repairOrderParentLayer && els.cardModal.classList.contains('is-open')) {
        state.repairOrderParentLayer = 'card';
      }
      pushModal('repair-order', els.repairOrderModal, { parentKey: state.repairOrderParentLayer || '' });
      applyRepairOrderToForm(order);

      const employeesRequest = loadEmployeesReference();
      const repairOrderRequest = preloadedRepairOrderData
        ? Promise.resolve(preloadedRepairOrderData)
        : cardId
        ? api('/api/get_repair_order', {
          method: 'POST',
          body: {
            card_id: cardId,
            actor_name: state.actor,
            source: 'ui',
            create_if_missing: true,
          },
        })
        : Promise.resolve(null);

      const [employeesResult, repairOrderResult] = await Promise.allSettled([employeesRequest, repairOrderRequest]);
      if (employeesResult.status === 'rejected' && employeesResult.reason) {
        setStatus(employeesResult.reason.message || String(employeesResult.reason), true);
      }
      if (cardId) {
        if (repairOrderResult.status !== 'fulfilled' || !repairOrderResult.value) {
          const error = repairOrderResult.status === 'rejected' ? repairOrderResult.reason : new Error('Не удалось загрузить заказ-наряд.');
          setStatus(error.message || String(error), true);
          return;
        }
        const data = repairOrderResult.value;
        const updatedCard = repairOrderResponseCard(data, order);
        order = applyRepairOrderCardUpdate(updatedCard, data?.repair_order || order);
      }
      applyRepairOrderToForm(order);
    }

    function closeRepairOrderModal() {
      const parentLayer = String(state.repairOrderParentLayer || '').trim();
      closeRepairOrderWorkSalaryPopover();
      closeRepairOrderPaymentsModal();
      popModal('repair-order');
      state.repairOrderParentLayer = '';
      syncRepairOrderSaveDirtyState();
      if (parentLayer === 'repair-orders') {
        resetCardModalState();
      }
    }

    async function addRepairOrderRow(section) {
      if (section === 'materials') {
        await loadEmployeesReference();
      }
      const body = repairOrderRowsBody(section);
      const rowIndex = body.querySelectorAll('tr[data-repair-order-row]').length;
      const defaults = section === 'materials' ? operatorDefaultMaterialExecutor() : {};
      body.insertAdjacentHTML('beforeend', repairOrderRowHtml(section, emptyRepairOrderRow(defaults), rowIndex));
      syncRepairOrderTotals();
      scheduleRepairOrderSaveDirtyStateSync();
      body.querySelector('tr:last-child input')?.focus();
    }

    function removeRepairOrderRow(section, rowIndex) {
      const rows = ensureRepairOrderRows(readRepairOrderRows(section));
      if (rowIndex >= 0 && rowIndex < rows.length) rows.splice(rowIndex, 1);
      renderRepairOrderRows(section, rows);
      scheduleRepairOrderSaveDirtyStateSync();
    }

    function repairOrdersModalIsOpen() {
      return Boolean(els.repairOrdersModal?.classList.contains('is-open'));
    }

    function invalidateRepairOrdersListCache() {
      if (state.repairOrdersLoadTimer) {
        window.clearTimeout(state.repairOrdersLoadTimer);
        state.repairOrdersLoadTimer = null;
      }
      setRepairOrdersSearchLoading(false);
      state.repairOrdersItems = [];
      state.repairOrdersMetaState = null;
    }

    async function refreshRepairOrdersListAfterMutation() {
      if (repairOrdersModalIsOpen()) {
        await loadRepairOrders(false);
        return;
      }
      invalidateRepairOrdersListCache();
    }

    async function persistRepairOrderRecord({ statusMessage = '', silent = false } = {}) {
      const cardId = await requireRepairOrderCardId();
      if (!cardId) return null;
      const repairOrder = readRepairOrderFromForm();
      const data = await api('/api/update_repair_order', {
        method: 'POST',
        body: {
          card_id: cardId,
          actor_name: state.actor,
          source: 'ui',
          repair_order: repairOrder,
        },
      });
      const updatedCard = repairOrderResponseCard(data, repairOrder);
      const nextOrder = applyRepairOrderCardUpdate(updatedCard, data?.repair_order || repairOrder);
      await refreshRepairOrdersListAfterMutation();
      await refreshCashboxesAfterMoneyMutation({ deferDetail: true });
      if (!silent && statusMessage) setStatus(statusMessage, false);
      return { cardId, repairOrder: nextOrder, card: updatedCard, data };
    }

    saveRepairOrder = async function(printAfter = false) {
      if (state.repairOrderSaveInFlight) return state.repairOrderSavePromise || false;
      state.repairOrderSaveInFlight = true;
      if (els.repairOrderSaveButton) els.repairOrderSaveButton.disabled = true;
      syncRepairOrderSaveDirtyState();
      const savePromise = perfMeasureAsync('saveRepairOrder', async () => {
        try {
          const persisted = await persistRepairOrderRecord({ statusMessage: 'Заказ-наряд сохранён.' });
          if (!persisted) return false;
          if (printAfter) setStatus('Печать будет добавлена позже. Заказ-наряд сохранён.', false);
          return true;
        } catch (error) {
          setStatus(error.message, true);
          return false;
        } finally {
          state.repairOrderSaveInFlight = false;
          state.repairOrderSavePromise = null;
          if (els.repairOrderSaveButton) els.repairOrderSaveButton.disabled = false;
          syncRepairOrderSaveDirtyState();
        }
      });
      state.repairOrderSavePromise = savePromise;
      return savePromise;
    };

    async function toggleRepairOrderStatus() {
      try {
        const persisted = await persistRepairOrderRecord({ silent: true });
        if (!persisted) return;
        const currentOrder = readRepairOrderFromForm();
        const currentStatus = currentOrder.status;
        const nextStatus = currentStatus === 'closed' ? 'open' : 'closed';
        if (nextStatus === 'closed' && !repairOrderIsFullyPaid(currentOrder)) {
          setStatus(repairOrderCloseBlockedMessage(), true);
          return;
        }
        els.repairOrderCloseButton.disabled = true;
        const data = await api('/api/set_repair_order_status', {
          method: 'POST',
          body: {
            card_id: persisted.cardId,
            status: nextStatus,
            actor_name: state.actor,
            source: 'ui',
          },
        });
        const updatedCard = repairOrderResponseCard(data, persisted.repairOrder);
        applyRepairOrderCardUpdate(updatedCard, data?.repair_order || persisted.repairOrder);
        await loadRepairOrders(false);
        setStatus(nextStatus === 'closed' ? 'Заказ-наряд закрыт.' : 'Заказ-наряд открыт.', false);
      } catch (error) {
        setStatus(error.message, true);
      } finally {
        syncRepairOrderCloseButtonState();
      }
    }

    function columnLabelById(columnId) {
      const found = (state.snapshot?.columns || []).find((column) => column.id === columnId);
      return found?.label || String(columnId || '—');
    }

    function renderCardCleanupIndicator() {
      if (!(els.cardAgentButton instanceof HTMLElement)) return;
      const currentState = String(state.cardCleanupState || 'idle').trim().toLowerCase();
      const uiState = currentState === 'running'
        ? 'busy'
        : (currentState === 'error' ? 'error' : (state.activeCard?.id ? 'online' : 'idle'));
      let title = 'Индикатор карточки';
      if (currentState === 'running') {
        title = 'Индикатор карточки · выполняется';
      } else if (currentState === 'error') {
        title = state.cardCleanupError
          ? 'Индикатор карточки · ошибка: ' + String(state.cardCleanupError || '').trim()
          : 'Индикатор карточки · ошибка';
      } else if (state.activeCard?.id) {
        title = 'Индикатор карточки · готово';
      }
      els.cardAgentButton.dataset.state = uiState;
      els.cardAgentButton.title = title;
      els.cardAgentButton.setAttribute('aria-label', title);
      els.cardAgentButton.disabled = currentState === 'running' || !state.activeCard?.id;
    }

    function stopCardCleanupPolling() {
      if (state.cardCleanupPollTimer) {
        window.clearTimeout(state.cardCleanupPollTimer);
        state.cardCleanupPollTimer = null;
      }
    }

    function scheduleCardCleanupPolling(delay = 1500) {
      stopCardCleanupPolling();
      if (!state.agentTaskId) return;
      state.cardCleanupPollTimer = window.setTimeout(refreshCardCleanupState, delay);
    }

    async function refreshCardCleanupState() {
      stopCardCleanupPolling();
      const card = state.activeCard && typeof state.activeCard === 'object'
        ? state.activeCard
        : currentAgentContextCard();
      const cardId = String(card?.id || '').trim();
      const taskId = String(state.agentTaskId || '').trim();
      if (!cardId || !taskId) {
        state.cardCleanupState = cardId ? 'idle' : 'idle';
        renderCardCleanupIndicator();
        return;
      }
      try {
        const data = await api('/api/agent_tasks?limit=20');
        const tasks = Array.isArray(data?.tasks) ? data.tasks : [];
        const task = tasks.find((item) => String(item?.id || '').trim() === taskId)
          || tasks.find((item) => {
            const metadata = item?.metadata && typeof item.metadata === 'object' ? item.metadata : {};
            const context = metadata.context && typeof metadata.context === 'object' ? metadata.context : {};
            return String(metadata.purpose || '').trim().toLowerCase() === 'card_enrichment'
              && String(context.card_id || '').trim() === cardId;
          })
          || null;
        if (!task) {
          state.cardCleanupState = 'running';
          renderCardCleanupIndicator();
          scheduleCardCleanupPolling(2500);
          return;
        }
        const status = String(task.status || '').trim().toLowerCase();
        state.agentTaskStatus = status;
        if (status === 'pending' || status === 'running') {
          state.cardCleanupState = 'running';
          renderCardCleanupIndicator();
          scheduleCardCleanupPolling(1500);
          return;
        }
        if (status === 'completed') {
          state.cardCleanupState = 'idle';
          renderCardCleanupIndicator();
          await syncAgentTaskEffects(task);
          return;
        }
        state.cardCleanupState = 'error';
        state.cardCleanupError = task.error || task.result || task.summary || 'AI-обогащение завершилось с ошибкой.';
        renderCardCleanupIndicator();
        await syncAgentTaskEffects(task);
      } catch (error) {
        state.cardCleanupState = 'error';
        state.cardCleanupError = error.message;
        renderCardCleanupIndicator();
        scheduleCardCleanupPolling(6000);
      }
    }

    function applyCardModalState(card, { descriptionLoading = false, cardIsFull = true, preserveLazyPanels = false } = {}) {
      const perfToken = perfStart('hydrateCard');
      const previousCardId = String(state.activeCard?.id || '').trim();
      const currentCard = card || null;
      const nextCardId = String(currentCard?.id || '').trim();
      state.activeCard = currentCard;
      state.activeCardIsFull = Boolean(cardIsFull || !nextCardId);
      state.editingId = currentCard?.id || null;
      state.cardCreateColumnId = currentCard?.id ? '' : String(currentCard?.column || state.snapshot?.columns?.[0]?.id || 'inbox').trim();
      if (!preserveLazyPanels || previousCardId !== nextCardId) {
        state.cardJournalLoadedFor = '';
        state.cardJournalLimit = CARD_JOURNAL_INITIAL_LIMIT;
        state.cardFilesRenderedFor = '';
      }
      state.pendingCardClientId = currentCard?.client_id || '';
      state.pendingCardClientVehicleId = currentCard?.client_vehicle_id || '';
      state.pendingCreateClientVehicleFromCard = false;
      state.draftTags = normalizeDraftTags(currentCard?.tag_items || currentCard?.tags || []);
      state.draftTagColor = 'green';
      const modalHeading = currentCard?.id ? cardModalHeading(currentCard) : 'Новая карточка';
      els.cardModalTitle.textContent = limitCardModalHeading(modalHeading);
      els.cardModalTitle.title = modalHeading;
      els.cardVehicle.value = currentCard?.vehicle || '';
      els.cardTitle.value = currentCard?.title || '';
      const parts = secondsToParts(currentCard?.remaining_seconds ?? 86400);
      els.signalDays.value = parts.days;
      els.signalHours.value = parts.hours;
      renderSignalPreview();
      const archiveAvailable = cardArchiveAvailability(currentCard);
      els.archiveAction.classList.toggle('hidden', !currentCard?.id || currentCard.archived);
      els.archiveAction.disabled = !archiveAvailable;
      els.archiveAction.dataset.archiveAvailable = archiveAvailable ? 'true' : 'false';
      els.archiveAction.title = archiveAvailable ? '' : cardArchiveUnavailableTitle(currentCard);
      els.restoreAction.classList.toggle('hidden', !currentCard?.id || !currentCard.archived);
      state.vehicleProfileBaseline = cloneVehicleProfile(currentCard?.vehicle_profile || {});
      applyVehicleProfileToForm(currentCard?.vehicle_profile || emptyVehicleProfile());
      hideClientSuggestions();
      if (currentCard?.id && !currentCard?.client_id) scheduleClientSuggestionsForCard();
      refreshRepairOrderEntry(currentCard);
      renderColorTags();
      if (!preserveLazyPanels || previousCardId !== nextCardId) renderLogs([]);
      if (descriptionLoading) {
        setCardDescriptionLoading(true);
      } else {
        setCardDescriptionValue(currentCard?.description || '');
      }
      if (!currentCard?.id) {
        renderFiles(currentCard);
      } else if (state.currentTab === 'files') {
        renderActiveCardFiles();
      } else {
        renderCardFilesPlaceholder(currentCard, 'ФАЙЛЫ ЗАГРУЗЯТСЯ ПРИ ОТКРЫТИИ ВКЛАДКИ.');
      }
      if (state.currentTab === 'journal') loadActiveCardTab('journal');
      if (state.cardCleanupState !== 'error') {
        state.cardCleanupState = currentCard?.id ? 'idle' : 'idle';
        state.cardCleanupError = '';
      }
      if (!String(state.agentTaskId || '').trim()) stopCardCleanupPolling();
      renderCardCleanupIndicator();
      if (els.cardModal?.classList.contains('is-open')) {
        requestAnimationFrame(() => syncCardDescriptionHeight());
      }
      rememberCardModalCleanState();
      syncCardSaveDirtyState();
      perfEnd(perfToken, { card_id: nextCardId, full: state.activeCardIsFull, description_loading: Boolean(descriptionLoading) });
    }

    function resetCardModalState() {
      state.activeCard = null;
      state.activeCardIsFull = false;
      state.editingId = null;
      state.cardCreateColumnId = '';
      state.cardSaveInFlight = false;
      state.cardSavePromise = null;
      state.cardCloseAfterSave = false;
      state.cardInitialPayloadKey = '';
      state.cardDescriptionLoading = false;
      state.cardHydratingId = '';
      state.cardJournalLoadedFor = '';
      state.cardJournalLimit = CARD_JOURNAL_INITIAL_LIMIT;
      state.cardFilesRenderedFor = '';
      clearCardOpenSideEffectTimer();
      state.vehicleProfileDraft = null;
      state.vehicleProfileBaseline = null;
      state.pendingCardClientId = '';
      state.pendingCardClientVehicleId = '';
      state.pendingCreateClientVehicleFromCard = false;
      state.cardClientCreateSaving = false;
      hideClientSuggestions();
      state.draftTags = [];
      state.draftTagColor = 'green';
      state.cardCleanupState = 'idle';
      state.cardCleanupError = '';
      stopCardCleanupPolling();
      refreshRepairOrderEntry(null);
      syncCardSaveDirtyState();
      els.fileInput.value = '';
      clearFilePreview({ sync: false });
      syncFileDropzone(null);
      syncFilePreview(null);
      renderCardCleanupIndicator();
    }

    async function persistCardPayload(payload) {
      let data;
      if (state.editingId) {
        data = await api('/api/update_card', { method: 'POST', body: { card_id: state.editingId, ...payload } });
      } else {
        data = await api('/api/create_card', { method: 'POST', body: payload });
      }
      const cardId = data?.card?.id || state.editingId || '';
      if (cardId && state.pendingCardClientId && data?.card?.client_id !== state.pendingCardClientId) {
        return api('/api/link_card_to_client', {
          method: 'POST',
          body: {
            card_id: cardId,
            client_id: state.pendingCardClientId,
            client_vehicle_id: state.pendingCardClientVehicleId || '',
            create_vehicle_from_card: Boolean(state.pendingCreateClientVehicleFromCard),
            sync_vehicle_fields: true,
            sync_fields: true,
            overwrite_card_fields: false,
          },
        });
      }
      return data;
    }

    function formatIndicatorLabel(value) {
      return ({ green: 'зелёный', yellow: 'жёлтый', red: 'красный' }[String(value || '').toLowerCase()] || String(value || '—'));
    }

    function formatSourceLabel(value) {
      return ({ ui: '', mcp: 'через GPT', api: 'через API', system: 'системой' }[String(value || '').toLowerCase()] || String(value || ''));
    }

    function formatBytes(value) {
      const size = finiteNonNegativeNumber(value);
      if (size >= 1024 * 1024) return (size / (1024 * 1024)).toFixed(1) + ' МБ';
      if (size >= 1024) return Math.round(size / 1024) + ' КБ';
      return size + ' Б';
    }

    function describeValue(value, key = '') {
      if (Array.isArray(value)) return value.length ? value.join(', ') : '—';
      if (value === null || value === undefined || value === '') return '—';
      if (String(key).includes('column')) return columnLabelById(value);
      if (String(key).includes('indicator')) return formatIndicatorLabel(value);
      if (String(key).includes('size_bytes')) return formatBytes(value);
      if (String(key).includes('total_seconds')) return durationToFull(value);
      if (String(key).includes('timestamp')) return formatDate(value);
      return String(value).replace(/\s+/g, ' ').trim();
    }

    function formatLogDetails(event) {
      const details = event.details || {};
      const lines = [];
      const push = (label, value, kind = '', { showEmpty = false } = {}) => {
        const text = describeValue(value, kind || label);
        if (!showEmpty && (text === '—' || text === '')) return;
        lines.push(label + ' ' + text);
      };

      if (event.action === 'card_created') {
        if (details.vehicle) push('машина', details.vehicle);
        if (details.column) push('столбец', details.column);
        if (details.tags) push('метки', details.tags);
        if (details.deadline_total_seconds !== undefined) push('сигнал', details.deadline_total_seconds, 'deadline_total_seconds');
      } else if (event.action === 'card_moved') {
        if (details.before_column) push('из', details.before_column);
        if (details.after_column) push('в', details.after_column);
      } else if (event.action === 'card_archived' || event.action === 'card_restored') {
        if (details.column) push('столбец', details.column);
      } else if (event.action === 'vehicle_changed') {
        push('автомобиль', details.after, '', { showEmpty: true });
      } else if (event.action === 'title_changed' || event.action === 'description_changed') {
        push(event.action === 'description_changed' ? 'описание' : 'заголовок', details.after, '', { showEmpty: true });
      } else if (event.action === 'signal_changed') {
        push('сигнал', details.after_total_seconds, 'after_total_seconds', { showEmpty: true });
      } else if (event.action === 'signal_indicator_changed') {
        push('индикатор', details.after_indicator, 'after_indicator', { showEmpty: true });
        if (details.deadline_total_seconds !== undefined) push('сигнал', details.deadline_total_seconds, 'deadline_total_seconds');
      } else if (event.action === 'attachment_added' || event.action === 'attachment_removed') {
        if (details.file_name) push('файл', details.file_name);
        if (details.size_bytes !== undefined) push('размер', details.size_bytes, 'size_bytes');
      } else if (event.action === 'tag_added' || event.action === 'tag_removed') {
        if (details.tag) push('метка', details.tag);
      } else if (event.action === 'tags_changed') {
        push('метки', details.after, '', { showEmpty: true });
      } else {
        Object.entries(details).forEach(([key, value]) => push(key.replace(/_/g, ' '), value));
      }

      return lines.join(' | ');
    }

    function buildCardJournalFallbackText(events) {
      const list = Array.isArray(events) ? events : [];
      if (!list.length) return 'ЗАПИСЕЙ НЕТ.';
      return list.map((event) => {
        const head = [
          formatDate(event.timestamp),
          event.actor_name || 'СИСТЕМА',
          event.message || 'Событие',
        ].filter(Boolean).join(' | ');
        const details = formatLogDetails(event);
        return details ? head + '\n  ' + details : head;
      }).join('\n\n');
    }

    function renderTags() {
      els.tagList.innerHTML = state.draftTags.length
        ? state.draftTags.map((tag) => '<button class="tag" data-remove-tag="' + escapeHtml(tag) + '">' + escapeHtml(tag) + ' ?</button>').join('')
        : '<div class="tag tag--muted">МЕТОК НЕТ</div>';
      els.tagSuggestions.innerHTML = SUGGESTED_TAGS.map((tag) => {
        const active = state.draftTags.includes(tag.label);
        const toneClass = tag.tone === 'danger' ? ' tag-suggestion--danger' : '';
        const activeClass = active ? ' is-active' : '';
        return '<button class="tag-suggestion' + toneClass + activeClass + '" data-suggest-tag="' + escapeHtml(tag.label) + '">' + escapeHtml(tag.label) + '</button>';
      }).join('');
    }

    function renderColorTags() {
      const atLimit = state.draftTags.length >= CARD_TAG_LIMIT;
      renderTagColorPicker();
      els.tagList.innerHTML = state.draftTags.length
        ? state.draftTags.map((tag) => '<button class="tag" data-tag-color="' + escapeHtml(tag.color) + '" data-remove-tag="' + escapeHtml(tag.label) + '"><span class="tag__dot"></span>' + escapeHtml(tag.label) + ' ?</button>').join('')
        : '<div class="tag tag--muted">МЕТОК НЕТ</div>';
      if (els.tagMeta) {
        els.tagMeta.textContent = state.draftTags.length + ' / ' + CARD_TAG_LIMIT;
        els.tagMeta.dataset.limitState = atLimit ? 'full' : 'open';
      }
      els.tagInput.disabled = atLimit;
      els.tagInput.placeholder = atLimit ? 'ЛИМИТ 3 / 3' : 'ЖДЁМ';
      els.tagAddButton.disabled = atLimit;
      els.tagSuggestions.innerHTML = SUGGESTED_TAGS.map((tag) => {
        const active = state.draftTags.some((item) => item.label === tag.label);
        const disabled = atLimit && !active;
        const activeClass = active ? ' is-active' : '';
        const disabledClass = disabled ? ' is-disabled' : '';
        const disabledAttr = disabled ? ' disabled' : '';
        return '<button class="tag-suggestion' + activeClass + disabledClass + '" data-tag-color="' + escapeHtml(tag.color || 'green') + '" data-suggest-tag="' + escapeHtml(tag.label) + '" data-suggest-color="' + escapeHtml(tag.color || 'green') + '"' + disabledAttr + '>' + escapeHtml(tag.label) + '</button>';
      }).join('');
    }

    function syncFileDropzone(card = state.activeCard) {
      const canUpload = Boolean(card?.id || state.editingId);
      els.fileDropzone.classList.toggle('is-disabled', !canUpload);
      els.fileDropzone.classList.remove('is-active');
      els.fileDropzone.setAttribute('aria-disabled', canUpload ? 'false' : 'true');
      els.fileDropzone.setAttribute('contenteditable', canUpload ? 'plaintext-only' : 'false');
      els.fileDropzone.dataset.title = canUpload ? 'ПЕРЕНЕСИТЕ ИЛИ ВСТАВЬТЕ ФАЙЛ' : 'СНАЧАЛА СОХРАНИТЕ КАРТОЧКУ';
      els.fileDropzone.dataset.hint = canUpload
        ? 'Ctrl+V, правый клик -> Вставить, drag-and-drop или клик для выбора. PNG, JPG, JPEG, WEBP, GIF, TXT, PDF, Word, Excel.'
        : 'Без сохранённой карточки вложения не принимаются.';
      els.fileDropzone.textContent = '';
    }

    function attachmentDownloadPath(cardId, attachmentId) {
      return '/api/attachment?card_id=' + encodeURIComponent(String(cardId || '').trim()) + '&attachment_id=' + encodeURIComponent(String(attachmentId || '').trim());
    }

    function findCardAttachment(card, attachmentId) {
      const attachments = Array.isArray(card?.attachments) ? card.attachments : [];
      const targetId = String(attachmentId || '').trim();
      if (!targetId) return null;
      return attachments.find((item) => String(item?.id || '').trim() === targetId && !item?.removed) || null;
    }

    function attachmentExistsOnDisk(attachment) {
      if (!attachment || typeof attachment !== 'object' || attachment.removed) return false;
      return attachment.exists_on_disk !== false;
    }

    function attachmentIsPreviewable(attachment) {
      if (!attachment || typeof attachment !== 'object' || attachment.removed) return false;
      if (!attachmentExistsOnDisk(attachment)) return false;
      const mimeType = normalizeAttachmentMimeType(attachment.mime_type || attachment.type || '');
      if (mimeType.startsWith('image/')) return true;
      return ATTACHMENT_PREVIEWABLE_EXTENSIONS.has(attachmentExtension(attachment.file_name || attachment.name || ''));
    }

    function renderAttachmentThumbnailHtml(attachment, downloadUrl) {
      if (!attachmentExistsOnDisk(attachment)) {
        return '<div class="file-row__thumb"><div class="file-row__thumb-fallback">ФАЙЛ<br>НЕ НАЙДЕН</div></div>';
      }
      if (!attachmentIsPreviewable(attachment)) {
        return '<div class="file-row__thumb"><div class="file-row__thumb-fallback">ФАЙЛ</div></div>';
      }
      const fileName = String(attachment?.file_name || attachment?.name || 'Вложение').trim() || 'Вложение';
      const previewUrl = withAccessToken(downloadUrl);
      return '<div class="file-row__thumb"><button class="file-row__thumb-button" type="button" data-preview-file="' + escapeHtml(attachment.id) + '" title="Открыть просмотр: ' + escapeHtml(fileName) + '"><img class="file-row__thumb-image" src="' + escapeHtml(previewUrl) + '" alt="Миниатюра файла ' + escapeHtml(fileName) + '" loading="lazy" decoding="async"></button></div>';
    }

    function revokeFilePreviewObjectUrl() {
      const objectUrl = String(state.filePreview?.objectUrl || '').trim();
      if (!objectUrl) return;
      try {
        URL.revokeObjectURL(objectUrl);
      } catch (_) {
        return;
      }
    }

    function clearFilePreview({ sync = true } = {}) {
      revokeFilePreviewObjectUrl();
      state.filePreview = {
        attachmentId: '',
        fileName: '',
        objectUrl: '',
        loading: false,
        error: '',
      };
      if (sync) syncFilePreview();
    }

    function syncFilePreview(card = state.activeCard) {
      if (!els.filePreviewPanel || !els.filePreviewTitle || !els.filePreviewMeta || !els.filePreviewStatus || !els.filePreviewImage) return;
      const preview = state.filePreview && typeof state.filePreview === 'object'
        ? state.filePreview
        : { attachmentId: '', fileName: '', objectUrl: '', loading: false, error: '' };
      const attachment = findCardAttachment(card, preview.attachmentId);
      if (preview.attachmentId && !preview.loading && (!attachment || !attachmentIsPreviewable(attachment))) {
        clearFilePreview();
        return;
      }
      const isVisible = Boolean(preview.loading || preview.objectUrl || preview.error);
      els.filePreviewPanel.classList.toggle('hidden', !isVisible);
      document.body.classList.toggle('is-file-preview-open', isVisible);
      if (!isVisible) {
        els.filePreviewTitle.textContent = 'ПРОСМОТР';
        els.filePreviewMeta.textContent = '';
        els.filePreviewStatus.textContent = '';
        els.filePreviewStatus.dataset.state = 'idle';
        els.filePreviewImage.hidden = true;
        els.filePreviewImage.removeAttribute('src');
        els.filePreviewImage.alt = 'Предпросмотр вложения';
        return;
      }
      const fileName = String(attachment?.file_name || preview.fileName || 'Вложение').trim() || 'Вложение';
      const metaParts = [];
      if (attachment?.created_at) metaParts.push(formatDate(attachment.created_at));
      if (attachment?.size_bytes !== undefined) metaParts.push(formatBytes(attachment.size_bytes));
      els.filePreviewTitle.textContent = fileName;
      els.filePreviewMeta.textContent = metaParts.join(' · ');
      if (preview.loading) {
        els.filePreviewStatus.textContent = 'ЗАГРУЖАЕМ ИЗОБРАЖЕНИЕ...';
        els.filePreviewStatus.dataset.state = 'loading';
        els.filePreviewImage.hidden = true;
        els.filePreviewImage.removeAttribute('src');
        return;
      }
      if (preview.error) {
        els.filePreviewStatus.textContent = preview.error;
        els.filePreviewStatus.dataset.state = 'error';
        els.filePreviewImage.hidden = true;
        els.filePreviewImage.removeAttribute('src');
        return;
      }
      els.filePreviewStatus.textContent = '';
      els.filePreviewStatus.dataset.state = 'ready';
      if (els.filePreviewImage.getAttribute('src') !== preview.objectUrl) {
        els.filePreviewImage.src = preview.objectUrl;
      }
      els.filePreviewImage.alt = 'Предпросмотр файла ' + fileName;
      els.filePreviewImage.hidden = false;
    }

    function handleFilePreviewKeydown(event) {
      if (event.key !== 'Escape') return;
      const previewOpen = Boolean(state.filePreview?.loading || state.filePreview?.objectUrl || state.filePreview?.error);
      if (!previewOpen) return;
      event.preventDefault();
      clearFilePreview();
    }

    function handleAttachmentThumbnailError(event) {
      const image = event.target;
      if (!(image instanceof HTMLImageElement) || !image.classList.contains('file-row__thumb-image')) return;
      image.hidden = true;
      image.removeAttribute('src');
      image.closest('.file-row__thumb-button')?.classList.add('is-broken');
    }

    async function previewActiveCardAttachment(attachmentId) {
      const attachment = findCardAttachment(state.activeCard, attachmentId);
      if (!state.editingId || !attachment) {
        clearFilePreview();
        setStatus('ФАЙЛ НЕ НАЙДЕН В КАРТОЧКЕ.', true);
        return;
      }
      if (!attachmentExistsOnDisk(attachment)) {
        clearFilePreview();
        setStatus('ФАЙЛ ЕСТЬ В СПИСКЕ, НО ОТСУТСТВУЕТ НА ДИСКЕ СЕРВЕРА.', true);
        return;
      }
      if (!attachmentIsPreviewable(attachment)) {
        setStatus('ЭТО ВЛОЖЕНИЕ НЕЛЬЗЯ ПОКАЗАТЬ В ИНТЕРФЕЙСЕ.', true);
        return;
      }
      if (String(state.filePreview?.attachmentId || '') === String(attachment.id || '') && (state.filePreview.loading || state.filePreview.objectUrl || state.filePreview.error)) {
        clearFilePreview();
        return;
      }
      clearFilePreview({ sync: false });
      state.filePreview = {
        attachmentId: String(attachment.id || '').trim(),
        fileName: String(attachment.file_name || '').trim(),
        objectUrl: '',
        loading: true,
        error: '',
      };
      syncFilePreview(state.activeCard);
      try {
        const { blob } = await fetchAttachmentBlob(withAccessToken(attachmentDownloadPath(state.editingId, attachment.id)), {
          networkErrorMessage: 'НЕ УДАЛОСЬ ЗАГРУЗИТЬ ИЗОБРАЖЕНИЕ. ПРОВЕРЬ СЕТЬ И ДОСТУП К ДОСКЕ.',
        });
        const blobMimeType = normalizeAttachmentMimeType(blob.type);
        const attachmentMimeType = normalizeAttachmentMimeType(attachment.mime_type || '');
        if (!blobMimeType.startsWith('image/') && !attachmentMimeType.startsWith('image/')) {
          throw new Error('ФАЙЛ НЕ ЯВЛЯЕТСЯ ИЗОБРАЖЕНИЕМ ДЛЯ ПРОСМОТРА.');
        }
        state.filePreview = {
          attachmentId: String(attachment.id || '').trim(),
          fileName: String(attachment.file_name || '').trim(),
          objectUrl: URL.createObjectURL(blob),
          loading: false,
          error: '',
        };
        syncFilePreview(state.activeCard);
      } catch (error) {
        clearFilePreview({ sync: false });
        state.filePreview = {
          attachmentId: String(attachment.id || '').trim(),
          fileName: String(attachment.file_name || '').trim(),
          objectUrl: '',
          loading: false,
          error: String(error?.message || 'НЕ УДАЛОСЬ ЗАГРУЗИТЬ ИЗОБРАЖЕНИЕ.'),
        };
        syncFilePreview(state.activeCard);
        setStatus(state.filePreview.error, true);
      }
    }

    function renderFiles(card) {
      const perfToken = perfStart('renderFiles');
      const attachments = (card?.attachments || []).filter((item) => !item.removed);
      syncFileDropzone(card);
      els.fileDropMeta.textContent = card?.id
        ? (attachments.length
            ? ('ВЛОЖЕНИЙ: ' + attachments.length + '. ПЕРЕТАЩИТЕ, ВСТАВЬТЕ ИЛИ КЛИКНИТЕ ПО ПОЛЮ ДЛЯ ДОБАВЛЕНИЯ.')
            : 'ПОЛЕ ПУСТО. ПЕРЕТАЩИТЕ ФАЙЛ, НАЖМИТЕ CTRL+V ИЛИ ВСТАВЬТЕ ЧЕРЕЗ КОНТЕКСТНОЕ МЕНЮ.')
        : 'СНАЧАЛА СОХРАНИТЕ КАРТОЧКУ, ЗАТЕМ ДОБАВЛЯЙТЕ ВЛОЖЕНИЯ.';
      els.fileList.innerHTML = attachments.length
        ? attachments.map((item) => {
            const downloadUrl = attachmentDownloadPath(card.id, item.id);
            const existsOnDisk = attachmentExistsOnDisk(item);
            const previewOpen = String(state.filePreview?.attachmentId || '') === String(item.id || '') && (state.filePreview.loading || state.filePreview.objectUrl || state.filePreview.error);
            const thumbnailHtml = renderAttachmentThumbnailHtml(item, downloadUrl);
            const previewButtonHtml = attachmentIsPreviewable(item)
              ? '<button class="btn btn--ghost' + (previewOpen ? ' is-active' : '') + '" type="button" data-preview-file="' + escapeHtml(item.id) + '">' + (previewOpen ? 'СКРЫТЬ' : 'ПРОСМОТР') + '</button>'
              : '';
            const downloadButtonHtml = existsOnDisk
              ? '<a class="btn" href="' + downloadUrl + '">СКАЧАТЬ</a>'
              : '<button class="btn btn--ghost" type="button" disabled title="Файл отсутствует на диске сервера">СКАЧАТЬ</button>';
            const missingNoteHtml = existsOnDisk
              ? ''
              : '<div class="file-row__missing-note">Файл отсутствует на диске сервера. Запись сохранена в карточке.</div>';
            return '<div class="file-row' + (previewOpen ? ' is-previewing' : '') + (existsOnDisk ? '' : ' is-missing') + '">' + thumbnailHtml + '<div class="file-row__body"><div class="file-row__title">' + escapeHtml(item.file_name) + '</div><div class="log-row__meta">' + escapeHtml(formatDate(item.created_at)) + ' · ' + escapeHtml(formatBytes(item.size_bytes ?? 0)) + '</div>' + missingNoteHtml + '<div class="file-row__actions">' + previewButtonHtml + downloadButtonHtml + '<button class="btn btn--danger" type="button" data-remove-file="' + escapeHtml(item.id) + '">УДАЛИТЬ</button></div></div></div>';
          }).join('')
        : '<div class="log-row__meta">ФАЙЛОВ НЕТ.</div>';
      syncFilePreview(card);
      if (card?.id) {
        state.cardFilesRenderedFor = String(card.id || '') + '|' + String(card.updated_at || '');
      }
      perfEnd(perfToken, { card_id: card?.id || '', attachments: attachments.length });
    }

    function renderCardFilesPlaceholder(card, message) {
      syncFileDropzone(card);
      els.fileDropMeta.textContent = card?.id
        ? 'ФАЙЛЫ КАРТОЧКИ'
        : 'СНАЧАЛА СОХРАНИТЕ КАРТОЧКУ, ЗАТЕМ ДОБАВЛЯЙТЕ ВЛОЖЕНИЯ.';
      els.fileList.innerHTML = '<div class="log-row__meta">' + escapeHtml(message || 'ФАЙЛЫ ЗАГРУЗЯТСЯ ПРИ ОТКРЫТИИ ВКЛАДКИ.') + '</div>';
      syncFilePreview(card);
    }

    function renderActiveCardFiles() {
      const card = state.activeCard;
      if (!card?.id) {
        renderFiles(card);
        return;
      }
      if (!state.activeCardIsFull) {
        renderCardFilesPlaceholder(card, 'ЗАГРУЗКА ФАЙЛОВ...');
        return;
      }
      const renderKey = String(card.id || '') + '|' + String(card.updated_at || '');
      if (state.cardFilesRenderedFor === renderKey) return;
      renderFiles(card);
    }

    function requireSavedCardForFiles({ syncDropzone = false } = {}) {
      if (state.editingId) return true;
      setStatus('СНАЧАЛА СОХРАНИТЕ КАРТОЧКУ.', true);
      if (syncDropzone) syncFileDropzone(null);
      return false;
    }

    async function refreshActiveCardFiles() {
      if (!state.editingId) return null;
      const data = await api('/api/get_card?card_id=' + encodeURIComponent(state.editingId));
      state.activeCard = data.card;
      state.activeCardIsFull = true;
      cacheFullCard(data.card);
      renderFiles(data.card);
      return data.card;
    }

    async function removeActiveCardAttachment(attachmentId) {
      await api('/api/remove_card_attachment', {
        method: 'POST',
        body: { card_id: state.editingId, attachment_id: attachmentId, actor_name: state.actor, source: 'ui' },
      });
      await refreshActiveCardFiles();
      state.cardJournalLoadedFor = '';
      await refreshSnapshot(true);
    }

    function formatJournalDayLabel(value) {
      if (!value) return 'без даты';
      try {
        const date = value instanceof Date ? value : new Date(value);
        if (Number.isNaN(date.getTime())) return String(value);
        const weekdays = ['воскресенье', 'понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота'];
        const dd = String(date.getDate()).padStart(2, '0');
        const mm = String(date.getMonth() + 1).padStart(2, '0');
        const yyyy = String(date.getFullYear());
        return dd + '.' + mm + '.' + yyyy + ', ' + weekdays[date.getDay()];
      } catch {
        return String(value);
      }
    }

    function formatJournalTime(value) {
      if (!value) return '—';
      try {
        const date = value instanceof Date ? value : new Date(value);
        if (Number.isNaN(date.getTime())) return String(value);
        return String(date.getHours()).padStart(2, '0') + ':' + String(date.getMinutes()).padStart(2, '0');
      } catch {
        return String(value);
      }
    }

    function formatJournalEventCount(count) {
      const value = finiteNumber(count);
      const lastDigit = value % 10;
      const lastTwo = value % 100;
      if (lastDigit === 1 && lastTwo !== 11) return value + ' СОБЫТИЕ';
      if (lastDigit >= 2 && lastDigit <= 4 && (lastTwo < 10 || lastTwo >= 20)) return value + ' СОБЫТИЯ';
      return value + ' СОБЫТИЙ';
    }

    function cardJournalPluralRu(count, one, few, many) {
      const value = Math.abs(finiteNumber(count));
      const lastDigit = value % 10;
      const lastTwo = value % 100;
      if (lastDigit === 1 && lastTwo !== 11) return one;
      if (lastDigit >= 2 && lastDigit <= 4 && (lastTwo < 10 || lastTwo >= 20)) return few;
      return many;
    }

    function cardJournalCountText(count, one, few, many) {
      const value = finiteNumber(count);
      return value + ' ' + cardJournalPluralRu(value, one, few, many);
    }

    function cardJournalEntriesFromPayload(payload) {
      if (Array.isArray(payload?.entries)) return payload.entries;
      if (Array.isArray(payload?.timeline)) return payload.timeline;
      return [];
    }

    function buildCardJournalDays(entries) {
      const byDay = new Map();
      (Array.isArray(entries) ? entries : []).forEach((entry) => {
        const key = String(entry?.day_key || entry?.date || '').trim() || 'unknown';
        if (!byDay.has(key)) {
          byDay.set(key, {
            key,
            label: key === 'unknown' ? 'без даты' : formatJournalDayLabel(entry?.business_timestamp || entry?.timestamp || key),
            count: 0,
            changes: 0,
            deletions: 0,
            entries: [],
          });
        }
        const day = byDay.get(key);
        day.entries.push(entry);
        day.count += 1;
        day.changes += finiteNumber(entry?.change_count);
        if (entry?.has_deletion) day.deletions += 1;
      });
      return Array.from(byDay.values()).sort((left, right) => String(right.key).localeCompare(String(left.key)));
    }

    function cardJournalStripIcon(value) {
      return String(value ?? '').replace(/^[\s\uFE0F\u200D\u2600-\u27BF\uD800-\uDFFF]+/g, '').trim();
    }

    function cardJournalCollapsedText(value) {
      return String(value ?? '')
        .replace(/\r/g, '')
        .split('\n')
        .map((line) => line.trim())
        .filter(Boolean)
        .join(' · ');
    }

    function cardJournalEnsurePeriod(value) {
      const text = String(value ?? '').trim();
      if (!text) return '';
      return /[.!?…:]$/.test(text) ? text : text + '.';
    }

    function cardJournalLineParts(entry) {
      return String(entry?.display_line || '').split('|').map((item) => item.trim()).filter(Boolean);
    }

    function cardJournalActorName(entry) {
      const lineParts = cardJournalLineParts(entry);
      return cardJournalStripIcon(lineParts[2] || entry?.display_actor_name || entry?.actor_name || 'неизвестно') || 'неизвестно';
    }

    function cardJournalActionLabel(entry) {
      const lineParts = cardJournalLineParts(entry);
      return cardJournalStripIcon(entry?.action_label || entry?.human_message || entry?.message || lineParts[1] || 'Событие') || 'Событие';
    }

    function cardJournalEventSentence(entry) {
      const actor = cardJournalActorName(entry);
      const action = cardJournalEnsurePeriod(cardJournalActionLabel(entry));
      return '<strong>' + escapeHtml(actor) + '</strong> · ' + escapeHtml(action);
    }

    function renderCardJournalBlock(block) {
      const item = block && typeof block === 'object' ? block : {};
      const title = cardJournalStripIcon(item.title || item.label || 'Запись журнала');
      const text = String(item.text ?? '').replace(/\r/g, '').trimEnd();
      const isEmpty = Boolean(item.is_empty) || !text.trim();
      const removed = String(item.change_kind || '').toLowerCase() === 'removed';
      let html = '<div class="card-journal-block' + (isEmpty ? ' card-journal-block--empty' : '') + '">';
      if (title) html += '<div class="card-journal-block__head">' + escapeHtml(title) + '</div>';
      if (!isEmpty) {
        html += '<pre class="card-journal-block__text">' + escapeHtml(text) + '</pre>';
      } else if (removed) {
        html += '<div class="card-journal-block__text">Текущее значение очищено.</div>';
      }
      return html + '</div>';
    }

    function cardJournalBlockParts(block) {
      const item = block && typeof block === 'object' ? block : {};
      const title = cardJournalStripIcon(item.title || item.label || '');
      const rawText = String(item.text ?? '').replace(/\r/g, '').trimEnd();
      const removed = String(item.change_kind || '').toLowerCase() === 'removed';
      const displayText = rawText.trim() ? rawText : (removed ? 'Текущее значение очищено.' : '');
      const summary = cardJournalCollapsedText(displayText);
      if (!title && !summary) return { inlineHtml: '', blockHtml: '' };
      const valueLines = displayText.split('\n').filter((line) => line.trim());
      const isFullValue = Boolean(item.is_full_value);
      const isLong = isFullValue || displayText.length > 140 || valueLines.length > 2;
      if (!isLong) {
        const inlineText = title && summary ? title + ': ' + summary : (title || summary);
        return {
          inlineHtml: inlineText ? ' <span class="card-journal-detail">' + escapeHtml(cardJournalEnsurePeriod(inlineText)) + '</span>' : '',
          blockHtml: '',
        };
      }
      return {
        inlineHtml: '',
        blockHtml: renderCardJournalBlock({
          ...item,
          title,
          text: displayText,
          is_empty: Boolean(item.is_empty) && !summary,
          change_kind: item.change_kind || (removed ? 'removed' : 'changed'),
        }),
      };
    }

    function renderCardJournalDetailLines(detailLines) {
      const lines = Array.isArray(detailLines) ? detailLines : [];
      let inlineHtml = '';
      let blockHtml = '';
      let captureAfter = false;
      let blockLines = [];
      const flushBlock = () => {
        if (!blockLines.length) return;
        blockHtml += renderCardJournalBlock({
          title: 'Опубликованное значение',
          text: blockLines.join('\n'),
        });
        blockLines = [];
      };

      lines.forEach((line) => {
        const raw = String(line ?? '').replace(/\r/g, '').trimEnd();
        const trimmed = raw.trim();
        if (!trimmed) return;
        const lower = trimmed.toLowerCase();
        if (lower === 'до:' || lower === 'до') {
          flushBlock();
          captureAfter = false;
          return;
        }
        if (lower === 'после:' || lower === 'после') {
          flushBlock();
          captureAfter = true;
          return;
        }
        if (captureAfter) {
          blockLines.push(raw.replace(/^\s{2}/, ''));
          return;
        }
        const isSummary = trimmed.startsWith('Что произошло:');
        const text = isSummary ? trimmed.replace(/^Что произошло:\s*/i, '') : trimmed;
        inlineHtml += ' <span class="card-journal-detail">' + escapeHtml(cardJournalEnsurePeriod(text)) + '</span>';
      });
      flushBlock();
      return { inlineHtml, blockHtml };
    }

    function renderCardJournalDetails(entry) {
      const blocks = Array.isArray(entry?.journal_blocks)
        ? entry.journal_blocks
        : (Array.isArray(entry?.published_blocks) ? entry.published_blocks : []);
      if (blocks.length) {
        return blocks.reduce((acc, block) => {
          const parts = cardJournalBlockParts(block);
          acc.inlineHtml += parts.inlineHtml;
          acc.blockHtml += parts.blockHtml;
          return acc;
        }, { inlineHtml: '', blockHtml: '' });
      }
      const detailLines = Array.isArray(entry?.detail_lines)
        ? entry.detail_lines
        : (entry?.details_text ? String(entry.details_text).split('\n') : []);
      return renderCardJournalDetailLines(detailLines);
    }

    function renderCardJournalEntry(entry) {
      const lineParts = cardJournalLineParts(entry);
      const time = escapeHtml(entry?.time_short || formatJournalTime(entry?.business_timestamp || entry?.timestamp) || lineParts[0] || '—');
      const deletionClass = entry?.has_deletion ? ' card-journal-entry--deletion' : '';
      const blockParts = renderCardJournalDetails(entry);
      return '<article class="card-journal-entry' + deletionClass + '"><div class="card-journal-entry__time">' + time + '</div><div class="card-journal-entry__content"><div class="card-journal-entry__sentence">' + cardJournalEventSentence(entry) + blockParts.inlineHtml + '</div>' + blockParts.blockHtml + '</div></article>';
    }

    function buildCardJournalHtml(payload) {
      const data = payload || {};
      const meta = data.meta || {};
      const totals = data.totals || {};
      const entries = cardJournalEntriesFromPayload(data);
      const payloadDays = Array.isArray(data.days) ? data.days : [];
      const days = payloadDays.some((day) => Array.isArray(day?.entries) && day.entries.length) ? payloadDays : buildCardJournalDays(entries);
      const returned = finiteNonNegativeNumber(totals.count ?? meta.events_returned, entries.length);
      const total = finiteNonNegativeNumber(meta.events_total, returned);
      const currentLimit = Math.min(CARD_JOURNAL_MAX_LIMIT, Math.max(0, finiteNumber(meta.limit ?? state.cardJournalLimit ?? returned, CARD_JOURNAL_INITIAL_LIMIT)));
      const nextLimit = Math.min(CARD_JOURNAL_MAX_LIMIT, total || CARD_JOURNAL_MAX_LIMIT, currentLimit + CARD_JOURNAL_LIMIT_STEP);
      const totalLabel = cardJournalCountText(total, 'событие', 'события', 'событий');
      const returnedLabel = returned === total ? totalLabel : 'показано ' + returned + ' из ' + totalLabel;
      let html = '<div class="card-journal-header"><div><div class="card-journal-header__title">Журнал карточки</div><div class="card-journal-header__subtitle">' + escapeHtml(meta.card_heading || 'Карточка') + '</div></div><div class="card-journal-header__meta">' + escapeHtml(returnedLabel + ' · новые сверху') + '</div></div>';
      if (meta.has_more) {
        html += '<div class="card-journal-note">Показаны последние события. Остальная история загрузится по запросу.</div>';
      }
      if (!entries.length && !days.length) {
        return html + '<div class="card-journal-empty">Журнал пуст.</div>';
      }
      days.forEach((day) => {
        const dayEntries = Array.isArray(day?.entries) ? day.entries : [];
        html += '<section class="card-journal-day"><div class="card-journal-day__label">' + escapeHtml(day?.label || day?.key || 'без даты') + '</div><div class="card-journal-events">';
        html += dayEntries.map(renderCardJournalEntry).join('');
        html += '</div></section>';
      });
      if (meta.has_more && nextLimit > currentLimit) {
        html += '<div class="card-journal-more"><button class="btn btn--ghost" type="button" data-card-journal-load-more="' + nextLimit + '">ПОКАЗАТЬ ЕЩЁ</button></div>';
      }
      return html;
    }

    function renderLogs(payload) {
      const data = Array.isArray(payload) ? { events: payload } : (payload || {});
      const text = String(data?.markdown || data?.text || buildCardJournalFallbackText(data?.events || data?.entries || []));
      if (data?.meta?.schema_version === 'card_journal.v2' || Array.isArray(data?.entries) || Array.isArray(data?.days)) {
        els.logList.className = 'card-journal-view';
        els.logList.innerHTML = buildCardJournalHtml(data);
        return;
      }
      els.logList.className = 'card-journal-text';
      els.logList.textContent = text;
    }

    function archiveCardSearchText(card) {
      return normalizeClientSearchText([
        cardHeading(card),
        card?.title,
        card?.vehicle,
        card?.client,
        card?.customer,
        card?.license_plate,
        card?.column,
        formatDate(card?.updated_at),
        stripDescriptionFormatting(card?.description || ''),
      ].filter(Boolean).join(' '));
    }

    function filteredArchiveCards() {
      const cards = Array.isArray(state.archiveCards) ? state.archiveCards : [];
      const query = normalizeClientSearchText(state.archiveQuery || '');
      if (!query) return cards;
      return cards.filter((card) => archiveCardSearchText(card).includes(query));
    }

    function renderArchiveSearchMeta(total, visible) {
      if (!els.archiveSearchMeta) return;
      const query = String(state.archiveQuery || '').trim();
      els.archiveSearchMeta.textContent = query
        ? ('НАЙДЕНО: ' + visible + ' ИЗ ' + total + ' ПО ПОКАЗАННЫМ ' + ARCHIVE_PREVIEW_LIMIT)
        : ('ПОКАЗАНО: ' + visible + ' ИЗ ' + total + ' ПОСЛЕДНИХ АРХИВНЫХ КАРТОЧЕК');
    }

    function renderCompactArchiveRows(cards) {
      return cards.map((card) => {
        const heading = cardHeading(card);
        const compactDescription = stripDescriptionFormatting(card.description || 'Описание не указано').replace(/\s+/g, ' ').trim();
        const summary = compactDescription.length > 180 ? compactDescription.slice(0, 177) + '...' : compactDescription;
        const restoreLabel = 'Вернуть карточку ' + heading;
        return '<div class="archive-row archive-row--compact"><div class="archive-row__main"><div class="archive-row__title" title="' + escapeHtml(heading) + '">' + escapeHtml(heading) + '</div><div class="archive-row__summary" title="' + escapeHtml(compactDescription || 'Описание не указано') + '">' + escapeHtml(summary || 'Описание не указано') + '</div></div><div class="archive-row__side"><div class="archive-row__meta">АРХИВ: ' + escapeHtml(formatDate(card.updated_at)) + '</div><button class="btn" data-restore-card="' + escapeHtml(card.id) + '" aria-label="Вернуть карточку ' + escapeHtml(heading) + '" title="' + escapeHtml(restoreLabel) + '">ВЕРНУТЬ</button></div></div>';
      }).join('');
    }

    function gptWallMetaText(meta) {
      return 'СОБРАНО: ' + formatDate(meta.generated_at) +
        ' | СТОЛБЦОВ: ' + (meta.columns ?? 0) +
        ' | АКТИВНЫХ: ' + (meta.active_cards ?? 0) +
        ' | АРХИВ: ' + (meta.archived_cards ?? 0) +
        ' | СТИКЕРОВ: ' + (meta.stickies ?? 0) +
        ' | СОБЫТИЙ: ' + (meta.events_total ?? 0);
    }

    function normalizeGptWallView(value) {
      return value === 'event_log' ? 'event_log' : 'board_content';
    }

    function buildGptWallEventsFallback(data) {
      const events = Array.isArray(data?.events) ? data.events : [];
      if (!events.length) return 'СОБЫТИЙ НЕТ.';
      return events.map((event) => {
        const parts = [
          event?.timestamp || '—',
          event?.actor_name || '—',
          event?.message || '—',
          event?.card_short_id || event?.card_id || '—',
        ];
        if (event?.details_text) parts.push(event.details_text);
        return parts.join(' | ');
      }).join('\n');
    }

    function buildReadableGptWallEvents(data) {
      const events = Array.isArray(data?.events) ? data.events : [];
      if (!events.length) return 'СОБЫТИЙ НЕТ.';
      return events.map((event, index) => {
        const lines = [
          '[event ' + (index + 1) + ']',
          'time: ' + (event?.timestamp || 'вЂ”'),
          'actor: ' + (event?.actor_name || 'вЂ”'),
          'source: ' + (event?.source || 'вЂ”'),
          'action: ' + (event?.action || 'вЂ”'),
          'message: ' + (event?.message || 'вЂ”'),
        ];
        const cardRef = event?.card_short_id || event?.card_id || '';
        if (cardRef) lines.push('card: ' + cardRef);
        if (event?.card_heading) lines.push('heading: ' + event.card_heading);
        if (event?.details_text) lines.push('details: ' + String(event.details_text).replace(/\r?\n/g, ' / '));
        return lines.join('\n');
      }).join('\n\n');
    }

    function gptWallSectionMetaText(view, data) {
      const meta = data?.meta || {};
      const sections = data?.sections || {};
      const section = sections?.[view] || {};
      if (view === 'event_log') {
        const sectionMeta = section?.meta || {};
        return 'ЖУРНАЛ СОБЫТИЙ | СОБРАНО: ' + formatDate(sectionMeta.generated_at || meta.generated_at) +
          ' | ПОКАЗАНО: ' + (sectionMeta.events_returned ?? meta.events_returned ?? 0) +
          ' | ВСЕГО: ' + (sectionMeta.events_total ?? meta.events_total ?? 0);
      }
      return 'СОДЕРЖАНИЕ ДОСКИ | ' + gptWallMetaText(section?.meta || meta);
    }

    function gptWallSectionText(view, data) {
      const sections = data?.sections || {};
      const section = sections?.[view] || {};
      if (view === 'event_log') {
        return section?.text || buildReadableGptWallEvents(data);
      }
      return section?.text || data?.text || 'ДАННЫХ НЕТ.';
    }

    function renderGptWallView() {
      const view = normalizeGptWallView(state.gptWallView);
      if (els.gptWallBoardTab) els.gptWallBoardTab.classList.toggle('is-active', view === 'board_content');
      if (els.gptWallEventsTab) els.gptWallEventsTab.classList.toggle('is-active', view === 'event_log');
      els.gptWallMeta.textContent = gptWallSectionMetaText(view, state.gptWall);
      els.gptWallText.dataset.wallView = view;
      els.gptWallText.textContent = gptWallSectionText(view, state.gptWall);
    }

    function setGptWallView(view) {
      state.gptWallView = normalizeGptWallView(view);
      renderGptWallView();
    }

    function setModalListError(metaEl, listEl, metaText, bodyText) {
      metaEl.textContent = metaText;
      listEl.innerHTML = '<div class="log-row__meta">' + escapeHtml(bodyText) + '</div>';
    }

    function setModalTextError(metaEl, textEl, metaText, bodyText) {
      metaEl.textContent = metaText;
      textEl.textContent = bodyText;
    }

    function renderArchive() {
      const totalCards = Array.isArray(state.archiveCards) ? state.archiveCards : [];
      const cards = filteredArchiveCards();
      renderArchiveSearchMeta(totalCards.length, cards.length);
      els.archiveList.innerHTML = cards.length
        ? renderCompactArchiveRows(cards)
        : state.archiveLoading
          ? '<div class="log-row__meta">ЗАГРУЗКА АРХИВА...</div>'
        : String(state.archiveQuery || '').trim()
          ? '<div class="log-row__meta">ПО ПОКАЗАННЫМ АРХИВНЫМ КАРТОЧКАМ НИЧЕГО НЕ НАЙДЕНО.</div>'
        : '<div class="log-row__meta">АРХИВ ПУСТ.</div>';
    }

    function clearCardOpenSideEffectTimer() {
      if (state.cardOpenSideEffectTimer) {
        window.clearTimeout(state.cardOpenSideEffectTimer);
        state.cardOpenSideEffectTimer = null;
      }
      state.cardOpenSideEffectCardId = '';
    }

    function recordCardOpenSideEffects(cardId) {
      const normalizedCardId = String(cardId || '').trim();
      if (!normalizedCardId) return;
      clearCardOpenSideEffectTimer();
      const currentCard = snapshotCardById(normalizedCardId) || (state.activeCard?.id === normalizedCardId ? state.activeCard : null);
      const shouldMarkSeen = Boolean(currentCard?.is_unread || currentCard?.has_unseen_update);
      if (shouldMarkSeen) {
        markCardSeenOptimistically(normalizedCardId);
        window.setTimeout(() => markCardSeen(normalizedCardId, { force: true }), CARD_OPEN_SIDE_EFFECT_DELAY_MS);
      }
      state.cardOpenSideEffectCardId = normalizedCardId;
      state.cardOpenSideEffectTimer = window.setTimeout(() => {
        state.cardOpenSideEffectTimer = null;
        if (state.cardOpenSideEffectCardId !== normalizedCardId) return;
        api('/api/open_card', {
          method: 'POST',
          body: {
            card_id: normalizedCardId,
            return_card: false,
            mark_seen: false,
          },
        }).catch(() => {});
      }, CARD_OPEN_SIDE_EFFECT_DELAY_MS);
    }

    async function openCardWorkspace(cardId, { closeModalEl = null, openCardModalEl = true, openRepairOrder = false, repairOrderParentLayer = '' } = {}) {
      return perfMeasureAsync('openCardWorkspace', async () => {
        const normalizedCardId = String(cardId || '').trim();
        if (!normalizedCardId) return null;
        const cachedCard = snapshotCardById(normalizedCardId);
        const cachedFullCard = cachedCard
          ? cachedFullCardForSnapshot(cachedCard)
          : (state.fullCardCache.get(normalizedCardId) || null);
        let openedFromCache = false;
        const hydrationSeq = state.cardHydrationSeq + 1;
        state.cardHydrationSeq = hydrationSeq;
        state.cardHydratingId = normalizedCardId;
        if (openCardModalEl && cachedFullCard) {
          if (closeModalEl) popModal(modalKeyForElement(closeModalEl));
          openCardModal(cachedFullCard, { cardIsFull: true });
          openedFromCache = true;
        } else if (openCardModalEl && cachedCard) {
          if (closeModalEl) popModal(modalKeyForElement(closeModalEl));
          openCardModal(cachedCard, { descriptionLoading: true, cardIsFull: false });
          openedFromCache = true;
        }
        let fullCard;
        try {
          fullCard = cachedFullCard || await fetchFullCard(normalizedCardId, cachedCard?.updated_at || '');
        } catch (error) {
          if (
            openCardModalEl
            && openedFromCache
            && els.cardModal?.classList.contains('is-open')
            && state.editingId === normalizedCardId
          ) {
            setCardDescriptionLoading(true, 'Не удалось загрузить описание.');
          }
          if (state.cardHydratingId === normalizedCardId) state.cardHydratingId = '';
          throw error;
        }
        if (openCardModalEl) {
          if (!openedFromCache && closeModalEl) popModal(modalKeyForElement(closeModalEl));
          const shouldHydrateOpenModal = !openedFromCache
            || (
              els.cardModal?.classList.contains('is-open')
              && state.cardHydrationSeq === hydrationSeq
              && state.editingId === normalizedCardId
            );
          if (shouldHydrateOpenModal) {
            openCardModal(fullCard, { cardIsFull: true, preserveTab: openedFromCache });
          }
        } else {
          applyCardModalState(fullCard, { cardIsFull: true });
        }
        if (state.cardHydratingId === normalizedCardId) state.cardHydratingId = '';
        recordCardOpenSideEffects(normalizedCardId);
        if (openRepairOrder) {
          state.repairOrderParentLayer = String(repairOrderParentLayer || (openCardModalEl ? 'card' : '')).trim();
          await openRepairOrderModal();
        }
        return fullCard;
      });
    }

    async function openRepairOrderCard(cardId, { parentLayer = 'repair-orders' } = {}) {
      try {
        const normalizedCardId = String(cardId || '').trim();
        if (!normalizedCardId) return;
        const data = await api('/api/get_repair_order', {
          method: 'POST',
          body: {
            card_id: normalizedCardId,
            actor_name: state.actor,
            source: 'ui',
            create_if_missing: true,
          },
        });
        const updatedCard = repairOrderResponseCard(data, data?.repair_order || {});
        state.activeCard = updatedCard;
        state.editingId = updatedCard?.id || normalizedCardId;
        state.pendingCardClientId = updatedCard?.client_id || '';
        state.repairOrderParentLayer = String(parentLayer || 'repair-orders').trim();
        await openRepairOrderModal({ preloadedRepairOrderData: data });
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    function updateRepairOrdersTabs() {
      const normalizedFilter = normalizeRepairOrderStatus(state.repairOrdersFilter);
      const isClosed = normalizedFilter === 'closed';
      const isReady = normalizedFilter === 'ready';
      const repairOrdersDialog = els.repairOrdersModal ? els.repairOrdersModal.querySelector('.dialog--repair-orders') : null;
      if (els.repairOrdersOpenTab) els.repairOrdersOpenTab.classList.toggle('is-active', normalizedFilter === 'open');
      if (els.repairOrdersReadyTab) els.repairOrdersReadyTab.classList.toggle('is-active', isReady);
      if (els.repairOrdersClosedTab) els.repairOrdersClosedTab.classList.toggle('is-active', isClosed);
      if (els.repairOrdersModal) els.repairOrdersModal.dataset.repairOrdersFilter = normalizedFilter;
      if (repairOrdersDialog) repairOrdersDialog.dataset.repairOrdersFilter = normalizedFilter;
      syncRepairOrdersLayout(normalizedFilter);
    }

    function repairOrdersIsClosedView(status = state.repairOrdersFilter) {
      return normalizeRepairOrderStatus(status) === 'closed';
    }

    function normalizeRepairOrdersSearchField(value) {
      const normalized = String(value || '').trim().toLowerCase();
      return REPAIR_ORDER_SEARCH_FIELDS.includes(normalized) ? normalized : 'summary';
    }

    function repairOrdersSearchFieldLabel(field = state.repairOrdersSearchField) {
      const normalized = normalizeRepairOrdersSearchField(field);
      if (normalized === 'number') return '№';
      if (normalized === 'date') return 'ДАТЫ';
      if (normalized === 'client') return 'КЛИЕНТ';
      if (normalized === 'phone') return 'ТЕЛЕФОН';
      if (normalized === 'vehicle') return 'АВТОМОБИЛЬ';
      if (normalized === 'license_plate') return 'ГОСНОМЕР';
      return 'СМЫСЛ КАРТОЧКИ';
    }

    function repairOrdersSearchPlaceholder(field = state.repairOrdersSearchField) {
      const normalized = normalizeRepairOrdersSearchField(field);
      if (normalized === 'number') return 'поиск по номеру заказ-наряда';
      if (normalized === 'date') return 'поиск по дате';
      if (normalized === 'client') return 'поиск по клиенту';
      if (normalized === 'phone') return 'поиск по телефону';
      if (normalized === 'vehicle') return 'поиск по автомобилю';
      if (normalized === 'license_plate') return 'поиск по госномеру';
      return 'поиск по сути карточки';
    }

    function repairOrdersTableHeadSearchableHtml(label, field) {
      const normalizedField = normalizeRepairOrdersSearchField(field);
      const activeClass = state.repairOrdersSearchField === normalizedField ? ' is-active' : '';
      const labelText = String(label || '').trim();
      const titleText = 'Искать по графе ' + labelText.toLowerCase();
      return '<div class="repair-orders-table-head__searchable"><span>' + escapeHtml(labelText) + '</span><button class="repair-orders-search-scope' + activeClass + '" type="button" data-repair-orders-search-field="' + escapeHtml(normalizedField) + '" aria-label="' + escapeHtml(titleText) + '" title="' + escapeHtml(titleText) + '"></button></div>';
    }

    function repairOrdersTableHeadSummaryCellHtml() {
      return '<div class="repair-orders-table-head__searchable-group">'
        + repairOrdersTableHeadSearchableHtml('Смысл карточки', 'summary')
        + repairOrdersTableHeadSearchableHtml('Госномер', 'license_plate')
        + '</div>';
    }

    function repairOrdersColumnsValue(status = state.repairOrdersFilter) {
      repairOrdersIsClosedView(status);
      return 'minmax(35px, 46px) minmax(67px, 79px) minmax(100px, 116px) minmax(136px, 168px) minmax(147px, 179px) minmax(138px, 168px) minmax(501px, 4.666fr) minmax(82px, 96px) minmax(82px, 96px)';
    }

    function repairOrdersTableHeadHtml(status = state.repairOrdersFilter) {
      return repairOrdersTableHeadSearchableHtml('№', 'number')
        + repairOrdersTableHeadSearchableHtml('Даты', 'date')
        + '<div>Оплата</div>'
        + repairOrdersTableHeadSearchableHtml('Клиент', 'client')
        + repairOrdersTableHeadSearchableHtml('Телефон', 'phone')
        + repairOrdersTableHeadSearchableHtml('Автомобиль', 'vehicle')
        + repairOrdersTableHeadSummaryCellHtml()
        + '<div class="repair-orders-table-head__sum">Внесено</div>'
        + '<div class="repair-orders-table-head__sum">Сумма</div>';
    }
    function syncRepairOrdersLayout(status = state.repairOrdersFilter) {
      if (els.repairOrdersModal) {
        els.repairOrdersModal.style.setProperty('--repair-orders-columns', repairOrdersColumnsValue(status));
      }
      if (els.repairOrdersTableHead) {
        els.repairOrdersTableHead.innerHTML = repairOrdersTableHeadHtml(status);
      }
    }

    function setRepairOrdersSearchLoading(isLoading) {
      state.repairOrdersSearchLoading = Boolean(isLoading);
      if (els.repairOrdersSearchSpinner) {
        els.repairOrdersSearchSpinner.classList.toggle('is-active', state.repairOrdersSearchLoading);
      }
    }

    function normalizeRepairOrdersSortBy(value) {
      const normalized = String(value || '').trim().toLowerCase();
      return REPAIR_ORDER_SORT_FIELDS.includes(normalized) ? normalized : 'number';
    }

    function normalizeRepairOrdersSortDir(value) {
      const normalized = String(value || '').trim().toLowerCase();
      return REPAIR_ORDER_SORT_DIRECTIONS.includes(normalized) ? normalized : 'desc';
    }

    function syncRepairOrdersControls() {
      if (els.repairOrdersSearchInput) {
        const query = String(state.repairOrdersQuery || '');
        if (els.repairOrdersSearchInput.value !== query) els.repairOrdersSearchInput.value = query;
        els.repairOrdersSearchInput.placeholder = repairOrdersSearchPlaceholder(state.repairOrdersSearchField);
      }
      setRepairOrdersSearchLoading(state.repairOrdersSearchLoading);
      if (els.repairOrdersSortBy) els.repairOrdersSortBy.value = normalizeRepairOrdersSortBy(state.repairOrdersSortBy);
      if (els.repairOrdersSortDir) els.repairOrdersSortDir.value = normalizeRepairOrdersSortDir(state.repairOrdersSortDir);
    }

    function repairOrdersRequestPath() {
      const params = new URLSearchParams();
      params.set('limit', '300');
      params.set('status', normalizeRepairOrderStatus(state.repairOrdersFilter));
      params.set('sort_by', normalizeRepairOrdersSortBy(state.repairOrdersSortBy));
      params.set('sort_dir', normalizeRepairOrdersSortDir(state.repairOrdersSortDir));
      if (state.repairOrdersRemoteQuery) params.set('query', state.repairOrdersRemoteQuery);
      return '/api/list_repair_orders?' + params.toString();
    }

    async function setRepairOrdersFilter(status, { openModal = false } = {}) {
      state.repairOrdersFilter = normalizeRepairOrderStatus(status);
      if (state.repairOrdersLoadTimer) {
        window.clearTimeout(state.repairOrdersLoadTimer);
        state.repairOrdersLoadTimer = null;
      }
      setRepairOrdersSearchLoading(false);
      updateRepairOrdersTabs();
      await loadRepairOrders(openModal);
    }

    function renderRepairOrderRows(section, rows, { syncTotals = true } = {}) {
      const body = repairOrderRowsBody(section);
      closeRepairOrderWorkSalaryPopover();
      body.innerHTML = ensureRepairOrderRows(rows).map((row, index) => repairOrderRowHtml(section, row, index)).join('');
      if (syncTotals) syncRepairOrderTotals();
    }

    function repairOrderParentLayerFromTrigger(trigger) {
      if (!(trigger instanceof Element)) return 'repair-orders';
      if (trigger.closest('#employeesModal')) return 'employees';
      if (trigger.closest('#clientsModal')) return 'clients';
      if (trigger.closest('#cardModal')) return 'card';
      if (trigger.closest('#repairOrdersModal')) return 'repair-orders';
      return 'repair-orders';
    }

    async function handleRepairOrdersListKeydown(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const row = target.closest('[data-open-repair-order-card]');
      if (!row) return;
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      await openRepairOrderCard(row.dataset.openRepairOrderCard, { parentLayer: 'repair-orders' });
    }

    async function handleRepairOrdersListClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const row = target.closest('[data-open-repair-order-card]');
      if (!(row instanceof HTMLElement)) return;
      event.preventDefault();
      event.stopPropagation();
      await openRepairOrderCard(row.dataset.openRepairOrderCard, { parentLayer: 'repair-orders' });
    }

    function renderGptWall(data) {
      state.gptWall = data;
      renderGptWallView();
    }

    async function loadGptWall(openModal = false) {
      try {
        const data = await api('/api/get_gpt_wall', { method: 'POST', body: { include_archived: true, event_limit: 100 } });
        renderGptWall(data);
        if (openModal) pushModal('wall', els.gptWallModal);
      } catch (error) {
        els.gptWallMeta.textContent = 'ОШИБКА ЗАГРУЗКИ СЛОЯ GPT.';
        els.gptWallText.textContent = error.message;
        if (openModal) pushModal('wall', els.gptWallModal);
        setStatus(error.message, true);
      }
    }

    repairOrderListTotalText = function(value, fallbackValue = '') {
      const normalized = String(value ?? '').trim();
      if (normalized && normalized !== '0') return normalized;
      const fallback = String(fallbackValue ?? '').trim();
      return fallback || normalized || '0';
    };

    function repairOrdersDisplayedDateForItem(item, isClosedView = repairOrdersIsClosedView()) {
      const openedAt = repairOrderListDateDisplayValue(item?.opened_at || item?.created_at || item?.date || item?.updated_at);
      const closedAt = repairOrderListDateDisplayValue(item?.closed_at);
      return isClosedView ? (closedAt || openedAt || '-') : (openedAt || closedAt || '-');
    }

    function repairOrdersNormalizeSearchText(value) {
      return String(value ?? '')
        .toLowerCase()
        .replace(/ё/g, 'е')
        .replace(/[^a-zа-я0-9]+/gi, ' ')
        .trim()
        .replace(/\s+/g, ' ');
    }

    function repairOrdersCompactSearchText(value) {
      return String(value ?? '')
        .toLowerCase()
        .replace(/ё/g, 'е')
        .replace(/[^a-zа-я0-9]+/gi, '');
    }

    function repairOrdersSearchTokens(value) {
      const normalized = repairOrdersNormalizeSearchText(value);
      return normalized ? normalized.split(' ').filter(Boolean) : [];
    }

    function repairOrdersSearchableText(item, field = state.repairOrdersSearchField) {
      const normalizedField = normalizeRepairOrdersSearchField(field);
      if (normalizedField === 'number') return String(item?.number || '').trim();
      if (normalizedField === 'date') return repairOrdersDisplayedDateForItem(item);
      if (normalizedField === 'client') return String(item?.client || '').trim();
      if (normalizedField === 'phone') return String(item?.phone || '').trim();
      if (normalizedField === 'vehicle') return String(item?.vehicle || '').trim();
      if (normalizedField === 'license_plate') {
        return [
          item?.license_plate,
          item?.summary,
          item?.reason,
          item?.heading,
        ].filter(Boolean).join(' ');
      }
      return [
        item?.summary,
        item?.reason,
        item?.heading,
        item?.vehicle,
        item?.client,
      ].filter(Boolean).join(' ');
    }

    function repairOrdersMatchesSummarySearch(item, query) {
      const normalizedQuery = repairOrdersNormalizeSearchText(query);
      if (!normalizedQuery) return true;
      const haystack = repairOrdersNormalizeSearchText(repairOrdersSearchableText(item, 'summary'));
      if (!haystack) return false;
      if (haystack.includes(normalizedQuery)) return true;
      const hayTokens = haystack.split(' ').filter(Boolean);
      const queryTokens = repairOrdersSearchTokens(query);
      if (!queryTokens.length) return true;
      return queryTokens.every((token) => hayTokens.some((word) => word.includes(token) || token.includes(word)));
    }

    function repairOrdersMatchesFieldSearch(item, field, query) {
      const normalizedField = normalizeRepairOrdersSearchField(field);
      const normalizedQuery = repairOrdersNormalizeSearchText(query);
      if (!normalizedQuery) return true;
      if (normalizedField === 'summary') return repairOrdersMatchesSummarySearch(item, query);
      const fieldText = repairOrdersSearchableText(item, normalizedField);
      const normalizedFieldText = repairOrdersNormalizeSearchText(fieldText);
      if (normalizedFieldText.includes(normalizedQuery)) return true;
      const compactQuery = repairOrdersCompactSearchText(query);
      if (!compactQuery) return false;
      const compactFieldText = repairOrdersCompactSearchText(fieldText);
      return compactFieldText.includes(compactQuery);
    }

    function filterRepairOrdersItems(items = state.repairOrdersItems) {
      const query = String(state.repairOrdersQuery || '').trim();
      if (!query) return Array.isArray(items) ? items : [];
      return (Array.isArray(items) ? items : []).filter((item) => repairOrdersMatchesFieldSearch(item, state.repairOrdersSearchField, query));
    }

    function repairOrdersEmptyStateText() {
      if (String(state.repairOrdersQuery || '').trim()) return 'ПО ПОИСКУ НИЧЕГО НЕ НАЙДЕНО.';
      const status = normalizeRepairOrderStatus(state.repairOrdersFilter);
      if (status === 'closed') return 'АРХИВ ЗАКАЗ-НАРЯДОВ ПУСТ.';
      if (status === 'ready') return 'ГОТОВЫХ ЗАКАЗ-НАРЯДОВ ПОКА НЕТ.';
      return 'ОТКРЫТЫХ ЗАКАЗ-НАРЯДОВ ПОКА НЕТ.';
    }

    function renderRepairOrdersView() {
      const items = filterRepairOrdersItems(state.repairOrdersItems);
      syncRepairOrdersControls();
      els.repairOrdersMeta.textContent = '';
      els.repairOrdersList.innerHTML = items.length
        ? renderRepairOrderListRows(items)
        : '<div class="log-row__meta">' + repairOrdersEmptyStateText() + '</div>';
      renderMobileShell();
    }

    // СПИСОК: ДАТА / АВТО / СУТЬ / СУММА
    repairOrdersMetaText = function(items, meta) {
      return '';
    };

    renderRepairOrderListRows = function(items) {
      const isClosedView = repairOrdersIsClosedView();
      return items.map((item) => {
        const number = item.number || '-';
        const numberDigits = String(number).replace(/\D+/g, '') || '-';
        const openedAt = repairOrderListDateDisplayValue(item.opened_at || item.created_at || item.date || item.updated_at);
        const closedAt = repairOrderListDateDisplayValue(item.closed_at);
        const displayedDate = isClosedView ? (closedAt || openedAt || '-') : (openedAt || closedAt || '-');
        const vehicle = String(item.vehicle || '').trim() || '-';
        const client = String(item.client || '').trim();
        const phone = String(item.phone || '').trim();
        const clientText = client || '-';
        const phoneText = phone || '-';
        const heading = item.summary || item.reason || item.heading || '-';
        const total = repairOrderListTotalText(item.grand_total, item.works_total);
        const paidTotal = repairOrderListTotalText(item.paid_total_display, item.paid_total);
        const paymentStatus = String(item.payment_status || '').trim().toLowerCase() === 'paid' ? 'paid' : 'unpaid';
        const paymentStatusLabel = String(item.payment_status_label || '').trim() || (paymentStatus === 'paid' ? 'Оплачен' : 'Не оплачен');
      const status = item.status_label || repairOrderStatusLabel(item.status);
      const rawStatus = normalizeRepairOrderStatus(item.status);
      const allTags = normalizeRepairOrderTags(item.tags || []);
      const previewTags = allTags.slice(0, 3);
      const extraTags = allTags.length - previewTags.length;
        const tagsHtml = previewTags.length
          ? '<div class="repair-orders-row__tags">' + previewTags.map((tag) => '<span class="tag" data-tag-color="' + escapeHtml(tag.color) + '"><span class="tag__dot"></span>' + escapeHtml(tag.label) + '</span>').join('') + (extraTags > 0 ? '<span class="tag">+' + extraTags + '</span>' : '') + '</div>'
          : '';
          return '<div class="archive-row repair-orders-row" role="button" tabindex="0" data-open-repair-order-card="' + escapeHtml(item.card_id) + '" title="Open repair order">'
            + '<div class="repair-orders-row__cell"><div class="repair-orders-row__number">' + escapeHtml(numberDigits) + '</div></div>'
            + '<div class="repair-orders-row__cell"><div class="repair-orders-row__dates"><div class="repair-orders-row__opened">' + escapeHtml(displayedDate) + '</div></div></div>'
            + '<div class="repair-orders-row__cell repair-orders-row__payment-cell"><div class="repair-orders-row__payment-status" data-payment-status="' + escapeHtml(paymentStatus) + '">' + escapeHtml(paymentStatusLabel) + '</div></div>'
            + '<div class="repair-orders-row__cell"><div class="repair-orders-row__client" title="' + escapeHtml(clientText) + '">' + escapeHtml(clientText) + '</div></div>'
            + '<div class="repair-orders-row__cell"><div class="repair-orders-row__phone" title="' + escapeHtml(phoneText) + '">' + escapeHtml(phoneText) + '</div></div>'
          + '<div class="repair-orders-row__cell"><div class="repair-orders-row__vehicle" title="' + escapeHtml(vehicle) + '">' + escapeHtml(vehicle) + '</div></div>'
          + '<div class="repair-orders-row__cell repair-orders-row__title-cell"><div class="repair-orders-row__title" title="' + escapeHtml(heading) + '">' + escapeHtml(heading) + '</div>' + tagsHtml + '</div>'
          + '<div class="repair-orders-row__cell repair-orders-row__paid-cell"><div class="repair-orders-row__paid" data-empty="' + String(paidTotal === '0') + '">' + escapeHtml(paidTotal) + '</div></div>'
          + '<div class="repair-orders-row__cell repair-orders-row__total-cell"><div class="repair-orders-row__total" data-empty="' + String(total === '0') + '">' + escapeHtml(total) + '</div></div>'
          + '</div>';
      }).join('');
    };
    function renderRepairOrders(data) {
      const items = data?.repair_orders || [];
      const meta = data?.meta || {};
      if (meta.status === 'open' || meta.status === 'ready' || meta.status === 'closed') state.repairOrdersFilter = meta.status;
      state.repairOrdersSortBy = normalizeRepairOrdersSortBy(meta.sort_by || state.repairOrdersSortBy);
      state.repairOrdersSortDir = normalizeRepairOrdersSortDir(meta.sort_dir || state.repairOrdersSortDir);
      state.repairOrdersItems = Array.isArray(items) ? items : [];
      state.repairOrdersMetaState = meta;
      updateRepairOrdersTabs();
      setRepairOrdersSearchLoading(false);
      renderRepairOrdersView();
    }

    function repairOrdersHasReusableOpenList() {
      const meta = state.repairOrdersMetaState || {};
      return Boolean(
        Array.isArray(state.repairOrdersItems)
        && state.repairOrdersItems.length
        && normalizeRepairOrderStatus(meta.status || state.repairOrdersFilter) === 'open'
        && normalizeRepairOrdersSortBy(meta.sort_by || state.repairOrdersSortBy) === 'opened_at'
        && normalizeRepairOrdersSortDir(meta.sort_dir || state.repairOrdersSortDir) === 'desc'
        && !String(state.repairOrdersRemoteQuery || '').trim()
      );
    }

    loadRepairOrders = async function(openModal = false) {
      state.repairOrdersRemoteQuery = '';
      await loadModalData(repairOrdersRequestPath(), {
        openModal,
        modalEl: els.repairOrdersModal,
        onSuccess: renderRepairOrders,
        onError: (error) => {
          setModalListError(
            els.repairOrdersMeta,
            els.repairOrdersList,
            'ОШИБКА ЗАГРУЗКИ СПИСКА ЗАКАЗ-НАРЯДОВ.',
            error.message,
          );
        },
      });
    };

    function applyRepairOrdersSearch() {
      if (state.repairOrdersLoadTimer) window.clearTimeout(state.repairOrdersLoadTimer);
      setRepairOrdersSearchLoading(true);
      state.repairOrdersLoadTimer = window.setTimeout(() => {
        state.repairOrdersLoadTimer = null;
        window.requestAnimationFrame(() => {
          renderRepairOrdersView();
          setRepairOrdersSearchLoading(false);
        });
      }, 1000);
    }

    function handleRepairOrdersSearchInput() {
      state.repairOrdersQuery = String(els.repairOrdersSearchInput?.value || '');
      applyRepairOrdersSearch();
    }

    function handleRepairOrdersSearchFieldClick(event) {
      const button = event.target.closest('[data-repair-orders-search-field]');
      if (!button) return;
      const nextField = normalizeRepairOrdersSearchField(button.dataset.repairOrdersSearchField);
      if (state.repairOrdersSearchField === nextField) return;
      if (state.repairOrdersLoadTimer) {
        window.clearTimeout(state.repairOrdersLoadTimer);
        state.repairOrdersLoadTimer = null;
      }
      setRepairOrdersSearchLoading(false);
      state.repairOrdersSearchField = nextField;
      syncRepairOrdersLayout();
      renderRepairOrdersView();
    }

    function handleRepairOrdersSortChange() {
      if (state.repairOrdersLoadTimer) {
        window.clearTimeout(state.repairOrdersLoadTimer);
        state.repairOrdersLoadTimer = null;
      }
      setRepairOrdersSearchLoading(false);
      state.repairOrdersSortBy = normalizeRepairOrdersSortBy(els.repairOrdersSortBy?.value);
      state.repairOrdersSortDir = normalizeRepairOrdersSortDir(els.repairOrdersSortDir?.value);
      loadRepairOrders(false);
    }

    loadGptWall = async function(openModal = false) {
      await loadModalData('/api/get_gpt_wall', {
        method: 'POST',
        body: { include_archived: true, event_limit: 100 },
        openModal,
        modalEl: els.gptWallModal,
        onSuccess: renderGptWall,
        onError: (error) => {
          setModalTextError(
            els.gptWallMeta,
            els.gptWallText,
            'ОШИБКА ЗАГРУЗКИ СЛОЯ GPT.',
            error.message,
          );
        },
      });
    };

    function sortBoardCards(cards) {
      return (Array.isArray(cards) ? cards : []).slice().sort((left, right) =>
        ((left.position ?? 0) - (right.position ?? 0))
        || String(left.created_at || '').localeCompare(String(right.created_at || ''))
        || String(left.id || '').localeCompare(String(right.id || ''))
      );
    }

    function sortBoardColumns(columns) {
      return (Array.isArray(columns) ? columns : []).slice().sort((left, right) =>
        ((left.position ?? 0) - (right.position ?? 0))
        || String(left.label || '').localeCompare(String(right.label || ''), 'ru')
        || String(left.id || '').localeCompare(String(right.id || ''))
      );
    }

    function buildBoardCardsByColumn(snapshot) {
      const grouped = new Map();
      (snapshot?.cards || []).forEach((card) => {
        const columnId = String(card?.column || '').trim();
        if (!columnId) return;
        const bucket = grouped.get(columnId);
        if (bucket) bucket.push(card);
        else grouped.set(columnId, [card]);
      });
      grouped.forEach((bucket, columnId) => grouped.set(columnId, sortBoardCards(bucket)));
      return grouped;
    }

    function sortedCardsForBoardColumn(snapshot, columnId, cardsByColumn = null) {
      if (cardsByColumn instanceof Map) return cardsByColumn.get(columnId) || [];
      const cards = (snapshot?.cards || []).filter((card) => card.column === columnId);
      return sortBoardCards(cards);
    }

    function renderBoardColumnHtml(column, index, snapshot, cardsByColumn = null) {
      const cards = sortedCardsForBoardColumn(snapshot, column.id, cardsByColumn);
      const tone = COLUMN_TONES[index % COLUMN_TONES.length];
      const toneStyle = '--column-tint:' + tone.tint + ';--column-head:' + tone.head + ';--column-edge:' + tone.edge + ';--column-empty:' + tone.empty + ';';
      const isReadyColumn = String(column.label || '').trim().toLowerCase() === READY_COLUMN_LABEL.toLowerCase();
      const isDeleteBlocked = isReadyColumn || cards.length > 0 || snapshot.columns.length <= 1;
      const deleteTitle = isReadyColumn
        ? 'Системную колонку готовых автомобилей нельзя удалить'
        : (cards.length > 0
        ? 'Сначала убери карточки из этого столбца'
        : (snapshot.columns.length <= 1 ? 'Последний столбец нельзя удалить' : 'Удалить пустой столбец'));
      const renameTitle = isReadyColumn ? 'Системную колонку готовых автомобилей нельзя переименовать' : 'Переименовать столбец';
      const deleteAttrs = isDeleteBlocked ? ' disabled' : '';
      const renameAttrs = isReadyColumn ? ' disabled data-system-column="ready"' : '';
      return '<section class="column" style="' + toneStyle + '" data-column-id="' + escapeHtml(column.id) + '" draggable="true"><div class="column__head" data-drag-column-handle="1"><div class="column__title">' + escapeHtml(column.label) + '</div><div class="column__head-actions"><button class="btn btn--ghost column__rename" type="button" data-rename-column="' + escapeHtml(column.id) + '" data-column-label="' + escapeHtml(column.label) + '" title="' + escapeHtml(renameTitle) + '" aria-label="' + escapeHtml(renameTitle) + '"' + renameAttrs + '>&#9998;</button><button class="btn btn--ghost column__delete" type="button" data-delete-column="' + escapeHtml(column.id) + '" data-column-label="' + escapeHtml(column.label) + '" data-card-count="' + cards.length + '" title="' + escapeHtml(deleteTitle) + '" aria-label="' + escapeHtml(deleteTitle) + '"' + deleteAttrs + '>&times;</button><div class="column__count">' + cards.length + '</div></div></div><div class="column__cards">' + (cards.length ? cards.map(renderBoardCardHtml).join('') : '') + '</div><button class="btn" type="button" data-create-in="' + escapeHtml(column.id) + '">+ КАРТОЧКА</button></section>';
    }

    function renderBoardColumnById(columnId, cardsByColumn = null) {
      const snapshot = state.snapshot;
      if (!snapshot || !columnId) return false;
      const columnIndex = snapshot.columns.findIndex((column) => column.id === columnId);
      if (columnIndex < 0) return false;
      const currentSection = els.board.querySelector('[data-column-id="' + columnId + '"]');
      if (!currentSection) return false;
      const template = document.createElement('template');
      template.innerHTML = renderBoardColumnHtml(snapshot.columns[columnIndex], columnIndex, snapshot, cardsByColumn);
      const nextSection = template.content.firstElementChild;
      if (!nextSection) return false;
      currentSection.replaceWith(nextSection);
      return true;
    }

    function renderBoard() {
      const perfToken = perfStart('renderBoard');
      const snapshot = state.snapshot;
      if (!snapshot) {
        perfEnd(perfToken, { skipped: true });
        return;
      }
      const cardsByColumn = buildBoardCardsByColumn(snapshot);
      const addColumnButtonHtml = '<button class="board-add-column" type="button" data-create-column="true" title="Добавить столбец" aria-label="Добавить столбец">+</button>';
      els.board.innerHTML = snapshot.columns.map((column, index) => renderBoardColumnHtml(column, index, snapshot, cardsByColumn)).join('') + addColumnButtonHtml + '<div class="sticky-layer" id="stickyLayer"></div>';
      els.stickyLayer = document.getElementById('stickyLayer');
      renderStickies();
      renderMobileShell();
      perfEnd(perfToken, { cards: snapshot.cards?.length || 0, columns: snapshot.columns?.length || 0 });
    }

    function setTab(name) {
      const nextName = name;
      state.currentTab = nextName;
      document.querySelectorAll('[data-tab]').forEach((button) => button.classList.toggle('is-active', button.dataset.tab === nextName));
      document.querySelectorAll('[data-panel]').forEach((panel) => panel.classList.toggle('hidden', panel.dataset.panel !== nextName));
      loadActiveCardTab(nextName);
    }

    function focusCardModalInitialControl() {
      if (!els.cardModal?.classList.contains('is-open')) return;
      if (state.currentTab !== 'overview') return;
      if (els.cardModal.contains(document.activeElement) && document.activeElement !== document.body) return;
      els.cardVehicle?.focus({ preventScroll: true });
    }

    function openCardModal(card, { descriptionLoading = false, cardIsFull = true, preserveTab = false } = {}) {
      applyCardModalState(card, { descriptionLoading, cardIsFull, preserveLazyPanels: preserveTab });
      if (!preserveTab) setTab('overview');
      else loadActiveCardTab(state.currentTab);
      pushModal('card', els.cardModal);
      requestAnimationFrame(() => {
        syncCardSaveDirtyState();
        syncCardDescriptionHeight();
        focusCardModalInitialControl();
      });
    }

    function closeCardModal({ force = false } = {}) {
      if (state.cardSaveInFlight) {
        state.cardCloseAfterSave = true;
        setStatus('СОХРАНЯЮ КАРТОЧКУ. ЗАКРОЮ ПОСЛЕ СОХРАНЕНИЯ.', false);
        return false;
      }
      if (!force && cardModalHasUnsavedChanges()) {
        const confirmed = window.confirm('Есть несохраненные изменения. Закрыть карточку без сохранения?');
        if (!confirmed) return false;
      }
      closeCardClientCreateModal();
      closeRepairOrderModal();
      clearFilePreview({ sync: false });
      popModal('card');
      resetCardModalState();
      stopCardCleanupPolling();
      return true;
    }
    window.__closeCardModal = closeCardModal;

    function bindDirectCardModalCloseButtons() {
      [els.cardModalCloseButtonTop, els.cardModalCloseButtonBottom].forEach((button) => {
        if (!(button instanceof HTMLElement)) return;
        button.addEventListener('click', (event) => {
          event.preventDefault();
          event.stopPropagation();
          closeCardModal();
        });
      });
    }

    function cardUpdatedAtMs(value) {
      const parsed = Date.parse(String(value || '').trim());
      return Number.isFinite(parsed) ? parsed : 0;
    }

    function pruneCardSeenSuppressions(nowMs = Date.now()) {
      for (const [cardId, suppression] of state.cardSeenSuppressions.entries()) {
        const suppressedAtMs = finiteNonNegativeNumber(suppression?.suppressed_at_ms);
        if (!suppressedAtMs || nowMs - suppressedAtMs > CARD_SEEN_SUPPRESSION_TTL_MS) {
          state.cardSeenSuppressions.delete(cardId);
        }
      }
    }

    function recordCardSeenSuppression(cardId, updatedAt = '') {
      const normalizedCardId = String(cardId || '').trim();
      if (!normalizedCardId) return;
      pruneCardSeenSuppressions();
      state.cardSeenSuppressions.set(normalizedCardId, {
        updated_at: String(updatedAt || '').trim(),
        suppressed_at_ms: Date.now(),
      });
    }

    function incomingCardIsNewerThanSuppression(card, suppression) {
      const incomingUpdatedAt = String(card?.updated_at || '').trim();
      const suppressedUpdatedAt = String(suppression?.updated_at || '').trim();
      const incomingMs = cardUpdatedAtMs(incomingUpdatedAt);
      const suppressedMs = cardUpdatedAtMs(suppressedUpdatedAt);
      if (incomingMs && suppressedMs) return incomingMs > suppressedMs;
      if (incomingUpdatedAt && suppressedUpdatedAt) return incomingUpdatedAt > suppressedUpdatedAt;
      return false;
    }

    function applyCardSeenSuppression(card) {
      const cardId = String(card?.id || '').trim();
      if (!cardId) return card;
      pruneCardSeenSuppressions();
      const suppression = state.cardSeenSuppressions.get(cardId);
      if (!suppression) return card;
      if (incomingCardIsNewerThanSuppression(card, suppression)) {
        state.cardSeenSuppressions.delete(cardId);
        return card;
      }
      if (!card.is_unread && !card.has_unseen_update) return card;
      return { ...card, is_unread: false, has_unseen_update: false };
    }

    function applyCardSeenSuppressionsToCards(cards) {
      if (!Array.isArray(cards)) return cards;
      return cards.map((card) => applyCardSeenSuppression(card));
    }

    function applyCardSeenSuppressionsToSnapshot(snapshot) {
      if (!snapshot || typeof snapshot !== 'object') return snapshot;
      return {
        ...snapshot,
        cards: applyCardSeenSuppressionsToCards(snapshot.cards),
      };
    }

    async function refreshSnapshot(showSuccess = false) {
      return perfMeasureAsync('refreshSnapshot', async () => {
        if (state.refreshInFlight) {
          const pending = state.refreshInFlight;
          await pending;
          if (!showSuccess) return;
        }

        state.refreshInFlight = (async () => {
          try {
            if (!state.snapshot || els.statusLine?.dataset.connection === 'offline') showConnectionPendingStatus();
            const nextSnapshot = applyCardSeenSuppressionsToSnapshot(await api('/api/get_board_snapshot?compact=1&include_archive=0'));
            const previousRevision = String(state.lastSnapshotRevision || '');
            const nextRevision = String(nextSnapshot?.meta?.revision || '');
            const boardChanged = !previousRevision || !nextRevision || previousRevision !== nextRevision;
            state.snapshot = nextSnapshot;
            applyBoardScalePreference({ fallbackValue: state.snapshot?.settings?.board_scale ?? 1, syncInput: true, persistFallback: true });
            if (boardChanged) {
              renderBoard();
              primeBoardViewport();
            }
            state.lastSnapshotRevision = nextRevision;
            if (els.archiveModal.classList.contains('is-open')) {
              await loadArchive(false, { force: true });
            }
            if (els.gptWallModal.classList.contains('is-open')) await loadGptWall(false);
            updateSnapshotStatusLine({ showSuccess });
          } catch (error) {
            setStatus(error.message, true);
          } finally {
            state.refreshInFlight = null;
          }
        })();

        return state.refreshInFlight;
      });
    }

    async function refreshSnapshotRevision() {
      return perfMeasureAsync('refreshSnapshotRevision', async () => {
        try {
          if (!state.lastSnapshotRevision) {
            await refreshSnapshot(false);
            return;
          }
          if (els.statusLine?.dataset.connection === 'offline') showConnectionPendingStatus();
          const data = await api('/api/get_board_revision?compact=1&include_archive=0');
          const nextRevision = String(data?.revision || data?.meta?.revision || '');
          if (!nextRevision || nextRevision !== String(state.lastSnapshotRevision || '')) {
            await refreshSnapshot(false);
            return;
          }
          updateSnapshotStatusLine();
        } catch (error) {
          setStatus(error.message, true);
        }
      });
    }

    function snapshotCardById(cardId) {
      if (!cardId) return null;
      const cards = state.snapshot?.cards || [];
      const archive = state.archiveCards || [];
      return cards.find((card) => card.id === cardId) || archive.find((card) => card.id === cardId) || null;
    }

    function cacheFullCard(card) {
      const cardId = String(card?.id || '').trim();
      if (!cardId) return null;
      state.fullCardCache.set(cardId, card);
      return card;
    }

    function cachedFullCardForSnapshot(card) {
      const cardId = String(card?.id || '').trim();
      if (!cardId) return null;
      const cachedCard = state.fullCardCache.get(cardId);
      if (!cachedCard) return null;
      const expectedUpdatedAt = String(card?.updated_at || '').trim();
      if (expectedUpdatedAt && String(cachedCard.updated_at || '').trim() !== expectedUpdatedAt) return null;
      return cachedCard;
    }

    async function fetchFullCard(cardId, expectedUpdatedAt = '') {
      const normalizedCardId = String(cardId || '').trim();
      if (!normalizedCardId) return null;
      const cachedCard = state.fullCardCache.get(normalizedCardId);
      const normalizedExpectedUpdatedAt = String(expectedUpdatedAt || '').trim();
      if (cachedCard && (!normalizedExpectedUpdatedAt || String(cachedCard.updated_at || '').trim() === normalizedExpectedUpdatedAt)) return cachedCard;
      const pending = state.cardFetchInFlight.get(normalizedCardId);
      if (pending) return pending;
      const request = api('/api/get_card?card_id=' + encodeURIComponent(normalizedCardId))
        .then((data) => cacheFullCard(applyCardSeenSuppression(data?.card)))
        .finally(() => state.cardFetchInFlight.delete(normalizedCardId));
      state.cardFetchInFlight.set(normalizedCardId, request);
      return request;
    }

    function boardCardElementById(cardId) {
      if (!cardId) return null;
      return els.board?.querySelector('.card[data-card-id="' + cardId + '"]') || null;
    }

    function replaceBoardCardElement(nextCard) {
      const currentCard = boardCardElementById(nextCard?.id);
      if (!currentCard) return false;
      const template = document.createElement('template');
      template.innerHTML = renderBoardCardHtml(nextCard);
      const nextCardElement = template.content.firstElementChild;
      if (!nextCardElement) return false;
      currentCard.replaceWith(nextCardElement);
      return true;
    }

    function updateSnapshotStatusLine({ showSuccess = false } = {}) {
      const data = state.snapshot;
      if (!data) return;
      setStatus(
        showSuccess
          ? ('ДОСКА ОБНОВЛЕНА · ' + new Date().toLocaleTimeString('ru-RU'))
          : 'СЕРВЕР АКТИВЕН',
        false,
      );
    }

    function applyBoardColumnCardsPatch(nextCards, affectedColumnIds) {
      if (!Array.isArray(state.snapshot?.cards) || !Array.isArray(nextCards) || !Array.isArray(affectedColumnIds)) return false;
      const normalizedColumnIds = affectedColumnIds
        .map((value) => String(value || '').trim())
        .filter(Boolean);
      if (!normalizedColumnIds.length) return false;
      const targetColumns = new Set(normalizedColumnIds);
      const suppressedNextCards = applyCardSeenSuppressionsToCards(nextCards);
      const nextCardMap = new Map(suppressedNextCards.filter((card) => card?.id).map((card) => [card.id, card]));
      state.snapshot.cards = state.snapshot.cards
        .filter((card) => !targetColumns.has(String(card.column || '').trim()))
        .concat(suppressedNextCards);
      if (state.activeCard?.id) {
        const nextActiveCard = nextCardMap.get(state.activeCard.id);
        if (nextActiveCard) state.activeCard = nextActiveCard;
      }
      const cardsByColumn = buildBoardCardsByColumn(state.snapshot);
      let renderedAny = false;
      for (const columnId of normalizedColumnIds) {
        renderedAny = renderBoardColumnById(columnId, cardsByColumn) || renderedAny;
      }
      return renderedAny;
    }

    function applyBoardColumnsPatch(nextColumns) {
      if (!Array.isArray(state.snapshot?.columns) || !Array.isArray(nextColumns)) return false;
      state.snapshot.columns = sortBoardColumns(nextColumns);
      renderBoard();
      updateSnapshotStatusLine({ showSuccess: true });
      return true;
    }

    function applyArchivedCardPatch(nextCard) {
      if (!nextCard?.id || !Array.isArray(state.snapshot?.cards)) return false;
      const suppressedNextCard = applyCardSeenSuppression(nextCard);
      const previousCard = snapshotCardById(suppressedNextCard.id);
      state.snapshot.cards = state.snapshot.cards.filter((card) => card.id !== suppressedNextCard.id);
      if (Array.isArray(state.archiveCards)) {
        state.archiveCards = state.archiveCards.filter((card) => card.id !== suppressedNextCard.id);
      }
      if (suppressedNextCard.archived) {
        if (state.archiveLoaded) {
          state.archiveCards = [suppressedNextCard].concat(state.archiveCards).slice(0, ARCHIVE_PREVIEW_LIMIT);
        }
      } else {
        state.snapshot.cards = state.snapshot.cards.concat(suppressedNextCard);
      }
      if (state.activeCard?.id === suppressedNextCard.id) state.activeCard = suppressedNextCard.archived ? null : suppressedNextCard;
      const affectedColumnId = String((suppressedNextCard.column || previousCard?.column || '')).trim();
      if (affectedColumnId) {
        const cardsByColumn = buildBoardCardsByColumn(state.snapshot);
        if (!renderBoardColumnById(affectedColumnId, cardsByColumn)) renderBoard();
      } else {
        renderBoard();
      }
      if (els.archiveModal.classList.contains('is-open')) renderArchive();
      updateSnapshotStatusLine();
      return true;
    }

    function applyStickySnapshot(stickies) {
      if (!Array.isArray(state.snapshot?.stickies) || !Array.isArray(stickies)) return false;
      state.snapshot.stickies = stickies;
      renderStickies();
      return true;
    }

    function replaceSnapshotCard(nextCard) {
      if (!nextCard?.id) return;
      const suppressedNextCard = applyCardSeenSuppression(nextCard);
      const previousCard = snapshotCardById(suppressedNextCard.id);
      if (Array.isArray(state.snapshot?.cards)) {
        state.snapshot.cards = state.snapshot.cards.map((card) => card.id === suppressedNextCard.id ? suppressedNextCard : card);
      }
      if (Array.isArray(state.archiveCards)) {
        state.archiveCards = state.archiveCards.map((card) => card.id === suppressedNextCard.id ? suppressedNextCard : card);
      }
      if (state.activeCard?.id === suppressedNextCard.id) state.activeCard = suppressedNextCard;
      const archiveOpen = els.archiveModal.classList.contains('is-open');
      const touchesArchive = previousCard?.archived || suppressedNextCard.archived;
      if (archiveOpen && touchesArchive) renderArchive();
      if (!previousCard || previousCard.archived || suppressedNextCard.archived) {
        renderBoard();
        if (archiveOpen && !touchesArchive) renderArchive();
        return;
      }
      const previousColumnId = String(previousCard.column || '').trim();
      const nextColumnId = String(suppressedNextCard.column || '').trim();
      if (previousColumnId && previousColumnId === nextColumnId) {
        const previousPosition = finiteNumber(previousCard.position, NaN);
        const nextPosition = finiteNumber(suppressedNextCard.position, NaN);
        const samePosition = previousPosition === nextPosition || (Number.isNaN(previousPosition) && Number.isNaN(nextPosition));
        if (samePosition && replaceBoardCardElement(suppressedNextCard)) return;
        const cardsByColumn = buildBoardCardsByColumn(state.snapshot);
        if (!renderBoardColumnById(previousColumnId, cardsByColumn)) renderBoard();
        return;
      }
      const cardsByColumn = buildBoardCardsByColumn(state.snapshot);
      const renderedPrevious = previousColumnId ? renderBoardColumnById(previousColumnId, cardsByColumn) : false;
      const renderedNext = nextColumnId ? renderBoardColumnById(nextColumnId, cardsByColumn) : false;
      if (!renderedPrevious || !renderedNext) renderBoard();
    }

    function boardCardFromFullCard(card) {
      if (!card?.id) return card;
      const preview = stripDescriptionFormatting(card.description_preview || card.board_summary || card.description || '');
      return {
        ...card,
        description: preview,
        description_preview: preview,
        board_summary: card.board_summary || preview,
      };
    }

    function applySavedCardLocalPatch(card) {
      if (!card?.id || !Array.isArray(state.snapshot?.cards)) return false;
      const suppressedCard = applyCardSeenSuppression(card);
      cacheFullCard(suppressedCard);
      const nextCard = boardCardFromFullCard(suppressedCard);
      const previousCard = snapshotCardById(nextCard.id);
      if (previousCard) {
        replaceSnapshotCard(nextCard);
        updateSnapshotStatusLine({ showSuccess: true });
        return true;
      }
      if (nextCard.archived) return false;
      state.snapshot.cards = state.snapshot.cards.concat(nextCard);
      const cardsByColumn = buildBoardCardsByColumn(state.snapshot);
      const columnId = String(nextCard.column || '').trim();
      if (!columnId || !renderBoardColumnById(columnId, cardsByColumn)) renderBoard();
      updateSnapshotStatusLine({ showSuccess: true });
      return true;
    }

    function scheduleBackgroundSnapshotRefresh({ showSuccess = false, delay = 900 } = {}) {
      if (state.backgroundSnapshotTimer) window.clearTimeout(state.backgroundSnapshotTimer);
      state.backgroundSnapshotTimer = window.setTimeout(() => {
        state.backgroundSnapshotTimer = null;
        refreshSnapshot(showSuccess);
      }, Math.max(0, finiteNumber(delay)));
    }

    function clearUnreadHoverTimer(cardId) {
      if (!cardId) return;
      const timerId = state.unreadHoverTimers.get(cardId);
      if (timerId) {
        clearTimeout(timerId);
        state.unreadHoverTimers.delete(cardId);
      }
    }

    function markCardSeenOptimistically(cardId) {
      const normalizedCardId = String(cardId || '').trim();
      if (!normalizedCardId) return false;
      clearUnreadHoverTimer(normalizedCardId);
      const currentCard = snapshotCardById(normalizedCardId);
      const cardElement = boardCardElementById(normalizedCardId);
      const suppressionUpdatedAt = currentCard?.updated_at || (state.activeCard?.id === normalizedCardId ? state.activeCard.updated_at : '');
      const hadMarker = Boolean(
        currentCard?.is_unread
        || currentCard?.has_unseen_update
        || cardElement?.querySelector('.card__unread-badge, .card__updated-badge')
      );
      recordCardSeenSuppression(normalizedCardId, suppressionUpdatedAt);
      if (currentCard) {
        currentCard.is_unread = false;
        currentCard.has_unseen_update = false;
      }
      if (state.activeCard?.id === normalizedCardId) {
        state.activeCard.is_unread = false;
        state.activeCard.has_unseen_update = false;
      }
      if (cardElement) {
        cardElement.dataset.unread = 'false';
        cardElement.dataset.updatedUnseen = 'false';
        cardElement.querySelectorAll('.card__unread-badge, .card__updated-badge').forEach((badge) => badge.remove());
      }
      return hadMarker;
    }

    function deferCardSeen(cardId, { force = false } = {}) {
      const normalizedCardId = String(cardId || '').trim();
      if (!normalizedCardId) return;
      const existingTimer = state.unreadSeenDeferredTimers.get(normalizedCardId);
      if (existingTimer) window.clearTimeout(existingTimer);
      const timerId = window.setTimeout(() => {
        state.unreadSeenDeferredTimers.delete(normalizedCardId);
        markCardSeen(normalizedCardId, { force });
      }, 500);
      state.unreadSeenDeferredTimers.set(normalizedCardId, timerId);
    }

    async function markCardSeen(cardId, { force = false } = {}) {
      const normalizedCardId = String(cardId || '').trim();
      if (!normalizedCardId) return;
      if (state.cardSaveInFlight) {
        deferCardSeen(normalizedCardId, { force });
        return;
      }
      const currentCard = snapshotCardById(normalizedCardId) || (state.activeCard?.id === normalizedCardId ? state.activeCard : null);
      if (!force && currentCard && !currentCard.is_unread && !currentCard.has_unseen_update) return;
      if (!force) markCardSeenOptimistically(normalizedCardId);
      if (state.unreadSeenInFlight.has(normalizedCardId)) return;
      state.unreadSeenInFlight.add(normalizedCardId);
      try {
        const data = await api('/api/mark_card_seen', {
          method: 'POST',
          body: { card_id: normalizedCardId, actor_name: state.actor, source: 'ui' },
        });
        if (data?.card) replaceSnapshotCard(data.card);
      } catch (_) {
      } finally {
        state.unreadSeenInFlight.delete(normalizedCardId);
      }
    }

    function scheduleCardSeen(cardId) {
      if (!cardId) return;
      const currentCard = snapshotCardById(cardId);
      if (!currentCard || (!currentCard.is_unread && !currentCard.has_unseen_update)) return;
      if (state.unreadSeenInFlight.has(cardId)) return;
      clearUnreadHoverTimer(cardId);
      const delayMs = currentCard.has_unseen_update && !currentCard.is_unread ? CARD_UPDATED_HOVER_DELAY_MS : CARD_UNREAD_HOVER_DELAY_MS;
      const timerId = setTimeout(() => {
        state.unreadHoverTimers.delete(cardId);
        markCardSeen(cardId);
      }, delayMs);
      state.unreadHoverTimers.set(cardId, timerId);
    }

    function stopSnapshotPolling() {
      if (state.pollHandle) {
        clearTimeout(state.pollHandle);
        state.pollHandle = null;
      }
    }

    function hasOpenWorkspaceModal() {
      const workspaceKeys = [
        'card',
        'archive',
        'repair-orders',
        'clients',
        'shared-files',
        'cashboxes',
        'cashbox-journal',
        'cashbox-transfer',
        'employees',
        'employeeSalary',
        'employee-salary-report',
        'agent',
        'agent-tasks',
        'wall',
        'settings',
        'sticky',
        'repair-order',
        'repair-order-payments',
        'operator-profile',
        'operator-admin',
      ];
      return state.modalStack.some((entry) => workspaceKeys.includes(entry?.key))
        || workspaceKeys.some((key) => modalElementForKey(key)?.classList.contains('is-open'));
    }

    function snapshotPollIntervalMs() {
      if (document.hidden) return SNAPSHOT_POLL_HIDDEN_INTERVAL_MS;
      if (hasOpenWorkspaceModal()) return SNAPSHOT_POLL_MODAL_INTERVAL_MS;
      return SNAPSHOT_POLL_INTERVAL_MS;
    }

    function scheduleNextSnapshotPoll() {
      stopSnapshotPolling();
      if (perfEnabled()) {
        stopSnapshotPolling();
        return;
      }
      state.pollHandle = window.setTimeout(async () => {
        state.pollHandle = null;
        await refreshSnapshotRevision();
        scheduleNextSnapshotPoll();
      }, snapshotPollIntervalMs());
    }

    function startSnapshotPolling() {
      scheduleNextSnapshotPoll();
    }

    function handleSnapshotVisibilityChange() {
      if (perfEnabled()) {
        stopSnapshotPolling();
        return;
      }
      startSnapshotPolling();
      if (!document.hidden) refreshSnapshotRevision();
    }

    function cardJournalLoadKey(cardId, limit = state.cardJournalLimit) {
      return String(cardId || '').trim() + ':' + Math.min(CARD_JOURNAL_MAX_LIMIT, Math.max(1, finiteNumber(limit, CARD_JOURNAL_INITIAL_LIMIT)));
    }

    function cardJournalRequestUrl(cardId, limit = state.cardJournalLimit) {
      const safeLimit = Math.min(CARD_JOURNAL_MAX_LIMIT, Math.max(1, finiteNumber(limit, CARD_JOURNAL_INITIAL_LIMIT)));
      return '/api/get_card_log?card_id=' + encodeURIComponent(cardId) + '&compact=1&limit=' + safeLimit;
    }

    function handleCardJournalLoadMore(trigger) {
      const nextLimit = Math.min(CARD_JOURNAL_MAX_LIMIT, Math.max(1, finiteNumber(trigger?.dataset?.cardJournalLoadMore)));
      if (!nextLimit || nextLimit <= state.cardJournalLimit) return;
      state.cardJournalLimit = nextLimit;
      state.cardJournalLoadedFor = '';
      loadActiveCardTab('journal');
    }

    function loadActiveCardTab(tabName) {
      const cardId = String(state.activeCard?.id || '').trim();
      if (tabName === 'files') {
        renderActiveCardFiles();
        return;
      }
      if (tabName !== 'journal') return;
      if (!cardId) {
        renderLogs([]);
        return;
      }
      const loadKey = cardJournalLoadKey(cardId);
      if (state.cardJournalLoadedFor === loadKey) return;
      state.cardJournalLoadedFor = loadKey;
      els.logList.className = 'card-journal-text';
      els.logList.textContent = 'Загрузка журнала...';
      loadLogs(cardId, state.cardJournalLimit);
    }

    async function loadLogs(cardId, limit = state.cardJournalLimit) {
      const perfToken = perfStart('loadLogs');
      const loadKey = cardJournalLoadKey(cardId, limit);
      try {
        const data = await api(cardJournalRequestUrl(cardId, limit));
        renderLogs(data);
      } catch (error) {
        if (state.cardJournalLoadedFor === loadKey) state.cardJournalLoadedFor = '';
        renderLogs({
          events: [{
            message: error.message,
            timestamp: new Date().toISOString(),
            actor_name: 'СИСТЕМА',
            source: 'ui',
            action: 'journal_error',
            details: {},
          }],
          meta: {
            card_heading: 'ЖУРНАЛ КАРТОЧКИ',
            card_short_id: '',
          },
        });
      } finally {
        perfEnd(perfToken, { card_id: cardId || '', limit: limit || CARD_JOURNAL_INITIAL_LIMIT });
      }
    }

    async function openCardById(cardId) {
      try {
        await openCardWorkspace(cardId);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    function clearCardDropState() {
      state.boardDropColumnId = '';
      state.boardDropBeforeCardId = '';
      document.querySelectorAll('.column.is-drop-target').forEach((column) => column.classList.remove('is-drop-target'));
      document.querySelectorAll('.card.is-drop-before').forEach((card) => card.classList.remove('is-drop-before'));
    }

    function finishCardDrag() {
      clearCardDropState();
      if (state.boardDragCardId) {
        const dragged = document.querySelector('.card[data-card-id="' + state.boardDragCardId + '"]');
        if (dragged) dragged.classList.remove('is-dragging');
      }
      state.boardDragCardId = '';
    }

    function clearColumnDropState() {
      state.boardDropBeforeColumnId = '';
      document.querySelectorAll('.column.is-column-drop-target').forEach((column) => column.classList.remove('is-column-drop-target'));
    }

    function finishColumnDrag() {
      clearColumnDropState();
      if (state.boardDragColumnId) {
        const dragged = document.querySelector('.column[data-column-id="' + state.boardDragColumnId + '"]');
        if (dragged) dragged.classList.remove('is-column-dragging');
      }
      state.boardDragColumnId = '';
    }

    function finishBoardDrag() {
      finishCardDrag();
      finishColumnDrag();
    }

    function updateBoardDragAutoScroll(clientX, clientY) {
      if ((!state.boardDragCardId && !state.boardDragColumnId) || !els.boardScroll) return;
      const rect = els.boardScroll.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const edgeThresholdX = Math.max(48, Math.min(96, Math.round(rect.width * 0.12)));
      const edgeThresholdY = Math.max(48, Math.min(96, Math.round(rect.height * 0.12)));
      const maxStepX = Math.max(18, Math.round(edgeThresholdX * 0.34));
      const maxStepY = Math.max(18, Math.round(edgeThresholdY * 0.34));
      let deltaX = 0;
      let deltaY = 0;
      if (clientX < rect.left + edgeThresholdX) {
        deltaX = -Math.round(((rect.left + edgeThresholdX) - clientX) / edgeThresholdX * maxStepX);
      } else if (clientX > rect.right - edgeThresholdX) {
        deltaX = Math.round((clientX - (rect.right - edgeThresholdX)) / edgeThresholdX * maxStepX);
      }
      if (clientY < rect.top + edgeThresholdY) {
        deltaY = -Math.round(((rect.top + edgeThresholdY) - clientY) / edgeThresholdY * maxStepY);
      } else if (clientY > rect.bottom - edgeThresholdY) {
        deltaY = Math.round((clientY - (rect.bottom - edgeThresholdY)) / edgeThresholdY * maxStepY);
      }
      if (!deltaX && !deltaY) return;
      clampBoardScroll(els.boardScroll.scrollLeft + deltaX, els.boardScroll.scrollTop + deltaY);
    }

    function resolveDropBeforeCardId(column, clientY, draggedCardId) {
      const cards = Array.from(column.querySelectorAll('.card')).filter((card) => card.dataset.cardId !== draggedCardId);
      for (const card of cards) {
        const rect = card.getBoundingClientRect();
        if (clientY < rect.top + (rect.height / 2)) return card.dataset.cardId || '';
      }
      return '';
    }

    function resolveDropBeforeColumnId(column, clientX, draggedColumnId) {
      const dragged = String(draggedColumnId || '').trim();
      const columns = Array.from(els.board?.querySelectorAll('.column[data-column-id]') || []);
      const hoveredId = String(column?.dataset?.columnId || '').trim();
      if (!hoveredId || hoveredId === dragged) return '';
      const rect = column.getBoundingClientRect();
      const insertBeforeHovered = clientX < rect.left + (rect.width / 2);
      if (insertBeforeHovered) return hoveredId;
      const orderedColumns = columns.filter((item) => String(item.dataset.columnId || '').trim() !== dragged);
      const hoveredIndex = orderedColumns.findIndex((item) => String(item.dataset.columnId || '').trim() === hoveredId);
      if (hoveredIndex < 0 || hoveredIndex === orderedColumns.length - 1) return '';
      return String(orderedColumns[hoveredIndex + 1].dataset.columnId || '').trim();
    }

    function updateCardDropState(column, beforeCardId) {
      clearCardDropState();
      if (!column) return;
      state.boardDropColumnId = column.dataset.columnId || '';
      state.boardDropBeforeCardId = beforeCardId || '';
      column.classList.add('is-drop-target');
      if (!beforeCardId) return;
      const beforeCard = column.querySelector('.card[data-card-id="' + beforeCardId + '"]');
      if (beforeCard) beforeCard.classList.add('is-drop-before');
    }

    async function moveCard(cardId, columnId, beforeCardId = '') {
      return perfMeasureAsync('moveCard', async () => {
        try {
          clearCardOpenSideEffectTimer();
          const data = await api('/api/move_card', {
            method: 'POST',
            body: {
              card_id: cardId,
              column: columnId,
              before_card_id: beforeCardId || undefined,
              actor_name: state.actor,
              source: 'ui',
            },
          });
          const patched = applyBoardColumnCardsPatch(data?.affected_cards || [], data?.affected_column_ids || []);
          if (!patched && data?.card) {
            replaceSnapshotCard(data.card);
          }
          if (!patched && !data?.card) {
            await refreshSnapshot(true);
          } else {
            setStatus('ДОСКА ОБНОВЛЕНА · ' + new Date().toLocaleTimeString('ru-RU'), false);
          }
          return true;
        } catch (error) {
          setStatus(error.message, true);
          return false;
        } finally {
          finishCardDrag();
        }
      });
    }

    async function moveColumn(columnId, beforeColumnId = '') {
      try {
        const data = await api('/api/move_column', {
          method: 'POST',
          body: {
            column_id: columnId,
            before_column_id: beforeColumnId || undefined,
            actor_name: state.actor,
            source: 'ui',
          },
        });
        if (!applyBoardColumnsPatch(data?.columns || [])) {
          await refreshSnapshot(true);
        }
      } catch (error) {
        setStatus(error.message, true);
      } finally {
        finishColumnDrag();
      }
    }

    async function restoreCard(cardId) {
      try {
        const data = await api('/api/restore_card', { method: 'POST', body: { card_id: cardId, actor_name: state.actor, source: 'ui' } });
        if (data?.card && applyArchivedCardPatch(data.card)) return;
        await refreshSnapshot(true);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    function openNewCardInColumn(columnId) {
      openCardModal({ column: columnId, tags: [], attachments: [], remaining_seconds: 86400 });
    }

    async function renameColumnFromButton(button) {
      if (button.hasAttribute('disabled')) {
        setStatus('КОЛОНКУ «ГОТОВЫЕ АВТОМОБИЛИ» ПЕРЕИМЕНОВАТЬ НЕЛЬЗЯ.', true);
        return;
      }
      const columnId = button.dataset.renameColumn;
      const columnLabel = button.dataset.columnLabel || columnId || 'column';
      const label = window.prompt('Новое название столбца', columnLabel);
      if (label === null) return;
      if (!label.trim()) {
        setStatus('НУЖНО УКАЗАТЬ НАЗВАНИЕ СТОЛБЦА.', true);
        return;
      }
      try {
        await api('/api/rename_column', {
          method: 'POST',
          body: { column_id: columnId, label, actor_name: state.actor, source: 'ui' },
        });
        await refreshSnapshot(true);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function deleteColumnFromButton(button) {
      const columnId = button.dataset.deleteColumn;
      const columnLabel = button.dataset.columnLabel || columnId || 'столбец';
      const cardsCount = finiteNonNegativeNumber(button.dataset.cardCount);
      if (button.hasAttribute('disabled')) {
        if (String(columnLabel || '').trim().toLowerCase() === READY_COLUMN_LABEL.toLowerCase()) {
          setStatus('КОЛОНКУ «ГОТОВЫЕ АВТОМОБИЛИ» УДАЛЯТЬ НЕЛЬЗЯ.', true);
          return;
        }
        if (cardsCount > 0) {
          setStatus('СНАЧАЛА УБЕРИ КАРТОЧКИ ИЗ СТОЛБЦА «' + columnLabel + '».', true);
          return;
        }
        setStatus('ПОСЛЕДНИЙ СТОЛБЕЦ УДАЛЯТЬ НЕЛЬЗЯ.', true);
        return;
      }
      if (!window.confirm('Удалить пустой столбец «' + columnLabel + '»?')) return;
      try {
        await api('/api/delete_column', { method: 'POST', body: { column_id: columnId, actor_name: state.actor, source: 'ui' } });
        await refreshSnapshot(true);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function handleAuxiliaryBoardClick(target, event) {
      if (target === els.stickyDockButton || target.closest('#stickyDockButton')) {
        openStickyModal();
        return true;
      }
      const stickyCloseButton = target.closest('.sticky__close');
      if (stickyCloseButton) {
        await removeSticky(stickyCloseButton.closest('.sticky').dataset.stickyId);
        return true;
      }
      if (target.closest('.sticky')) return true;
      const attachmentLink = target.closest('a[href*="/api/attachment"]');
      if (attachmentLink) {
        event.preventDefault();
        try {
          await downloadAttachment(withAccessToken(attachmentLink.getAttribute('href')));
        } catch (error) {
          setStatus(error.message, true);
        }
        return true;
      }
      if (target.dataset.restoreCard) {
        await restoreCard(target.dataset.restoreCard);
        return true;
      }
      return false;
    }

    async function handleCardWorkspaceClick(target) {
      if (target.dataset.copyVehicleField) {
        await copyVehicleFieldValue(target.dataset.copyVehicleField);
        return true;
      }
      if (target.dataset.editRepairOrderTag) {
        editRepairOrderTag(target.dataset.editRepairOrderTag);
        return true;
      }
      if (target.dataset.removeRepairOrderTag) {
        removeRepairOrderTag(target.dataset.removeRepairOrderTag);
        return true;
      }
      if (target.dataset.repairOrderTagColorChoice) {
        state.repairOrderTagColor = normalizeTagColor(target.dataset.repairOrderTagColorChoice);
        renderRepairOrderTags();
        return true;
      }
      const boardCard = target.closest('.card');
      if (boardCard) {
        markCardSeenOptimistically(boardCard.dataset.cardId);
        await openCardById(boardCard.dataset.cardId);
        return true;
      }
      if (target.dataset.removeTag) {
        state.draftTags = state.draftTags.filter((tag) => tag.label !== target.dataset.removeTag);
        renderColorTags();
        scheduleCardSaveDirtyStateSync();
        return true;
      }
      if (target.dataset.tagColorChoice) {
        state.draftTagColor = normalizeTagColor(target.dataset.tagColorChoice);
        renderColorTags();
        scheduleCardSaveDirtyStateSync();
        return true;
      }
      if (target.dataset.suggestTag) {
        addSuggestedTag({ label: target.dataset.suggestTag, color: target.dataset.suggestColor });
        return true;
      }
      const previewFileTarget = target.closest('[data-preview-file]');
      if (previewFileTarget && state.editingId) {
        await previewActiveCardAttachment(previewFileTarget.dataset.previewFile);
        return true;
      }
      if (target.dataset.closeFilePreview) {
        clearFilePreview();
        return true;
      }
      if (target.dataset.removeFile && state.editingId) {
        await removeActiveCardAttachment(target.dataset.removeFile);
        return true;
      }
      return false;
    }

    function openBoardSettings() {
      applyBoardScale(normalizeBoardScale(state.boardScale), { syncInput: true });
      syncBoardControlSettingsForm();
      pushModal('settings', els.boardSettingsModal);
    }

    function currentBoardControlSettings() {
      const snapshotSettings = state.snapshot?.settings?.ai_board_control && typeof state.snapshot.settings.ai_board_control === 'object'
        ? state.snapshot.settings.ai_board_control
        : {};
      return {
        enabled: Boolean(snapshotSettings.enabled),
        interval_minutes: Math.max(5, Math.min(240, finiteNumber(snapshotSettings.interval_minutes, 20))),
        cooldown_minutes: Math.max(5, Math.min(1440, finiteNumber(snapshotSettings.cooldown_minutes, 60))),
      };
    }

    function boardControlEntryExposure() {
      const payload = state.agentStatusPayload && typeof state.agentStatusPayload === 'object' ? state.agentStatusPayload : {};
      const exposure = payload?.ai_remodel?.effective_mode?.entry_exposure?.future_board_control_toggle;
      return exposure && typeof exposure === 'object' ? exposure : {};
    }

    function syncBoardControlSettingsForm() {
      const settings = currentBoardControlSettings();
      const exposure = boardControlEntryExposure();
      const visible = String(exposure.exposure_state || '').trim().toLowerCase() !== 'hidden';
      if (els.boardControlSettingsRow) els.boardControlSettingsRow.classList.toggle('hidden', !visible);
      if (els.boardControlToggle) els.boardControlToggle.checked = Boolean(settings.enabled);
      if (els.boardControlIntervalInput) els.boardControlIntervalInput.value = String(settings.interval_minutes);
      if (els.boardControlCooldownInput) els.boardControlCooldownInput.value = String(settings.cooldown_minutes);
    }

    function readBoardControlSettingsForm() {
      if (!els.boardControlToggle && !els.boardControlIntervalInput && !els.boardControlCooldownInput) return null;
      return {
        enabled: Boolean(els.boardControlToggle?.checked),
        interval_minutes: Math.max(5, Math.min(240, finiteNumber(els.boardControlIntervalInput?.value, 20))),
        cooldown_minutes: Math.max(5, Math.min(1440, finiteNumber(els.boardControlCooldownInput?.value, 60))),
      };
    }

    function handleBoardScaleInput() {
      zoomBoardTo(Number(els.boardScaleInput.value) / 100);
    }

    async function resetBoardScaleToDefault() {
      els.boardScaleInput.value = '100';
      zoomBoardTo(1, { syncInput: true });
      await saveBoardScale();
    }

    async function createColumnFromBoard() {
      const label = window.prompt('Название столбца');
      if (!label) return;
      try {
        await api('/api/create_column', { method: 'POST', body: { label, actor_name: state.actor, source: 'ui' } });
        await refreshSnapshot(true);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    function openRepairOrdersModal() {
      const canReuseOpenList = repairOrdersHasReusableOpenList();
      state.repairOrdersFilter = 'open';
      state.repairOrdersQuery = '';
      state.repairOrdersRemoteQuery = '';
      state.repairOrdersSearchField = 'summary';
      state.repairOrdersSortBy = 'number';
      state.repairOrdersSortDir = 'desc';
      if (state.repairOrdersLoadTimer) {
        window.clearTimeout(state.repairOrdersLoadTimer);
        state.repairOrdersLoadTimer = null;
      }
      setRepairOrdersSearchLoading(false);
      updateRepairOrdersTabs();
      syncRepairOrdersControls();
      if (canReuseOpenList) {
        renderRepairOrdersView();
        maybeOpenModal(els.repairOrdersModal, true);
        return;
      }
      state.repairOrdersItems = [];
      state.repairOrdersMetaState = null;
      loadRepairOrders(true);
    }

    function inventoryItemId(item) {
      return String(item?.id || '').trim();
    }

    function inventoryItemById(itemId) {
      const normalizedId = String(itemId || '').trim();
      if (!normalizedId) return null;
      return (Array.isArray(state.inventoryItems) ? state.inventoryItems : [])
        .find((item) => inventoryItemId(item) === normalizedId) || null;
    }

    function activeInventoryItem() {
      return inventoryItemById(state.inventoryActiveId);
    }

    function inventoryDecimalText(value, fallback = '0') {
      const normalized = String(value ?? '').trim().replace(',', '.');
      if (!normalized) return fallback;
      const parsed = Number(normalized);
      if (!Number.isFinite(parsed)) return fallback;
      if (!String(normalized).includes('.')) return String(normalized);
      return String(normalized).replace(/0+$/, '').replace(/\.$/, '') || '0';
    }

    function inventoryDisplayQuantity(item) {
      return inventoryDecimalText(item?.quantity, '0') + ' ' + (item?.unit || 'шт');
    }

    function inventoryItemMeta(item) {
      const parts = [];
      const catalog = String(item?.catalog_number || '').trim();
      if (catalog) parts.push(catalog);
      parts.push(inventoryDisplayQuantity(item));
      parts.push('закуп ' + repairOrderFormatRubles(item?.cost_price ?? 0));
      parts.push('прод ' + repairOrderFormatRubles(item?.sale_price ?? 0));
      return parts.join(' · ');
    }

    function inventorySearchMatches(item, query) {
      const needle = String(query || '').trim().toLowerCase();
      if (!needle) return true;
      return [
        item?.name,
        item?.catalog_number,
        item?.id,
      ].some((value) => String(value || '').toLowerCase().includes(needle));
    }

    function inventoryItemQuantityNumber(item) {
      const parsed = repairOrderParseNumber(item?.quantity);
      return parsed === null ? 0 : parsed;
    }

    function inventoryFilteredItems() {
      const query = String(state.inventoryQuery || '').trim();
      const stockFilter = String(state.inventoryStockFilter || 'all');
      return (Array.isArray(state.inventoryItems) ? state.inventoryItems : [])
        .filter((item) => inventorySearchMatches(item, query))
        .filter((item) => {
          const quantity = inventoryItemQuantityNumber(item);
          if (stockFilter === 'in_stock') return quantity > 0;
          if (stockFilter === 'zero') return quantity <= 0;
          return true;
        });
    }

    function inventoryUpdatedText(item) {
      const value = item?.updated_at || item?.created_at || '';
      return value ? formatDate(value) : '-';
    }

    function inventoryTableRowHtml(item) {
      const itemId = inventoryItemId(item);
      const activeClass = itemId === String(state.inventoryActiveId || '').trim() ? ' is-active' : '';
      const zeroClass = inventoryItemQuantityNumber(item) <= 0 ? ' is-zero' : '';
      return '<tr class="inventory-table__row' + activeClass + zeroClass + '" data-inventory-item-id="' + escapeHtml(itemId) + '">'
        + '<td><button class="inventory-table__select" type="button" data-inventory-item-id="' + escapeHtml(itemId) + '">' + escapeHtml(item?.name || 'Позиция без названия') + '</button></td>'
        + '<td class="inventory-table__mono">' + escapeHtml(item?.catalog_number || '-') + '</td>'
        + '<td class="inventory-table__number">' + escapeHtml(inventoryDisplayQuantity(item)) + '</td>'
        + '<td class="inventory-table__number">' + escapeHtml(repairOrderFormatRubles(item?.cost_price ?? 0)) + '</td>'
        + '<td class="inventory-table__number">' + escapeHtml(repairOrderFormatRubles(item?.sale_price ?? 0)) + '</td>'
        + '<td class="inventory-table__mono">' + escapeHtml(inventoryUpdatedText(item)) + '</td>'
      + '</tr>';
    }

    function inventoryMovementKindText(kind) {
      const normalized = String(kind || '').trim();
      if (normalized === 'incoming') return 'ПРИХОД';
      if (normalized === 'write_off') return 'СПИСАНИЕ';
      if (normalized === 'return') return 'ВОЗВРАТ';
      if (normalized === 'adjustment') return 'КОРР.';
      return normalized || '-';
    }

    function inventoryMovementItemName(movement) {
      const item = inventoryItemById(movement?.item_id);
      return item?.name || movement?.item_name || movement?.item_id || '-';
    }

    function inventoryMovementCardText(movement) {
      const orderNumber = String(movement?.repair_order_number || '').trim();
      if (orderNumber) return 'ЗН ' + orderNumber;
      const cardId = String(movement?.card_id || '').trim();
      return cardId ? ('КАРТА ' + cardId.slice(0, 8)) : '-';
    }

    function inventoryMovementPriceText(movement) {
      const kind = String(movement?.kind || '');
      const value = kind === 'incoming' ? movement?.cost_price : movement?.sale_price;
      return repairOrderFormatRubles(value ?? 0);
    }

    function inventoryMovementQuantityText(movement) {
      const quantity = inventoryDecimalText(movement?.quantity, '0') + ' ' + (movement?.unit || 'шт');
      const delta = inventoryDecimalText(movement?.quantity_delta, '');
      return delta && delta !== '0' ? quantity + ' (' + delta + ')' : quantity;
    }

    function inventoryMovementRowHtml(movement) {
      return '<tr>'
        + '<td class="inventory-table__mono">' + escapeHtml(formatDate(movement?.created_at || '')) + '</td>'
        + '<td>' + escapeHtml(inventoryMovementKindText(movement?.kind)) + '</td>'
        + '<td>' + escapeHtml(inventoryMovementItemName(movement)) + '</td>'
        + '<td class="inventory-table__number">' + escapeHtml(inventoryMovementQuantityText(movement)) + '</td>'
        + '<td class="inventory-table__number">' + escapeHtml(inventoryMovementPriceText(movement)) + '</td>'
        + '<td class="inventory-table__mono">' + escapeHtml(inventoryMovementCardText(movement)) + '</td>'
        + '<td class="inventory-table__mono">' + escapeHtml(movement?.actor_name || '-') + '</td>'
      + '</tr>';
    }

    function renderInventoryWorkspace() {
      const isMovements = state.inventoryView === 'movements';
      if (els.inventoryPositionsTab) {
        els.inventoryPositionsTab.classList.toggle('is-active', !isMovements);
        els.inventoryPositionsTab.setAttribute('aria-selected', isMovements ? 'false' : 'true');
      }
      if (els.inventoryMovementsTab) {
        els.inventoryMovementsTab.classList.toggle('is-active', isMovements);
        els.inventoryMovementsTab.setAttribute('aria-selected', isMovements ? 'true' : 'false');
      }
      if (els.inventoryPositionsPanel) els.inventoryPositionsPanel.hidden = isMovements;
      if (els.inventoryMovementsPanel) els.inventoryMovementsPanel.hidden = !isMovements;
      if (els.inventoryStockFilter && els.inventoryStockFilter.value !== state.inventoryStockFilter) {
        els.inventoryStockFilter.value = state.inventoryStockFilter;
      }
    }

    function renderInventoryQuickState() {
      if (!els.inventoryQuickState) return;
      const item = activeInventoryItem();
      const refs = inventoryFormRefs({ mobile: false });
      let stateName = 'dirty';
      let text = item ? 'ИЗМЕНЕНО' : 'НОВАЯ ПОЗИЦИЯ';
      if (item?.id) {
        const dirty = [
          [refs.name?.value, item.name || ''],
          [refs.catalog?.value, item.catalog_number || ''],
          [refs.unit?.value, item.unit || 'шт'],
          [refs.costPrice?.value, inventoryDecimalText(item.cost_price, '0')],
          [refs.salePrice?.value, inventoryDecimalText(item.sale_price, '0')],
        ].some(([left, right]) => String(left ?? '').trim() !== String(right ?? '').trim());
        if (!dirty && inventoryItemQuantityNumber(item) <= 0) {
          stateName = 'empty';
          text = 'НЕТ ОСТАТКА';
        } else if (!dirty) {
          stateName = 'saved';
          text = 'СОХРАНЕНО · ' + inventoryDisplayQuantity(item);
        }
      }
      els.inventoryQuickState.dataset.state = stateName;
      els.inventoryQuickState.textContent = text;
    }

    function renderInventoryMovements() {
      if (!els.inventoryMovementsBody) return;
      const movements = Array.isArray(state.inventoryMovements) ? state.inventoryMovements.slice().reverse() : [];
      if (state.inventoryMovementsLoading && !movements.length) {
        els.inventoryMovementsBody.innerHTML = '<tr><td colspan="7" class="cashboxes-empty">ЗАГРУЖАЮ ДВИЖЕНИЯ...</td></tr>';
        return;
      }
      els.inventoryMovementsBody.innerHTML = movements.length
        ? movements.map((movement) => inventoryMovementRowHtml(movement)).join('')
        : '<tr><td colspan="7" class="cashboxes-empty">ДВИЖЕНИЙ ПОКА НЕТ.</td></tr>';
    }

    function renderMobileInventoryMovements() {
      if (!els.mobileInventoryRecentMovements) return;
      const item = activeInventoryItem();
      if (!item?.id) {
        els.mobileInventoryRecentMovements.innerHTML = '<div class="mobile-kicker">ДВИЖЕНИЯ</div><div class="mobile-empty">ВЫБЕРИТЕ ПОЗИЦИЮ.</div>';
        return;
      }
      const itemId = inventoryItemId(item);
      const movements = (Array.isArray(state.inventoryMovements) ? state.inventoryMovements : [])
        .filter((movement) => String(movement?.item_id || '').trim() === itemId)
        .slice()
        .reverse()
        .slice(0, 5);
      if (!state.inventoryMovementsLoaded && !movements.length) {
        els.mobileInventoryRecentMovements.innerHTML = '<div class="mobile-kicker">ДВИЖЕНИЯ</div><div class="mobile-empty">ДВИЖЕНИЯ ЗАГРУЖАЮТСЯ...</div>';
        return;
      }
      els.mobileInventoryRecentMovements.innerHTML = '<div class="mobile-kicker">ПОСЛЕДНИЕ ДВИЖЕНИЯ</div>'
        + (movements.length
          ? movements.map((movement) => (
            '<div class="mobile-inventory-movement">'
              + '<span>' + escapeHtml(formatDate(movement?.created_at || '') + ' · ' + inventoryMovementKindText(movement?.kind)) + '</span>'
              + '<strong>' + escapeHtml(inventoryMovementQuantityText(movement)) + '</strong>'
            + '</div>'
          )).join('')
          : '<div class="mobile-empty">ДВИЖЕНИЙ ПО ЭТОЙ ПОЗИЦИИ НЕТ.</div>');
    }

    function inventoryStatus(text, isError = false) {
      const statusText = String(text || '').trim();
      if (els.inventoryStatusLine) {
        els.inventoryStatusLine.textContent = statusText;
        els.inventoryStatusLine.dataset.tone = isError ? 'error' : 'normal';
      }
      if (els.repairOrderInventoryStatus) {
        els.repairOrderInventoryStatus.textContent = statusText;
        els.repairOrderInventoryStatus.dataset.tone = isError ? 'error' : 'normal';
      }
      if (els.mobileInventoryStatusLine) {
        els.mobileInventoryStatusLine.textContent = statusText;
        els.mobileInventoryStatusLine.dataset.tone = isError ? 'error' : 'normal';
      }
    }

    function inventoryRowHtml(item, { mobile = false, panel = false } = {}) {
      const itemId = inventoryItemId(item);
      const activeId = panel ? state.repairOrderInventorySelectedId : state.inventoryActiveId;
      const activeClass = itemId === String(activeId || '').trim() ? ' is-active' : '';
      const className = panel ? 'repair-order-inventory-result' : (mobile ? 'inventory-row mobile-inventory-row' : 'inventory-row');
      const attr = panel ? 'data-repair-order-inventory-item-id' : (mobile ? 'data-mobile-inventory-item-id' : 'data-inventory-item-id');
      return '<button class="' + className + activeClass + '" type="button" ' + attr + '="' + escapeHtml(itemId) + '">'
        + '<div class="inventory-row__top">'
          + '<span class="inventory-row__name">' + escapeHtml(item?.name || 'Позиция без названия') + '</span>'
          + '<strong class="inventory-row__qty">' + escapeHtml(inventoryDisplayQuantity(item)) + '</strong>'
        + '</div>'
        + '<div class="inventory-row__meta">' + escapeHtml(inventoryItemMeta(item)) + '</div>'
      + '</button>';
    }

    function renderInventoryItems() {
      const items = inventoryFilteredItems();
      if (els.inventorySearchInput && els.inventorySearchInput.value !== state.inventoryQuery) {
        els.inventorySearchInput.value = state.inventoryQuery;
      }
      renderInventoryWorkspace();
      if (els.inventoryTableBody) {
        els.inventoryTableBody.innerHTML = !state.inventoryLoaded && !items.length
          ? '<tr><td colspan="6" class="cashboxes-empty">ЗАГРУЖАЮ СКЛАД...</td></tr>'
          : (items.length
            ? items.map((item) => inventoryTableRowHtml(item)).join('')
            : '<tr><td colspan="6" class="cashboxes-empty">ПОЗИЦИЙ ПОКА НЕТ.</td></tr>');
      } else if (els.inventoryItemsList) {
        els.inventoryItemsList.innerHTML = !state.inventoryLoaded && !items.length
          ? '<div class="cashboxes-empty">ЗАГРУЖАЮ СКЛАД...</div>'
          : (items.length
            ? items.map((item) => inventoryRowHtml(item)).join('')
            : '<div class="cashboxes-empty">ПОЗИЦИЙ ПОКА НЕТ.</div>');
      }
      renderInventoryMovements();
      renderMobileInventory();
      renderRepairOrderInventoryPanel();
    }

    function inventoryFormRefs({ mobile = state.mobileLite && state.mobileView === 'inventory' } = {}) {
      return mobile ? {
        name: els.mobileInventoryNameInput,
        catalog: els.mobileInventoryCatalogInput,
        unit: els.mobileInventoryUnitSelect,
        quantity: els.mobileInventoryQuantityInput,
        replenishQuantity: els.mobileInventoryReplenishQuantityInput,
        costPrice: els.mobileInventoryCostPriceInput,
        salePrice: els.mobileInventorySalePriceInput,
        saveButton: els.mobileInventorySaveButton,
        replenishButton: els.mobileInventoryReplenishButton,
      } : {
        name: els.inventoryNameInput,
        catalog: els.inventoryCatalogInput,
        unit: els.inventoryUnitSelect,
        quantity: els.inventoryQuantityInput,
        replenishQuantity: els.inventoryReplenishQuantityInput,
        costPrice: els.inventoryCostPriceInput,
        salePrice: els.inventorySalePriceInput,
        saveButton: els.inventorySaveButton,
        replenishButton: els.inventoryReplenishButton,
      };
    }

    function syncInventoryForm(refs, item) {
      if (!refs?.name) return;
      const hasItem = Boolean(item?.id);
      refs.name.value = hasItem ? String(item.name || '') : '';
      if (refs.catalog) refs.catalog.value = hasItem ? String(item.catalog_number || '') : '';
      if (refs.unit) refs.unit.value = hasItem ? String(item.unit || 'шт') : 'шт';
      if (refs.quantity) {
        refs.quantity.value = hasItem ? inventoryDecimalText(item.quantity, '0') : '0';
        refs.quantity.readOnly = hasItem;
        refs.quantity.title = hasItem ? 'Остаток меняется через пополнение или списание.' : '';
      }
      if (refs.replenishQuantity) refs.replenishQuantity.value = '';
      if (refs.costPrice) refs.costPrice.value = hasItem ? inventoryDecimalText(item.cost_price, '0') : '0';
      if (refs.salePrice) refs.salePrice.value = hasItem ? inventoryDecimalText(item.sale_price, '0') : '0';
      if (refs.saveButton) refs.saveButton.disabled = state.inventorySaving;
      if (refs.replenishButton) refs.replenishButton.disabled = state.inventorySaving || !hasItem;
    }

    function renderInventoryForm() {
      const item = activeInventoryItem();
      if (els.inventoryDetailTitle) {
        els.inventoryDetailTitle.textContent = item ? 'ПОЗИЦИЯ СКЛАДА' : 'НОВАЯ ПОЗИЦИЯ';
      }
      syncInventoryForm(inventoryFormRefs({ mobile: false }), item);
      syncInventoryForm(inventoryFormRefs({ mobile: true }), item);
      renderInventoryQuickState();
    }

    function renderInventory() {
      renderInventoryItems();
      renderInventoryForm();
      renderInventoryMovements();
      renderMobileInventoryMovements();
    }

    function upsertInventoryItem(item) {
      if (!item?.id) return;
      const items = Array.isArray(state.inventoryItems) ? state.inventoryItems.slice() : [];
      const index = items.findIndex((entry) => inventoryItemId(entry) === inventoryItemId(item));
      if (index >= 0) items[index] = item;
      else items.unshift(item);
      state.inventoryItems = items;
      state.inventoryLoaded = true;
    }

    async function loadInventoryItems(openModal = false, { query = null } = {}) {
      const requestedQuery = query === null ? String(state.inventoryQuery || '').trim() : String(query || '').trim();
      try {
        if (!state.inventoryLoaded) renderInventoryItems();
        const data = requestedQuery
          ? await api('/api/search_inventory_items', {
            method: 'POST',
            body: { query: requestedQuery, limit: 200 },
          })
          : await api('/api/list_inventory_items?limit=200');
        state.inventoryItems = Array.isArray(data?.items) ? data.items : [];
        state.inventoryLoaded = true;
        if (state.inventoryActiveId && !inventoryItemById(state.inventoryActiveId)) {
          state.inventoryActiveId = '';
        }
        if (!state.inventoryActiveId && state.inventoryItems.length) {
          state.inventoryActiveId = inventoryItemId(state.inventoryItems[0]);
        }
        if (state.repairOrderInventorySelectedId && !inventoryItemById(state.repairOrderInventorySelectedId)) {
          state.repairOrderInventorySelectedId = '';
        }
        if (!state.repairOrderInventorySelectedId && state.inventoryItems.length) {
          state.repairOrderInventorySelectedId = inventoryItemId(state.inventoryItems[0]);
        }
        renderInventory();
        maybeOpenModal(els.inventoryModal, openModal);
        return data;
      } catch (error) {
        state.inventoryLoaded = false;
        renderInventory();
        maybeOpenModal(els.inventoryModal, openModal);
        inventoryStatus(error.message, true);
        setStatus(error.message, true);
        return null;
      }
    }

    async function loadInventoryMovements({ force = false } = {}) {
      if (state.inventoryMovementsLoading) return null;
      if (state.inventoryMovementsLoaded && !force) {
        renderInventoryMovements();
        renderMobileInventoryMovements();
        return { movements: state.inventoryMovements };
      }
      state.inventoryMovementsLoading = true;
      renderInventoryMovements();
      renderMobileInventoryMovements();
      try {
        const data = await api('/api/list_inventory_movements?limit=200');
        state.inventoryMovements = Array.isArray(data?.movements) ? data.movements : [];
        state.inventoryMovementsLoaded = true;
        renderInventoryMovements();
        renderMobileInventoryMovements();
        return data;
      } catch (error) {
        state.inventoryMovementsLoaded = false;
        inventoryStatus(error.message, true);
        setStatus(error.message, true);
        renderInventoryMovements();
        renderMobileInventoryMovements();
        return null;
      } finally {
        state.inventoryMovementsLoading = false;
        renderInventoryMovements();
        renderMobileInventoryMovements();
      }
    }

    function invalidateInventoryMovements() {
      state.inventoryMovementsLoaded = false;
      if (state.inventoryView === 'movements' || (state.mobileLite && state.mobileView === 'inventory')) {
        loadInventoryMovements({ force: true });
      } else {
        renderInventoryMovements();
        renderMobileInventoryMovements();
      }
    }

    function openInventoryModal() {
      maybeOpenModal(els.inventoryModal, true);
      renderInventory();
      loadInventoryItems(false);
      if (state.inventoryView === 'movements') loadInventoryMovements();
    }

    function selectInventoryItem(itemId) {
      const normalizedId = String(itemId || '').trim();
      state.inventoryActiveId = normalizedId;
      if (normalizedId) state.repairOrderInventorySelectedId = normalizedId;
      renderInventory();
      if (state.mobileLite && state.mobileView === 'inventory') loadInventoryMovements();
    }

    function resetInventoryForm() {
      state.inventoryActiveId = '';
      renderInventory();
      inventoryFormRefs().name?.focus({ preventScroll: true });
    }

    function setInventoryView(view) {
      state.inventoryView = view === 'movements' ? 'movements' : 'positions';
      renderInventory();
      if (state.inventoryView === 'movements') loadInventoryMovements();
    }

    function handleInventoryStockFilterChange() {
      state.inventoryStockFilter = String(els.inventoryStockFilter?.value || 'all');
      renderInventoryItems();
    }

    function handleInventoryFormInput() {
      renderInventoryQuickState();
    }

    function inventoryPayloadFromForm() {
      const refs = inventoryFormRefs();
      const itemId = String(state.inventoryActiveId || '').trim();
      const payload = {
        name: String(refs.name?.value || '').trim(),
        catalog_number: String(refs.catalog?.value || '').trim(),
        unit: String(refs.unit?.value || 'шт').trim() || 'шт',
        cost_price: String(refs.costPrice?.value || '0').trim(),
        sale_price: String(refs.salePrice?.value || '0').trim(),
        actor_name: state.actor,
        source: 'ui',
      };
      if (itemId) payload.item_id = itemId;
      else payload.quantity = String(refs.quantity?.value || '0').trim();
      return payload;
    }

    async function saveInventoryItem() {
      if (state.inventorySaving) return;
      const payload = inventoryPayloadFromForm();
      if (!payload.name) {
        inventoryStatus('УКАЖИТЕ НАЗВАНИЕ ПОЗИЦИИ.', true);
        return;
      }
      state.inventorySaving = true;
      renderInventoryForm();
      try {
        const data = await api('/api/save_inventory_item', { method: 'POST', body: payload });
        if (data?.item) {
          upsertInventoryItem(data.item);
          state.inventoryActiveId = inventoryItemId(data.item);
          state.repairOrderInventorySelectedId = inventoryItemId(data.item);
        }
        if (data?.movement) invalidateInventoryMovements();
        await loadInventoryItems(false, { query: state.inventoryQuery });
        inventoryStatus(data?.meta?.created ? 'ПОЗИЦИЯ ДОБАВЛЕНА.' : 'ПОЗИЦИЯ СОХРАНЕНА.', false);
      } catch (error) {
        inventoryStatus(error.message, true);
        setStatus(error.message, true);
      } finally {
        state.inventorySaving = false;
        renderInventory();
      }
    }

    async function replenishInventoryItem() {
      if (state.inventorySaving) return;
      const item = activeInventoryItem();
      if (!item?.id) return inventoryStatus('ВЫБЕРИТЕ ПОЗИЦИЮ ДЛЯ ПОПОЛНЕНИЯ.', true);
      const refs = inventoryFormRefs();
      const quantity = String(refs.replenishQuantity?.value || '').trim();
      const parsed = repairOrderParseNumber(quantity);
      if (parsed === null || parsed <= 0) {
        refs.replenishQuantity?.focus({ preventScroll: true });
        return inventoryStatus('УКАЖИТЕ КОЛИЧЕСТВО БОЛЬШЕ НУЛЯ.', true);
      }
      state.inventorySaving = true;
      renderInventoryForm();
      try {
        const data = await api('/api/replenish_inventory_item', {
          method: 'POST',
          body: {
            item_id: item.id,
            quantity,
            cost_price: String(refs.costPrice?.value || '').trim(),
            sale_price: String(refs.salePrice?.value || '').trim(),
            actor_name: state.actor,
            source: 'ui',
          },
        });
        if (data?.item) {
          upsertInventoryItem(data.item);
          state.inventoryActiveId = inventoryItemId(data.item);
          state.repairOrderInventorySelectedId = inventoryItemId(data.item);
        }
        invalidateInventoryMovements();
        await loadInventoryItems(false, { query: state.inventoryQuery });
        inventoryStatus('ОСТАТОК ПОПОЛНЕН.', false);
      } catch (error) {
        inventoryStatus(error.message, true);
        setStatus(error.message, true);
      } finally {
        state.inventorySaving = false;
        renderInventory();
      }
    }

    function handleInventorySearchInput() {
      state.inventoryQuery = String(els.inventorySearchInput?.value || '').trim();
      if (state.inventorySearchTimer) window.clearTimeout(state.inventorySearchTimer);
      state.inventorySearchTimer = window.setTimeout(() => {
        state.inventorySearchTimer = null;
        loadInventoryItems(false, { query: state.inventoryQuery });
      }, 250);
    }

    function handleInventoryItemsClick(event) {
      const button = event.target instanceof HTMLElement ? event.target.closest('[data-inventory-item-id]') : null;
      if (!button || !els.inventoryItemsList?.contains(button)) return;
      selectInventoryItem(button.getAttribute('data-inventory-item-id'));
    }

    function renderMobileInventory() {
      if (!els.mobileInventoryItemsList) return;
      const items = (Array.isArray(state.inventoryItems) ? state.inventoryItems : [])
        .filter((item) => inventorySearchMatches(item, state.inventoryQuery));
      if (els.mobileInventorySearchInput && els.mobileInventorySearchInput.value !== state.inventoryQuery) {
        els.mobileInventorySearchInput.value = state.inventoryQuery;
      }
      els.mobileInventoryItemsList.innerHTML = !state.inventoryLoaded && !items.length
        ? '<div class="mobile-empty">СКЛАД ЗАГРУЖАЕТСЯ...</div>'
        : (items.length
          ? items.map((item) => inventoryRowHtml(item, { mobile: true })).join('')
          : '<div class="mobile-empty">ПОЗИЦИЙ ПОКА НЕТ.</div>');
      renderInventoryForm();
      renderMobileInventoryMovements();
    }

    function handleMobileInventorySearchInput() {
      state.inventoryQuery = String(els.mobileInventorySearchInput?.value || '').trim();
      if (state.mobileInventorySearchTimer) window.clearTimeout(state.mobileInventorySearchTimer);
      state.mobileInventorySearchTimer = window.setTimeout(() => {
        state.mobileInventorySearchTimer = null;
        loadInventoryItems(false, { query: state.inventoryQuery });
      }, 250);
    }

    function handleMobileInventoryItemsClick(event) {
      const button = event.target instanceof HTMLElement ? event.target.closest('[data-mobile-inventory-item-id]') : null;
      if (!button || !els.mobileInventoryItemsList?.contains(button)) return;
      selectInventoryItem(button.getAttribute('data-mobile-inventory-item-id'));
    }

    function repairOrderMaterialRowElements() {
      return Array.from(els.repairOrderMaterialsBody?.querySelectorAll('tr[data-repair-order-row="materials"]') || []);
    }

    function repairOrderInventoryRememberedRowIndex() {
      const parsed = finiteNumber(state.repairOrderInventoryRowIndex, -1);
      const rows = repairOrderMaterialRowElements();
      return Number.isInteger(parsed) && parsed >= 0 && parsed < rows.length ? parsed : -1;
    }

    function rememberRepairOrderInventoryRow(event) {
      const row = event?.target instanceof HTMLElement ? event.target.closest('tr[data-repair-order-row="materials"]') : null;
      if (!row || !els.repairOrderMaterialsBody?.contains(row)) return;
      const rows = repairOrderMaterialRowElements();
      const index = rows.indexOf(row);
      if (index < 0) return;
      state.repairOrderInventoryRowIndex = String(index);
      const rowData = readRepairOrderRowElement(row);
      if (rowData.inventory_item_id) state.repairOrderInventorySelectedId = rowData.inventory_item_id;
      renderRepairOrderInventoryPanel();
    }

    function repairOrderInventorySelectedRow() {
      const rows = repairOrderMaterialRowElements();
      if (!rows.length) return null;
      const rememberedIndex = repairOrderInventoryRememberedRowIndex();
      if (rememberedIndex >= 0) return rows[rememberedIndex];
      const activeRow = document.activeElement instanceof HTMLElement
        ? document.activeElement.closest('tr[data-repair-order-row="materials"]')
        : null;
      if (activeRow && els.repairOrderMaterialsBody?.contains(activeRow)) return activeRow;
      const selectedItemId = String(state.repairOrderInventorySelectedId || '').trim();
      if (selectedItemId) {
        const linked = rows.find((row) => {
          const rowData = readRepairOrderRowElement(row);
          return rowData.inventory_item_id === selectedItemId && rowData.inventory_movement_id;
        });
        if (linked) return linked;
      }
      if (rows.length === 1 && !repairOrderRowHasAnyData(readRepairOrderRowElement(rows[0]))) return rows[0];
      return null;
    }

    function repairOrderInventorySelectedMovementId() {
      const selectedRow = repairOrderInventorySelectedRow();
      const selectedData = selectedRow ? readRepairOrderRowElement(selectedRow) : null;
      if (selectedData?.inventory_movement_id) return selectedData.inventory_movement_id;
      const selectedItemId = String(state.repairOrderInventorySelectedId || '').trim();
      if (!selectedItemId) return '';
      const linked = repairOrderMaterialRowElements().find((row) => {
        const rowData = readRepairOrderRowElement(row);
        return rowData.inventory_item_id === selectedItemId && rowData.inventory_movement_id;
      });
      return linked ? readRepairOrderRowElement(linked).inventory_movement_id : '';
    }

    function repairOrderInventoryTargetRowIndex() {
      const rows = repairOrderMaterialRowElements();
      const rememberedIndex = repairOrderInventoryRememberedRowIndex();
      if (rememberedIndex >= 0) return rememberedIndex;
      const selectedRow = repairOrderInventorySelectedRow();
      if (selectedRow) {
        const index = rows.indexOf(selectedRow);
        if (index >= 0) return index;
      }
      if (rows.length === 1 && !repairOrderRowHasAnyData(readRepairOrderRowElement(rows[0]))) return 0;
      return rows.length;
    }

    function selectedRepairOrderInventoryItem() {
      return inventoryItemById(state.repairOrderInventorySelectedId) || activeInventoryItem();
    }

    function repairOrderInventoryQuantity() {
      const raw = String(els.repairOrderInventoryQuantityInput?.value || '').trim();
      const parsed = repairOrderParseNumber(raw);
      return parsed !== null && parsed > 0 ? { raw, parsed } : null;
    }

    function repairOrderInventoryResults() {
      const query = String(state.repairOrderInventoryQuery || '').trim();
      return (Array.isArray(state.inventoryItems) ? state.inventoryItems : [])
        .filter((item) => inventorySearchMatches(item, query))
        .slice(0, 80);
    }

    function repairOrderInventoryRowFromItem(item, quantity) {
      const salePrice = repairOrderParseNumber(item?.sale_price ?? 0) ?? 0;
      return normalizeRepairOrderRow({
        name: item?.name || '',
        catalog_number: item?.catalog_number || '',
        quantity: quantity.raw,
        cost_price: item?.cost_price || '0',
        price: item?.sale_price || '0',
        total: repairOrderNumberToRaw(repairOrderRoundMoney(quantity.parsed * salePrice)),
        inventory_item_id: '',
        inventory_movement_id: '',
        inventory_unit: '',
      });
    }

    function setRepairOrderMaterialRow(rowData, targetIndex) {
      const rows = readRepairOrderRows('materials');
      let index = finiteNumber(targetIndex, rows.length);
      if (!Number.isInteger(index) || index < 0) index = rows.length;
      if (index > rows.length) index = rows.length;
      if (index === rows.length) rows.push(rowData);
      else rows[index] = normalizeRepairOrderRow({ ...rows[index], ...rowData });
      renderRepairOrderRows('materials', rows);
      state.repairOrderInventoryRowIndex = String(Math.max(0, Math.min(index, rows.length - 1)));
    }

    function fillRepairOrderInventoryRow() {
      const item = selectedRepairOrderInventoryItem();
      if (!item?.id) return inventoryStatus('ВЫБЕРИТЕ ПОЗИЦИЮ СКЛАДА.', true);
      const quantity = repairOrderInventoryQuantity();
      if (!quantity) {
        els.repairOrderInventoryQuantityInput?.focus({ preventScroll: true });
        return inventoryStatus('УКАЖИТЕ КОЛИЧЕСТВО БОЛЬШЕ НУЛЯ.', true);
      }
      setRepairOrderMaterialRow(repairOrderInventoryRowFromItem(item, quantity), repairOrderInventoryTargetRowIndex());
      syncRepairOrderTotals();
      renderRepairOrderInventoryPanel();
      inventoryStatus('СТРОКА МАТЕРИАЛА ЗАПОЛНЕНА БЕЗ СПИСАНИЯ.', false);
    }

    async function writeOffInventoryItem() {
      const item = selectedRepairOrderInventoryItem();
      if (!item?.id) return inventoryStatus('ВЫБЕРИТЕ ПОЗИЦИЮ СКЛАДА.', true);
      const quantity = repairOrderInventoryQuantity();
      if (!quantity) {
        els.repairOrderInventoryQuantityInput?.focus({ preventScroll: true });
        return inventoryStatus('УКАЖИТЕ КОЛИЧЕСТВО БОЛЬШЕ НУЛЯ.', true);
      }
      const available = inventoryItemQuantityNumber(item);
      if (quantity.parsed > available) {
        els.repairOrderInventoryQuantityInput?.focus({ preventScroll: true });
        renderRepairOrderInventoryPanel();
        return inventoryStatus('НЕЛЬЗЯ СПИСАТЬ БОЛЬШЕ ОСТАТКА: ' + inventoryDisplayQuantity(item) + '.', true);
      }
      const cardId = await requireRepairOrderCardId();
      if (!cardId) return;
      const rowIndex = repairOrderInventoryTargetRowIndex();
      try {
        if (els.repairOrderInventoryIssueButton) els.repairOrderInventoryIssueButton.disabled = true;
        const data = await api('/api/write_off_inventory_item', {
          method: 'POST',
          body: {
            item_id: item.id,
            card_id: cardId,
            quantity: quantity.raw,
            row_index: rowIndex,
            actor_name: state.actor,
            source: 'ui',
          },
        });
        if (data?.item) {
          upsertInventoryItem(data.item);
          state.inventoryActiveId = inventoryItemId(data.item);
          state.repairOrderInventorySelectedId = inventoryItemId(data.item);
        }
        state.repairOrderInventoryRowIndex = String(data?.meta?.row_index ?? rowIndex);
        if (data?.card || data?.repair_order) {
          const updatedCard = repairOrderResponseCard(data, data?.repair_order || readRepairOrderFromForm());
          applyRepairOrderCardUpdate(updatedCard, data?.repair_order || {});
          await refreshRepairOrdersListAfterMutation();
        }
        await loadInventoryItems(false, { query: state.repairOrderInventoryQuery || state.inventoryQuery });
        invalidateInventoryMovements();
        inventoryStatus('МАТЕРИАЛ СПИСАН СО СКЛАДА.', false);
        setStatus('МАТЕРИАЛ СПИСАН СО СКЛАДА.', false);
      } catch (error) {
        inventoryStatus(error.message, true);
        setStatus(error.message, true);
      } finally {
        renderRepairOrderInventoryPanel();
      }
    }

    async function returnInventoryMovement() {
      const movementId = repairOrderInventorySelectedMovementId();
      if (!movementId) return inventoryStatus('В СТРОКЕ НЕТ СКЛАДСКОГО СПИСАНИЯ.', true);
      const cardId = await requireRepairOrderCardId();
      if (!cardId) return;
      try {
        if (els.repairOrderInventoryReturnButton) els.repairOrderInventoryReturnButton.disabled = true;
        const data = await api('/api/return_inventory_movement', {
          method: 'POST',
          body: {
            movement_id: movementId,
            card_id: cardId,
            actor_name: state.actor,
            source: 'ui',
          },
        });
        if (data?.item) {
          upsertInventoryItem(data.item);
          state.inventoryActiveId = inventoryItemId(data.item);
          state.repairOrderInventorySelectedId = inventoryItemId(data.item);
        }
        if (data?.card || data?.repair_order) {
          const updatedCard = repairOrderResponseCard(data, data?.repair_order || readRepairOrderFromForm());
          applyRepairOrderCardUpdate(updatedCard, data?.repair_order || {});
          await refreshRepairOrdersListAfterMutation();
        }
        await loadInventoryItems(false, { query: state.repairOrderInventoryQuery || state.inventoryQuery });
        invalidateInventoryMovements();
        inventoryStatus('СПИСАНИЕ ВОЗВРАЩЕНО НА СКЛАД.', false);
        setStatus('СПИСАНИЕ ВОЗВРАЩЕНО НА СКЛАД.', false);
      } catch (error) {
        inventoryStatus(error.message, true);
        setStatus(error.message, true);
      } finally {
        renderRepairOrderInventoryPanel();
      }
    }

    function renderRepairOrderInventoryPanel() {
      const panel = els.repairOrderInventoryPanel;
      const isOpen = Boolean(state.repairOrderInventoryOpen);
      const materialsCard = els.repairOrderMaterialsBody?.closest('.repair-order-table-card');
      materialsCard?.classList.toggle('is-inventory-open', isOpen);
      if (els.repairOrderInventoryToggleButton) {
        els.repairOrderInventoryToggleButton.classList.toggle('is-active', isOpen);
        els.repairOrderInventoryToggleButton.setAttribute('aria-pressed', isOpen ? 'true' : 'false');
      }
      if (!panel) return;
      panel.hidden = !isOpen;
      if (!isOpen) return;
      if (els.repairOrderInventorySearchInput && els.repairOrderInventorySearchInput.value !== state.repairOrderInventoryQuery) {
        els.repairOrderInventorySearchInput.value = state.repairOrderInventoryQuery;
      }
      const items = repairOrderInventoryResults();
      if (els.repairOrderInventoryResults) {
        els.repairOrderInventoryResults.innerHTML = !state.inventoryLoaded && !items.length
          ? '<div class="cashboxes-empty">ЗАГРУЖАЮ СКЛАД...</div>'
          : (items.length
            ? items.map((item) => inventoryRowHtml(item, { panel: true })).join('')
            : '<div class="cashboxes-empty">НИЧЕГО НЕ НАЙДЕНО.</div>');
      }
      const selected = selectedRepairOrderInventoryItem();
      if (els.repairOrderInventorySelected) {
        els.repairOrderInventorySelected.innerHTML = selected
          ? '<div class="inventory-row__top"><span class="inventory-row__name">' + escapeHtml(selected.name || 'Позиция') + '</span><strong class="inventory-row__qty">' + escapeHtml(inventoryDisplayQuantity(selected)) + '</strong></div>'
            + '<div class="inventory-row__meta">' + escapeHtml(inventoryItemMeta(selected)) + '</div>'
          : '<div class="cashboxes-empty">ВЫБЕРИТЕ ПОЗИЦИЮ.</div>';
      }
      if (els.repairOrderInventoryQuantityInput && selected && !String(els.repairOrderInventoryQuantityInput.value || '').trim()) {
        els.repairOrderInventoryQuantityInput.value = '1';
      }
      const hasQuantity = Boolean(repairOrderInventoryQuantity());
      const requestedQuantity = repairOrderInventoryQuantity();
      if (els.repairOrderInventoryStock) {
        const stockText = selected ? ('ОСТАТОК: ' + inventoryDisplayQuantity(selected)) : 'ОСТАТОК: НЕ ВЫБРАНО';
        const overLimit = selected && requestedQuantity && requestedQuantity.parsed > inventoryItemQuantityNumber(selected);
        els.repairOrderInventoryStock.textContent = overLimit
          ? stockText + ' · НЕДОСТАТОЧНО ДЛЯ СПИСАНИЯ'
          : stockText;
        els.repairOrderInventoryStock.dataset.tone = overLimit ? 'error' : 'normal';
      }
      const hasMovement = Boolean(repairOrderInventorySelectedMovementId());
      if (els.repairOrderInventoryFillButton) els.repairOrderInventoryFillButton.disabled = !selected || !hasQuantity;
      if (els.repairOrderInventoryIssueButton) els.repairOrderInventoryIssueButton.disabled = !selected || !hasQuantity;
      if (els.repairOrderInventoryReturnButton) els.repairOrderInventoryReturnButton.disabled = !hasMovement;
    }

    function toggleRepairOrderInventoryPanel() {
      state.repairOrderInventoryOpen = !state.repairOrderInventoryOpen;
      renderRepairOrderInventoryPanel();
      if (state.repairOrderInventoryOpen) {
        if (!state.inventoryLoaded) loadInventoryItems(false, { query: state.repairOrderInventoryQuery });
        window.setTimeout(() => els.repairOrderInventorySearchInput?.focus({ preventScroll: true }), 0);
      }
    }

    function selectRepairOrderInventoryItem(itemId) {
      const normalizedId = String(itemId || '').trim();
      state.repairOrderInventorySelectedId = normalizedId;
      if (normalizedId) state.inventoryActiveId = normalizedId;
      if (els.repairOrderInventoryQuantityInput && !String(els.repairOrderInventoryQuantityInput.value || '').trim()) {
        els.repairOrderInventoryQuantityInput.value = '1';
      }
      renderRepairOrderInventoryPanel();
    }

    function handleRepairOrderInventorySearchInput() {
      state.repairOrderInventoryQuery = String(els.repairOrderInventorySearchInput?.value || '').trim();
      renderRepairOrderInventoryPanel();
      if (state.inventorySearchTimer) window.clearTimeout(state.inventorySearchTimer);
      state.inventorySearchTimer = window.setTimeout(() => {
        state.inventorySearchTimer = null;
        loadInventoryItems(false, { query: state.repairOrderInventoryQuery });
      }, 250);
    }

    function handleRepairOrderInventoryResultsClick(event) {
      const button = event.target instanceof HTMLElement ? event.target.closest('[data-repair-order-inventory-item-id]') : null;
      if (!button || !els.repairOrderInventoryResults?.contains(button)) return;
      selectRepairOrderInventoryItem(button.getAttribute('data-repair-order-inventory-item-id'));
    }

    function cashboxFormatMinorAmount(value) {
      const amount = finiteNumber(value);
      const rounded = Math.round(Math.abs(amount) / 100);
      const sign = amount < 0 && rounded > 0 ? '-' : '';
      return sign + rounded.toLocaleString('ru-RU', {
        maximumFractionDigits: 0,
      }) + ' ₽';
    }

    function activeCashboxStatistics() {
      return state.activeCashbox?.statistics || {
        transactions_total: 0,
        income_total_minor: 0,
        expense_total_minor: 0,
        balance_minor: 0,
        balance_display: cashboxFormatMinorAmount(0),
        balance_sign: 'positive',
      };
    }

    function filteredCashboxTransactions() {
      return Array.isArray(state.activeCashbox?.transactions) ? state.activeCashbox.transactions : [];
    }

    function cashboxTransactionIsTransfer(item) {
      if (item?.transfer_group_id || item?.related_transaction_id) return true;
      const note = String(item?.note || '').trim().toLowerCase();
      return note.startsWith('перемещение в ') || note.startsWith('перемещение из ');
    }

    function cashboxCancelledTransactionIds() {
      const ids = new Set();
      filteredCashboxTransactions().forEach((item) => {
        const kind = String(item?.transaction_kind || '').trim();
        const relatedId = String(item?.related_transaction_id || '').trim();
        if (kind === 'cashbox_cancellation' && relatedId) ids.add(relatedId);
      });
      return ids;
    }

    function cashboxTransactionCanBeCancelled(item) {
      const transactionId = String(item?.id || '').trim();
      if (!transactionId) return false;
      const kind = String(item?.transaction_kind || '').trim();
      if (kind === 'cashbox_cancellation' || kind === 'cashbox_cancelled') return false;
      return !cashboxCancelledTransactionIds().has(transactionId);
    }

    function cashboxTransactionById(transactionId) {
      const normalizedId = String(transactionId || '').trim();
      if (!normalizedId) return null;
      return filteredCashboxTransactions().find((item) => String(item?.id || '') === normalizedId) || null;
    }

    function buildCashboxStatistics(transactions) {
      const items = Array.isArray(transactions) ? transactions : [];
      let incomeMinor = 0;
      let expenseMinor = 0;
      let lastTransactionAt = '';
      items.forEach((item) => {
        const amountMinor = finiteNumber(item?.amount_minor);
        if (item?.direction === 'expense') expenseMinor += amountMinor;
        else incomeMinor += amountMinor;
        if (item?.created_at && (!lastTransactionAt || String(item.created_at) > lastTransactionAt)) {
          lastTransactionAt = String(item.created_at);
        }
      });
      const balanceMinor = incomeMinor - expenseMinor;
      return {
        transactions_total: items.length,
        income_total_minor: incomeMinor,
        expense_total_minor: expenseMinor,
        balance_minor: balanceMinor,
        balance_display: cashboxFormatMinorAmount(balanceMinor),
        income_total_display: cashboxFormatMinorAmount(incomeMinor),
        expense_total_display: cashboxFormatMinorAmount(expenseMinor),
        last_transaction_at: lastTransactionAt,
      };
    }

    function cashboxTransactionSourceLabel(item) {
      const payloadLabel = String(item?.source_label ?? item?.sourceLabel ?? '').trim();
      if (payloadLabel) return payloadLabel;
      const transactionKind = String(item?.transaction_kind ?? item?.transactionKind ?? '').trim().toLowerCase();
      if (transactionKind === 'repair_order_payment') return 'заказ-наряд';
      if (transactionKind === 'salary_payout') return 'зарплата';
      if (transactionKind === 'salary_advance') return 'аванс';
      const note = String(item?.note || '').trim();
      if (note.toLowerCase().startsWith('перемещение')) return 'перемещение';
      if (/заказ-наряд\s*№/i.test(note)) return 'заказ-наряд';
      const source = String(item?.source || '').trim().toLowerCase();
      if (source === 'ui') return 'ручное';
      if (source === 'mcp') return 'mcp';
      return source ? source : 'система';
    }

    function syncCashboxFiltersUi() {
      return;
    }

    function resetCashboxDragState() {
      state.cashboxDragId = '';
      state.cashboxDropBeforeId = '';
      syncCashboxDragClasses();
    }

    function syncCashboxDragClasses() {
      if (!els.cashboxesList) return;
      const isDragActive = Boolean(state.cashboxDragId);
      const isDropEnd = state.cashboxDropBeforeId === '__end__';
      els.cashboxesList.classList.toggle('is-drag-active', isDragActive);
      els.cashboxesList.classList.toggle('is-drop-end', isDropEnd);
      els.cashboxesList.querySelectorAll('[data-cashbox-id]').forEach((row) => {
        const cashboxId = String(row.dataset.cashboxId || '').trim();
        row.classList.toggle('is-dragging', Boolean(cashboxId && cashboxId === state.cashboxDragId));
        row.classList.toggle('is-drop-target', Boolean(cashboxId && cashboxId === state.cashboxDropBeforeId && cashboxId !== state.cashboxDragId));
      });
    }

    function setCashboxDropBeforeId(nextId) {
      const normalized = String(nextId || '').trim();
      if (state.cashboxDropBeforeId === normalized) return false;
      state.cashboxDropBeforeId = normalized;
      syncCashboxDragClasses();
      return true;
    }

    function cashboxBalanceMinor(cashbox) {
      return finiteNumber(cashbox?.statistics?.balance_minor);
    }

    function cashboxBalanceDisplay(cashbox) {
      const balanceMinor = cashboxBalanceMinor(cashbox);
      return String(cashbox?.statistics?.balance_display || cashboxFormatMinorAmount(balanceMinor));
    }

    function cashboxBalanceSign(balanceMinor) {
      return finiteNumber(balanceMinor) < 0 ? 'negative' : 'positive';
    }

    function invalidateCashboxesCache() {
      state.cashboxesLoaded = false;
      state.cashboxJournalData = null;
    }

    function cashboxesModalIsOpen() {
      return Boolean(els.cashboxesModal?.classList.contains('is-open'));
    }

    function cashboxMutationPath(path) {
      const normalizedPath = String(path || '').split('?')[0];
      return [
        '/api/create_cash_transaction',
        '/api/create_cashbox_transfer',
        '/api/cancel_cash_transaction',
        '/api/cancel_last_cash_transaction',
        '/api/create_employee_salary_transaction',
        '/api/update_card',
        '/api/update_repair_order',
        '/api/set_repair_order_status',
      ].includes(normalizedPath);
    }

    function notifyCashboxesMutation(path, method = 'GET') {
      if (String(method || 'GET').toUpperCase() === 'GET') return;
      if (!cashboxMutationPath(path)) return;
      invalidateCashboxesCache();
    }

    async function refreshCashboxesAfterMoneyMutation({ openModal = false, deferDetail = true } = {}) {
      invalidateCashboxesCache();
      const shouldReload = openModal
        || cashboxesModalIsOpen()
        || (state.mobileLite && state.mobileView === 'cashboxes');
      if (!shouldReload) return;
      await loadCashboxes(openModal, { deferDetail });
    }

    function cashboxDropBeforeIdFromRow(row, clientY) {
      const targetId = String(row?.dataset?.cashboxId || '').trim();
      if (!targetId || targetId === state.cashboxDragId) return '';
      const items = Array.isArray(state.cashboxes) ? state.cashboxes : [];
      const index = items.findIndex((item) => item.id === targetId);
      if (index < 0) return '__end__';
      const rect = row.getBoundingClientRect();
      const before = finiteNumber(clientY) < (rect.top + rect.height / 2);
      if (before) return targetId;
      return items[index + 1]?.id || '__end__';
    }

    function syncCashboxInList(cashbox) {
      if (!cashbox?.id) return;
      const nextItems = (state.cashboxes || []).slice();
      const index = nextItems.findIndex((item) => item.id === cashbox.id);
      if (index >= 0) nextItems[index] = cashbox;
      else nextItems.push(cashbox);
      nextItems.sort((left, right) => {
        const orderDiff = finiteNumber(left?.order) - finiteNumber(right?.order);
        if (orderDiff) return orderDiff;
        const nameDiff = String(left?.name || '').localeCompare(String(right?.name || ''), 'ru', { sensitivity: 'base' });
        if (nameDiff) return nameDiff;
        return String(left?.id || '').localeCompare(String(right?.id || ''));
      });
      state.cashboxes = nextItems;
    }

    function renderCashboxesList() {
      const items = Array.isArray(state.cashboxes) ? state.cashboxes : [];
      const isDropEnd = state.cashboxDropBeforeId === '__end__';
      els.cashboxesList.classList.toggle('is-drop-end', isDropEnd);
      els.cashboxesList.innerHTML = items.length ? items.map((item) => {
        const stats = item?.statistics || {};
        const balanceMinor = cashboxBalanceMinor(item);
        const balanceDisplay = cashboxBalanceDisplay(item);
        const balanceSign = String(stats?.balance_sign || cashboxBalanceSign(balanceMinor));
        const activeClass = item.id === state.activeCashboxId ? ' is-active' : '';
        const draggingClass = item.id === state.cashboxDragId ? ' is-dragging' : '';
        const dropClass = item.id === state.cashboxDropBeforeId ? ' is-drop-target' : '';
        return '<div class="cashbox-row' + activeClass + draggingClass + dropClass + '" role="button" tabindex="0" data-cashbox-id="' + escapeHtml(item.id) + '" draggable="true" title="Перетащите, чтобы изменить порядок касс">'
          + '<div class="cashbox-row__head">'
          + '<div class="cashbox-row__name">' + escapeHtml(item.name || '—') + '</div>'
          + '<div class="cashbox-row__balance" data-balance-sign="' + escapeHtml(balanceSign) + '">' + escapeHtml(balanceDisplay) + '</div>'
          + '</div>'
          + '</div>';
      }).join('') : '<div class="cashboxes-empty">КАСС ПОКА НЕТ.</div>';
      syncCashboxDragClasses();
      renderMobileShell();
    }

    function renderCashboxTransactions() {
      const transactions = filteredCashboxTransactions();
      const meta = state.activeCashbox?.meta || {};
      const rowsHtml = transactions.length ? transactions.map((item) => {
        const direction = item?.direction === 'expense' ? 'expense' : 'income';
        const note = String(item?.note || '').trim() || 'Без комментария';
        const actor = String(item?.actor_name || '').trim() || '—';
        const sourceLabel = cashboxTransactionSourceLabel(item);
        const linkParts = [];
        if (item?.repair_order_number) linkParts.push('ЗН №' + String(item.repair_order_number));
        if (item?.repair_order_vehicle) linkParts.push(String(item.repair_order_vehicle));
        const flags = cashJournalLinkFlags(item);
        const contextLabel = 'Источник: ' + sourceLabel + (linkParts.length ? ' · ' + linkParts.join(' · ') : '');
        const contextHtml = escapeHtml(contextLabel) + (flags.length ? '<div class="cashbox-journal-link-flags">' + flags.map((flag) => '<span class="cashbox-journal-link-flag">' + escapeHtml(flag) + '</span>').join('') + '</div>' : '');
        const absoluteAmount = cashboxFormatMinorAmount(item?.amount_minor ?? 0).replace(/^-/, '');
        const canCancel = cashboxTransactionCanBeCancelled(item);
        const cancelHtml = canCancel
          ? '<button class="cashbox-transaction__cancel" type="button" data-cashbox-transaction-cancel="' + escapeHtml(item.id || '') + '" title="Отменить платеж" aria-label="Отменить платеж">&times;</button>'
          : '<button class="cashbox-transaction__cancel" type="button" hidden aria-hidden="true" tabindex="-1">&times;</button>';
        return '<div class="cashbox-transaction">'
          + '<div class="cashbox-transaction__badge" data-direction="' + escapeHtml(direction) + '">' + escapeHtml(direction === 'expense' ? 'списание' : 'поступление') + '</div>'
          + '<div class="cashbox-transaction__body"><div class="cashbox-transaction__summary"><div class="cashbox-transaction__note">' + escapeHtml(note) + '</div><div class="cashbox-transaction__context">' + contextHtml + '</div></div><div class="cashbox-transaction__meta">' + escapeHtml(item?.business_datetime_display || formatDate(item?.created_at)) + ' | ' + escapeHtml(actor) + '</div></div>'
          + '<div class="cashbox-transaction__amount" data-direction="' + escapeHtml(direction) + '">' + escapeHtml(direction === 'expense' ? '-' : '+') + escapeHtml(absoluteAmount) + '</div>'
          + cancelHtml
          + '</div>';
      }).join('') : '<div class="cashboxes-empty">ПО ФИЛЬТРУ НИЧЕГО НЕ НАЙДЕНО.</div>';
      const hasMore = Boolean(meta?.has_more);
      const total = finiteNonNegativeNumber(meta?.transactions_total, transactions.length);
      const moreHtml = hasMore
        ? '<button class="btn btn--ghost cashbox-transactions__more" type="button" data-cashbox-transactions-load-more="true">ПОКАЗАТЬ ЕЩЁ · ' + escapeHtml(String(transactions.length)) + '/' + escapeHtml(String(total)) + '</button>'
        : '';
      els.cashboxTransactions.innerHTML = rowsHtml + moreHtml;
    }

    function renderCashboxDetail() {
      const cashbox = state.activeCashbox?.cashbox || null;
      if (!cashbox) {
        els.cashboxDetailTitle.textContent = 'КАССА НЕ ВЫБРАНА';
        els.cashboxDetailMeta.textContent = '';
        els.cashboxIncomeButton.disabled = true;
        els.cashboxTransferButton.disabled = true;
        els.cashboxExpenseButton.disabled = true;
        syncCashboxFiltersUi();
        els.cashboxTransactions.innerHTML = '<div class="cashboxes-empty">НЕТ ДАННЫХ.</div>';
        closeCashboxCancelPopover();
        renderMobileShell();
        return;
      }
      els.cashboxDetailTitle.textContent = cashbox.name || 'КАССА';
      els.cashboxDetailMeta.textContent = '';
      els.cashboxIncomeButton.disabled = false;
      els.cashboxTransferButton.disabled = (Array.isArray(state.cashboxes) ? state.cashboxes.length : 0) < 2;
      els.cashboxExpenseButton.disabled = false;
      syncCashboxFiltersUi();
      renderCashboxTransactions();
      if (state.cashboxCancelTransactionId && !cashboxTransactionById(state.cashboxCancelTransactionId)) {
        closeCashboxCancelPopover();
      }
      renderMobileShell();
    }

    function abortCashboxesLoad() {
      if (state.cashboxesLoadController) {
        state.cashboxesLoadController.abort();
      }
      state.cashboxesLoadController = null;
      state.cashboxesRequestSeq += 1;
    }

    function beginCashboxesLoad() {
      if (state.cashboxesLoadController) {
        state.cashboxesLoadController.abort();
      }
      const controller = new AbortController();
      state.cashboxesLoadController = controller;
      state.cashboxesRequestSeq += 1;
      return { controller, seq: state.cashboxesRequestSeq };
    }

    function isCurrentCashboxesLoad(loadContext) {
      return Boolean(
        loadContext
        && state.cashboxesLoadController === loadContext.controller
        && state.cashboxesRequestSeq === loadContext.seq
        && (state.mobileLite || els.cashboxesModal?.classList.contains('is-open'))
      );
    }

    function finishCashboxesLoad(loadContext) {
      if (state.cashboxesLoadController === loadContext?.controller) {
        state.cashboxesLoadController = null;
      }
    }

    async function loadCashboxDetail(cashboxId, { openModal = false, offset = 0, append = false, loadContext = null } = {}) {
      const normalizedId = String(cashboxId || '').trim();
      if (!normalizedId) return null;
      if (openModal) maybeOpenModal(els.cashboxesModal, true);
      const ownsLoadContext = !loadContext;
      if (!loadContext) loadContext = beginCashboxesLoad();
      try {
        const transactionOffset = finiteNonNegativeNumber(offset);
        const data = await api('/api/get_cashbox?cashbox_id=' + encodeURIComponent(normalizedId) + '&transaction_limit=' + CASHBOX_TRANSACTION_PAGE_SIZE + '&transaction_offset=' + transactionOffset + '&compact=true', {
          signal: loadContext.controller.signal,
        });
        if (!isCurrentCashboxesLoad(loadContext)) return null;
        const nextTransactions = Array.isArray(data?.transactions) ? data.transactions : [];
        const canAppend = append && state.activeCashbox?.cashbox?.id === (data?.cashbox?.id || normalizedId);
        const transactions = canAppend
          ? filteredCashboxTransactions().concat(nextTransactions)
          : nextTransactions;
        state.activeCashboxId = data?.cashbox?.id || normalizedId;
        state.activeCashbox = {
          cashbox: data?.cashbox || null,
          transactions,
          meta: data?.meta || {},
          statistics: data?.cashbox?.statistics || {},
        };
        if (data?.cashbox) syncCashboxInList(data.cashbox);
        renderCashboxesList();
        renderCashboxDetail();
        maybeOpenModal(els.cashboxesModal, openModal);
        return data;
      } catch (error) {
        if (error?.name === 'AbortError' || !isCurrentCashboxesLoad(loadContext)) return null;
        els.cashboxDetailTitle.textContent = 'ОШИБКА ЗАГРУЗКИ';
        els.cashboxDetailMeta.textContent = error.message;
        els.cashboxTransactions.innerHTML = '<div class="cashboxes-empty">' + escapeHtml(error.message) + '</div>';
        maybeOpenModal(els.cashboxesModal, openModal);
        setStatus(error.message, true);
        return null;
      } finally {
        if (ownsLoadContext) finishCashboxesLoad(loadContext);
      }
    }

    async function loadMoreCashboxTransactions() {
      const cashboxId = String(state.activeCashbox?.cashbox?.id || state.activeCashboxId || '').trim();
      if (!cashboxId) return;
      await loadCashboxDetail(cashboxId, {
        openModal: true,
        offset: filteredCashboxTransactions().length,
        append: true,
      });
    }

    function scheduleCashboxDetailLoad(cashboxId, { openModal = false } = {}) {
      const normalizedId = String(cashboxId || '').trim();
      if (!normalizedId) return;
      window.setTimeout(() => {
        if (!els.cashboxesModal?.classList.contains('is-open')) return;
        if (String(state.activeCashboxId || '').trim() !== normalizedId) return;
        loadCashboxDetail(normalizedId, { openModal });
      }, CASHBOX_DETAIL_DEFER_DELAY_MS);
    }

    async function loadCashboxes(openModal = false, { deferDetail = false } = {}) {
      if (openModal) maybeOpenModal(els.cashboxesModal, true);
      const loadContext = beginCashboxesLoad();
      try {
        resetCashboxDragState();
        const data = await api('/api/list_cashboxes?limit=200', {
          signal: loadContext.controller.signal,
        });
        if (!isCurrentCashboxesLoad(loadContext)) return null;
        state.cashboxes = Array.isArray(data?.cashboxes) ? data.cashboxes : [];
        state.cashboxesLoaded = true;
        const nextId = state.cashboxes.some((item) => item.id === state.activeCashboxId)
          ? state.activeCashboxId
          : (state.cashboxes[0]?.id || '');
        renderCashboxesList();
        if (nextId) {
          if (deferDetail) {
            const summaryCashbox = state.cashboxes.find((item) => item.id === nextId) || null;
            state.activeCashboxId = nextId;
            state.activeCashbox = {
              cashbox: summaryCashbox,
              transactions: [],
              meta: summaryCashbox?.statistics || {},
              statistics: summaryCashbox?.statistics || {},
            };
            renderCashboxesList();
            renderCashboxDetail();
            els.cashboxTransactions.innerHTML = '<div class="cashboxes-empty">ЗАГРУЖАЮ ДВИЖЕНИЯ...</div>';
            maybeOpenModal(els.cashboxesModal, openModal);
            scheduleCashboxDetailLoad(nextId, { openModal });
            return data;
          }
          await loadCashboxDetail(nextId, { openModal, loadContext });
          return data;
        }
        state.activeCashboxId = '';
        state.activeCashbox = null;
        state.cashboxesLoaded = true;
        renderCashboxDetail();
        maybeOpenModal(els.cashboxesModal, openModal);
        return data;
      } catch (error) {
        if (error?.name === 'AbortError' || !isCurrentCashboxesLoad(loadContext)) return null;
        state.cashboxesLoaded = false;
        els.cashboxesList.innerHTML = '<div class="cashboxes-empty">' + escapeHtml(error.message) + '</div>';
        state.activeCashboxId = '';
        state.activeCashbox = null;
        renderCashboxDetail();
        maybeOpenModal(els.cashboxesModal, openModal);
        setStatus(error.message, true);
        return null;
      } finally {
        finishCashboxesLoad(loadContext);
      }
    }

    function openCashboxesModal() {
      maybeOpenModal(els.cashboxesModal, true);
      els.cashboxDetailTitle.textContent = 'ЗАГРУЖАЮ КАССЫ...';
      els.cashboxDetailMeta.textContent = '';
      els.cashboxTransactions.innerHTML = '<div class="cashboxes-empty">ЗАГРУЖАЮ ДВИЖЕНИЯ...</div>';
      if (!state.cashboxesLoaded || !Array.isArray(state.cashboxes) || !state.cashboxes.length) {
        els.cashboxesList.innerHTML = '<div class="cashboxes-empty">ЗАГРУЖАЮ КАССЫ...</div>';
      }
      if (!state.activeCashbox) {
        renderCashboxDetail();
      }
      if (state.cashboxesLoaded) {
        const cachedId = String(state.activeCashboxId || state.cashboxes[0]?.id || '').trim();
        if (!state.activeCashbox && cachedId) {
          const summaryCashbox = state.cashboxes.find((item) => item.id === cachedId) || null;
          state.activeCashboxId = cachedId;
          state.activeCashbox = {
            cashbox: summaryCashbox,
            transactions: [],
            meta: summaryCashbox?.statistics || {},
            statistics: summaryCashbox?.statistics || {},
          };
        }
        renderCashboxesList();
        renderCashboxDetail();
      }
      loadCashboxes(false, { deferDetail: true });
    }

    async function loadCashJournalData({ includeMarkdown = false } = {}) {
      const journalPath = includeMarkdown
        ? '/api/get_cash_journal?months=3&limit=5000&include_markdown=true'
        : '/api/get_cash_journal?months=3&limit=5000&include_markdown=false&compact_groups=true';
      const [journalData, cashboxesData] = await Promise.all([
        api(journalPath),
        api('/api/list_cashboxes?limit=200'),
      ]);
      return {
        ...(journalData || {}),
        cashboxes: Array.isArray(cashboxesData?.cashboxes) ? cashboxesData.cashboxes : [],
      };
    }

    async function loadCashJournalText() {
      const data = await loadCashJournalData({ includeMarkdown: true });
      return String(data?.markdown || data?.text || 'ЗА ВЫБРАННЫЙ ПЕРИОД ДВИЖЕНИЙ НЕТ.');
    }

    function renderCashJournalLoading() {
      return '<div class="cashbox-journal-loading">'
        + '<div class="cashbox-journal-loading__title">ЗАГРУЖАЮ ЖУРНАЛ...</div>'
        + '<div class="cashbox-journal-loading__hint">На наполненной базе это может занять несколько секунд. Фильтры появятся после загрузки операций.</div>'
        + '</div>';
    }

    function cashJournalDefaultFilters() {
      return { query: '', cashbox: '', type: 'all', period: 'all', periodKind: '', periodKey: '', periodLabel: '' };
    }

    function cashJournalFilters() {
      const current = state.cashboxJournalFilters || {};
      const defaults = cashJournalDefaultFilters();
      const type = ['all', 'income', 'expense', 'transfer'].indexOf(current.type) >= 0 ? current.type : defaults.type;
      const period = ['all', '30', '7', 'today'].indexOf(current.period) >= 0 ? current.period : defaults.period;
      const periodKind = ['day', 'week', 'month'].indexOf(current.periodKind) >= 0 ? String(current.periodKind) : '';
      const periodKey = periodKind ? String(current.periodKey || '').trim() : '';
      return {
        query: String(current.query || ''),
        cashbox: String(current.cashbox || ''),
        type,
        period,
        periodKind: periodKey ? periodKind : '',
        periodKey,
        periodLabel: periodKey ? String(current.periodLabel || current.periodKey || '') : '',
      };
    }

    function cashJournalStatHtml(label, value, sign = 'positive') {
      return '<div class="cashbox-journal-stat">'
        + '<div class="cashbox-journal-stat__label">' + escapeHtml(label) + '</div>'
        + '<div class="cashbox-journal-stat__value" data-balance-sign="' + escapeHtml(sign) + '">' + escapeHtml(value) + '</div>'
        + '</div>';
    }

    function cashJournalSingleTransferDisplay(incomeMinor, expenseMinor) {
      const transferMinor = Math.max(Math.abs(finiteNumber(incomeMinor)), Math.abs(finiteNumber(expenseMinor)));
      return cashboxFormatMinorAmount(transferMinor);
    }

    function cashJournalTransferSummaryText(transferMinor, count) {
      return cashboxFormatMinorAmount(transferMinor) + ' · ' + String(finiteNumber(count)) + ' оп.';
    }

    function cashJournalSignedAmountDisplay(amountMinor) {
      const amount = finiteNumber(amountMinor);
      return (amount > 0 ? '+' : '') + cashboxFormatMinorAmount(amount);
    }

    function cashJournalVisibleSource(sourceLabel) {
      const source = String(sourceLabel || '').trim();
      if (!source) return '';
      const normalized = source.toLowerCase();
      if (['api', 'ручное', 'система'].indexOf(normalized) >= 0) return '';
      return source;
    }

    function cashJournalCleanOperationNote(note) {
      const text = String(note || '').trim();
      const cleaned = text.replace(/^(?:поступление|списание|приход|расход)\s*:\s*/i, '').trim();
      return cleaned || 'Без комментария';
    }

    function cashJournalDisplayTypeLabel(direction) {
      if (direction === 'transfer') return 'Перевод';
      return direction === 'expense' ? 'Расход' : 'Приход';
    }

    function cashJournalLinkFlags(item) {
      const status = String(item?.link_status || '').trim();
      const flags = [];
      if (status === 'linked_legacy') flags.push('legacy');
      if (status === 'payment_without_order') flags.push('нет связи с оплатой');
      if (status === 'legacy_without_payment') flags.push('legacy');
      if (status === 'legacy_without_payment') flags.push('проверить связь');
      if (item?.stored_note && item.stored_note !== item.note) flags.push('исправлен display-note');
      return flags;
    }

    function cashJournalOperationTagsHtml(tags) {
      const items = (Array.isArray(tags) ? tags : [])
        .map((tag) => String(tag || '').trim())
        .filter(Boolean);
      if (!items.length) return '';
      return '<div class="cashbox-journal-operation-tags">'
        + items.map((tag) => '<span class="cashbox-journal-operation-tag">' + escapeHtml(tag) + '</span>').join('')
        + '</div>';
    }

    function cashJournalEntryNoteText(item) {
      const direction = item?.direction === 'expense' ? 'expense' : 'income';
      if (item?.repair_order_number) {
        const parts = ['ЗН №' + String(item.repair_order_number)];
        if (item?.repair_order_vehicle) parts.push(String(item.repair_order_vehicle));
        return parts.join(' · ');
      }
      return cashJournalCleanOperationNote(item?.note || (direction === 'expense' ? 'Расход' : 'Приход'));
    }

    function cashJournalTransferNote(item) {
      const raw = String(item?.note || '').trim();
      return raw
        .replace(/^перемещение\s+(?:в|из)\s+[^:]+(?::\s*)?/i, '')
        .trim();
    }

    function cashJournalTextKey(value) {
      return String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
    }

    function cashJournalLegacyTransferPeerName(item) {
      const note = String(item?.note || '').trim();
      const direction = item?.direction === 'expense' ? 'expense' : 'income';
      const pattern = direction === 'expense'
        ? /^перемещение\s+в\s+(.+?)(?::|$)/i
        : /^перемещение\s+из\s+(.+?)(?::|$)/i;
      const match = note.match(pattern);
      return match ? String(match[1] || '').trim() : '';
    }

    function cashJournalLegacyTransferActorKey(item) {
      return cashJournalTextKey(item?.actor_label || item?.actor_name || '');
    }

    function cashJournalLegacyTransferPairMatches(item, candidate) {
      if (item?.source_label !== 'перемещение' || candidate?.source_label !== 'перемещение') return false;
      if (candidate?.direction === item?.direction) return false;
      const sameDate = cashJournalEntryDateKey(candidate) === cashJournalEntryDateKey(item);
      const sameTime = String(candidate?.time_short || '') === String(item?.time_short || '');
      const amountMinor = finiteNumber(item?.amount_minor);
      const sameAmount = finiteNumber(candidate?.amount_minor) === amountMinor;
      if (!sameDate || !sameTime || !sameAmount || !amountMinor) return false;
      const itemActor = cashJournalLegacyTransferActorKey(item);
      const candidateActor = cashJournalLegacyTransferActorKey(candidate);
      if (itemActor && candidateActor && itemActor !== candidateActor) return false;
      const source = item?.direction === 'expense' ? item : candidate;
      const target = item?.direction === 'income' ? item : candidate;
      const sourceCashbox = cashJournalTextKey(source?.cashbox_name || '');
      const targetCashbox = cashJournalTextKey(target?.cashbox_name || '');
      const sourcePeer = cashJournalTextKey(cashJournalLegacyTransferPeerName(source));
      const targetPeer = cashJournalTextKey(cashJournalLegacyTransferPeerName(target));
      if (sourcePeer && sourcePeer !== targetCashbox) return false;
      if (targetPeer && targetPeer !== sourceCashbox) return false;
      return Boolean(sourcePeer || targetPeer);
    }

    function cashJournalFindTransferPair(item, entries, usedIds) {
      const itemId = String(item?.id || '');
      if (item?.source_label !== 'перемещение' || usedIds.has(itemId)) return null;
      const relatedId = String(item?.related_transaction_id || '');
      const transferGroupId = String(item?.transfer_group_id || '');
      for (const candidate of entries) {
        const candidateId = String(candidate?.id || '');
        if (!candidateId || candidateId === itemId || usedIds.has(candidateId)) continue;
        if (candidate?.source_label !== 'перемещение') continue;
        const sameRelated = relatedId && candidateId === relatedId;
        const sameGroup = transferGroupId && String(candidate?.transfer_group_id || '') === transferGroupId;
        if (!sameRelated && !sameGroup) continue;
        if (candidate?.direction === item?.direction) continue;
        const source = item?.direction === 'expense' ? item : candidate;
        const target = item?.direction === 'income' ? item : candidate;
        return { source, target };
      }
      const legacyCandidates = entries.filter((candidate) => {
        const candidateId = String(candidate?.id || '');
        if (!candidateId || candidateId === itemId || usedIds.has(candidateId)) return false;
        return cashJournalLegacyTransferPairMatches(item, candidate);
      });
      if (legacyCandidates.length === 1) {
        const candidate = legacyCandidates[0];
        const source = item?.direction === 'expense' ? item : candidate;
        const target = item?.direction === 'income' ? item : candidate;
        return { source, target };
      }
      return null;
    }

    function cashJournalDisplayRows(entries) {
      const sourceEntries = Array.isArray(entries) ? entries : [];
      const rows = [];
      const usedIds = new Set();
      sourceEntries.forEach((item) => {
        const itemId = String(item?.id || '');
        if (itemId && usedIds.has(itemId)) return;
        const transferPair = cashJournalFindTransferPair(item, sourceEntries, usedIds);
        if (transferPair) {
          if (transferPair.source?.id) usedIds.add(String(transferPair.source.id));
          if (transferPair.target?.id) usedIds.add(String(transferPair.target.id));
          rows.push({ kind: 'transfer', ...transferPair });
          return;
        }
        if (itemId) usedIds.add(itemId);
        rows.push({ kind: 'operation', item });
      });
      return rows;
    }

    function cashJournalFlatEntries(data) {
      if (Array.isArray(data?.entries) && data.entries.length) return data.entries;
      const days = Array.isArray(data?.days) ? data.days : [];
      const entries = [];
      days.forEach((day) => {
        if (Array.isArray(day?.entries)) entries.push(...day.entries);
      });
      return entries;
    }

    function cashJournalRowItems(row) {
      if (row?.kind === 'transfer') return [row.source, row.target].filter(Boolean);
      return row?.item ? [row.item] : [];
    }

    function cashJournalEntryDateKey(item) {
      const date = String(item?.business_date || item?.date || '').trim();
      if (date) return date.slice(0, 10);
      return String(item?.created_at || '').slice(0, 10);
    }

    function cashJournalDateFromKey(key) {
      const parts = String(key || '').split('-').map((part) => finiteNumber(part, NaN));
      if (parts.length < 3 || parts.some((part) => Number.isNaN(part))) return null;
      return new Date(parts[0], parts[1] - 1, parts[2]);
    }

    function cashJournalDateKey(date) {
      if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
      const year = String(date.getFullYear()).padStart(4, '0');
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return year + '-' + month + '-' + day;
    }

    function cashJournalPeriodAnchor(data) {
      const entries = cashJournalFlatEntries(data);
      let anchor = null;
      entries.forEach((item) => {
        const date = cashJournalDateFromKey(cashJournalEntryDateKey(item));
        if (date && (!anchor || date > anchor)) anchor = date;
      });
      return anchor || new Date();
    }

    function cashJournalEntryMatchesPeriod(item, period, anchor) {
      if (period === 'all') return true;
      const date = cashJournalDateFromKey(cashJournalEntryDateKey(item));
      if (!date) return false;
      const anchorDay = new Date(anchor.getFullYear(), anchor.getMonth(), anchor.getDate());
      if (period === 'today') return cashJournalDateKey(date) === cashJournalDateKey(anchorDay);
      const days = period === '7' ? 7 : 30;
      const start = new Date(anchorDay);
      start.setDate(start.getDate() - (days - 1));
      return date >= start && date <= anchorDay;
    }

    function cashJournalEntryMatchesExactPeriod(item, periodKind, periodKey) {
      const key = String(periodKey || '').trim();
      if (!key) return true;
      if (periodKind === 'day') return cashJournalEntryDateKey(item) === key;
      if (periodKind === 'week') return String(item?.week_key || '') === key;
      if (periodKind === 'month') return String(item?.month_key || '') === key;
      return true;
    }

    function cashJournalSearchTextForItem(item) {
      return [
        item?.time_short,
        item?.cashbox_name,
        item?.direction_label,
        item?.signed_amount_display,
        item?.amount_display,
        item?.note,
        item?.source_label,
        item?.link_status,
        item?.repair_order_number,
        item?.repair_order_vehicle,
        item?.repair_order_card_id,
        item?.repair_order_payment_id,
        item?.actor_label,
        item?.actor_name,
        item?.short_id,
        item?.transaction_kind,
      ].map((part) => String(part || '').toLowerCase()).join(' ');
    }

    function cashJournalRowMatchesFilters(row, filters, anchor) {
      const items = cashJournalRowItems(row);
      if (!items.length) return false;
      if (filters.type !== 'all') {
        const rowType = row?.kind === 'transfer' ? 'transfer' : String(items[0]?.direction || '');
        if (rowType !== filters.type) return false;
      }
      if (filters.cashbox && !items.some((item) => String(item?.cashbox_id || '') === filters.cashbox)) {
        return false;
      }
      if (filters.periodKind && filters.periodKey) {
        if (!items.some((item) => cashJournalEntryMatchesExactPeriod(item, filters.periodKind, filters.periodKey))) {
          return false;
        }
      } else if (!items.some((item) => cashJournalEntryMatchesPeriod(item, filters.period, anchor))) {
        return false;
      }
      const query = String(filters.query || '').trim().toLowerCase();
      if (query && !items.map(cashJournalSearchTextForItem).join(' ').includes(query)) {
        return false;
      }
      return true;
    }

    function cashJournalFilteredEntries(data) {
      const entries = cashJournalFlatEntries(data);
      const filters = cashJournalFilters();
      const anchor = cashJournalPeriodAnchor(data);
      const rows = cashJournalDisplayRows(entries);
      const result = [];
      const usedIds = new Set();
      rows.forEach((row) => {
        if (!cashJournalRowMatchesFilters(row, filters, anchor)) return;
        cashJournalRowItems(row).forEach((item) => {
          const id = String(item?.id || '');
          if (id && usedIds.has(id)) return;
          if (id) usedIds.add(id);
          result.push(item);
        });
      });
      return result;
    }

    function cashJournalSummarizeEntries(entries, base = {}) {
      let externalIncomeMinor = 0;
      let externalExpenseMinor = 0;
      let transferIncomeMinor = 0;
      let transferExpenseMinor = 0;
      (Array.isArray(entries) ? entries : []).forEach((item) => {
        const amount = Math.abs(finiteNumber(item?.amount_minor));
        const isTransfer = item?.source_label === 'перемещение';
        if (item?.direction === 'expense') {
          if (isTransfer) transferExpenseMinor += amount;
          else externalExpenseMinor += amount;
        } else {
          if (isTransfer) transferIncomeMinor += amount;
          else externalIncomeMinor += amount;
        }
      });
      const balanceMinor = externalIncomeMinor - externalExpenseMinor;
      const rowsCount = cashJournalDisplayRows(entries).length;
      return {
        ...base,
        entries,
        count: rowsCount,
        income_minor: externalIncomeMinor + transferIncomeMinor,
        expense_minor: externalExpenseMinor + transferExpenseMinor,
        balance_minor: balanceMinor,
        external_income_minor: externalIncomeMinor,
        external_expense_minor: externalExpenseMinor,
        transfer_income_minor: transferIncomeMinor,
        transfer_expense_minor: transferExpenseMinor,
        income_display: cashboxFormatMinorAmount(externalIncomeMinor + transferIncomeMinor),
        expense_display: cashboxFormatMinorAmount(externalExpenseMinor + transferExpenseMinor),
        balance_display: cashJournalSignedAmountDisplay(balanceMinor),
        external_income_display: cashboxFormatMinorAmount(externalIncomeMinor),
        external_expense_display: cashboxFormatMinorAmount(externalExpenseMinor),
        transfer_income_display: cashboxFormatMinorAmount(transferIncomeMinor),
        transfer_expense_display: cashboxFormatMinorAmount(transferExpenseMinor),
      };
    }

    function cashJournalRebuildDays(data, entries) {
      const baseByDate = new Map();
      (Array.isArray(data?.days) ? data.days : []).forEach((day) => {
        baseByDate.set(String(day?.date || day?.key || ''), day);
      });
      const groups = new Map();
      (Array.isArray(entries) ? entries : []).forEach((item) => {
        const key = cashJournalEntryDateKey(item);
        if (!key) return;
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key).push(item);
      });
      return Array.from(groups.entries()).map(([key, dayEntries]) => {
        const base = baseByDate.get(key) || { key, date: key, label: key };
        return cashJournalSummarizeEntries(dayEntries, { ...base, key, date: base.date || key });
      });
    }

    function cashJournalDaySummaryHtml(day) {
      const transferIncomeMinor = finiteNumber(day?.transfer_income_minor);
      const transferExpenseMinor = finiteNumber(day?.transfer_expense_minor);
      const balanceMinor = finiteNumber(day?.balance_minor);
      const operationCount = finiteNumber(day?.count, cashJournalDisplayRows(day?.entries || []).length);
      const parts = [
        'приход ' + String(day?.external_income_display || cashboxFormatMinorAmount(day?.external_income_minor ?? 0)),
        'расход ' + String(day?.external_expense_display || cashboxFormatMinorAmount(day?.external_expense_minor ?? 0)),
        'дельта ' + String(day?.balance_display || cashJournalSignedAmountDisplay(balanceMinor)),
      ];
      if (transferIncomeMinor || transferExpenseMinor) {
        parts.push('перемещения ' + cashJournalSingleTransferDisplay(transferIncomeMinor, transferExpenseMinor));
      }
      parts.push(String(operationCount) + ' оп.');
      return parts.map((part) => '<span>' + escapeHtml(part) + '</span>').join('');
    }

    function cashJournalDayCompactSummaryHtml(day) {
      const balanceMinor = finiteNumber(day?.balance_minor);
      const operationCount = finiteNumber(day?.count, cashJournalDisplayRows(day?.entries || []).length);
      const balanceText = String(day?.balance_display || cashJournalSignedAmountDisplay(balanceMinor));
      const sign = balanceMinor < 0 ? 'negative' : 'positive';
      return '<span data-balance-sign="' + escapeHtml(sign) + '">' + escapeHtml(balanceText) + ' · ' + escapeHtml(String(operationCount)) + ' оп.</span>';
    }

    function renderCashJournalDayDetails(day) {
      const details = cashJournalDaySummaryHtml(day || {});
      if (!details) return '';
      return '<details class="cashbox-journal-day-details">'
        + '<summary>Детали дня</summary>'
        + '<div class="cashbox-journal-day-details__grid">' + details + '</div>'
        + '</details>';
    }

    function renderCashJournalOpening(day) {
      const balances = Array.isArray(day?.opening_balances) ? day.opening_balances : [];
      if (!balances.length) return '';
      const totalText = String(day?.opening_total_display || '');
      return '<details class="cashbox-journal-opening">'
        + '<summary><span class="cashbox-journal-opening__title">Остатки на начало дня</span>' + (totalText ? ' · ' + escapeHtml(totalText) : '') + '</summary>'
        + '<div class="cashbox-journal-opening__grid">'
        + balances.map((item) => {
          const balanceMinor = finiteNumber(item?.balance_minor);
          const sign = String(item?.balance_sign || (balanceMinor < 0 ? 'negative' : 'positive'));
          const display = String(item?.balance_display || cashboxFormatMinorAmount(balanceMinor));
          return '<div class="cashbox-journal-balance">'
            + '<div class="cashbox-journal-balance__name">' + escapeHtml(item?.cashbox_name || 'Касса') + '</div>'
            + '<div class="cashbox-journal-balance__amount" data-balance-sign="' + escapeHtml(sign) + '">' + escapeHtml(display) + '</div>'
            + '</div>';
        }).join('')
        + '</div>'
        + '</details>';
    }

    function renderCashJournalEntry(item) {
      const direction = item?.direction === 'expense' ? 'expense' : 'income';
      const source = cashJournalVisibleSource(item?.source_label);
      const visualDirection = source === 'перемещение' ? 'transfer' : direction;
      const typeLabel = cashJournalDisplayTypeLabel(visualDirection);
      const note = cashJournalEntryNoteText(item);
      const amount = String(item?.signed_amount_display || ((direction === 'expense' ? '-' : '+') + cashboxFormatMinorAmount(item?.amount_minor ?? 0).replace(/^-/, '')));
      const actor = String(item?.actor_label || item?.actor_name || '').trim();
      const actorText = actor && actor !== 'СИСТЕМА' ? actor : '';
      const flags = cashJournalLinkFlags(item);
      const tags = source ? [source].concat(flags) : flags;
      const rowLabel = [item?.time_short || '--:--', item?.cashbox_name || 'Касса', typeLabel, note, amount, actorText].filter(Boolean).join('. ');
      return '<div class="cashbox-journal-operation-row" data-direction="' + escapeHtml(visualDirection) + '" role="listitem" aria-label="Операция кассы ' + escapeHtml(rowLabel) + '">'
        + '<div class="cashbox-journal-operation-row__time">' + escapeHtml(item?.time_short || '--:--') + '</div>'
        + '<div class="cashbox-journal-operation-row__cashbox">' + escapeHtml(item?.cashbox_name || 'Касса') + '</div>'
        + '<div class="cashbox-journal-operation-row__type">' + escapeHtml(typeLabel) + '</div>'
        + '<div class="cashbox-journal-operation-row__body">'
        + '<div class="cashbox-journal-operation-row__note" title="' + escapeHtml(note) + '">' + escapeHtml(note) + '</div>'
        + cashJournalOperationTagsHtml(tags)
        + '</div>'
        + '<div class="cashbox-journal-operation-row__actor">' + escapeHtml(actorText) + '</div>'
        + '<div class="cashbox-journal-operation-row__amount" data-direction="' + escapeHtml(visualDirection) + '">' + escapeHtml(amount) + '</div>'
        + '</div>';
    }

    function renderCashJournalTransferEntry(source, target) {
      const amount = cashboxFormatMinorAmount(source?.amount_minor ?? target?.amount_minor ?? 0);
      const note = cashJournalTransferNote(source) || cashJournalTransferNote(target);
      const actor = String(source?.actor_label || source?.actor_name || target?.actor_label || target?.actor_name || '').trim();
      const actorText = actor && actor !== 'СИСТЕМА' ? actor : '';
      const cashboxPath = String(source?.cashbox_name || 'Касса') + ' → ' + String(target?.cashbox_name || 'Касса');
      const rowLabel = [source?.time_short || target?.time_short || '--:--', cashboxPath, 'Перемещение', note, amount, actorText].filter(Boolean).join('. ');
      return '<div class="cashbox-journal-operation-row cashbox-journal-operation-row--transfer" data-direction="transfer" role="listitem" aria-label="Операция кассы ' + escapeHtml(rowLabel) + '">'
        + '<div class="cashbox-journal-operation-row__time">' + escapeHtml(source?.time_short || target?.time_short || '--:--') + '</div>'
        + '<div class="cashbox-journal-operation-row__cashbox">' + escapeHtml(cashboxPath) + '</div>'
        + '<div class="cashbox-journal-operation-row__type">' + escapeHtml(cashJournalDisplayTypeLabel('transfer')) + '</div>'
        + '<div class="cashbox-journal-operation-row__body">'
        + '<div class="cashbox-journal-operation-row__note" title="' + escapeHtml(note || 'Перемещение') + '">Перемещение</div>'
        + (note ? '<div class="cashbox-journal-operation-row__source">' + escapeHtml(note) + '</div>' : '')
        + '</div>'
        + '<div class="cashbox-journal-operation-row__actor">' + escapeHtml(actorText) + '</div>'
        + '<div class="cashbox-journal-operation-row__amount" data-direction="transfer">' + escapeHtml(amount) + '</div>'
        + '</div>';
    }

    function cashJournalOperationHeaderHtml() {
      return '<div class="cashbox-journal-operation-head" aria-hidden="true">'
        + '<span>Время</span>'
        + '<span>Касса</span>'
        + '<span>Тип</span>'
        + '<span>Операция</span>'
        + '<span>Оператор</span>'
        + '<span>Сумма</span>'
        + '</div>';
    }

    function renderCashJournalRow(row) {
      if (row?.kind === 'transfer') return renderCashJournalTransferEntry(row.source, row.target);
      return renderCashJournalEntry(row?.item || {});
    }

    function renderCashJournalDay(day) {
      const entries = Array.isArray(day?.entries) ? day.entries : [];
      const rows = cashJournalDisplayRows(entries);
      return '<section class="cashbox-journal-day">'
        + '<div class="cashbox-journal-day-divider">'
        + '<div class="cashbox-journal-day-divider__title">' + escapeHtml(day?.label || day?.date || 'День') + '</div>'
        + '<div class="cashbox-journal-day-divider__meta" data-cash-journal-compact-day="' + escapeHtml(day?.key || day?.date || '') + '">' + cashJournalDayCompactSummaryHtml(day || {}) + '</div>'
        + '</div>'
        + renderCashJournalDayDetails(day || {})
        + renderCashJournalOpening(day || {})
        + '<div class="cashbox-journal-entries">'
        + (rows.length ? rows.map(renderCashJournalRow).join('') : '<div class="cashbox-journal-empty">Операций за день нет.</div>')
        + '</div>'
        + '</section>';
    }

    function cashJournalCurrentTotalMinor(data) {
      const cashboxes = Array.isArray(data?.cashboxes) ? data.cashboxes : [];
      if (cashboxes.length) {
        return cashboxes.reduce((sum, cashbox) => sum + finiteNumber(cashbox?.statistics?.balance_minor), 0);
      }
      return finiteNumber(data?.totals?.balance_minor);
    }

    function renderCashJournalCurrentBalances(data) {
      const cashboxes = Array.isArray(data?.cashboxes) ? data.cashboxes : [];
      if (!cashboxes.length) return '<div class="cashbox-journal-empty">Текущие остатки касс не загружены.</div>';
      const hasNegative = cashboxes.some((cashbox) => finiteNumber(cashbox?.statistics?.balance_minor) < 0);
      const expanded = Boolean(state.cashboxJournalBalancesExpanded);
      const rows = cashboxes.map((cashbox) => {
        const balanceMinor = finiteNumber(cashbox?.statistics?.balance_minor);
        const sign = String(cashbox?.statistics?.balance_sign || (balanceMinor < 0 ? 'negative' : 'positive'));
        const display = String(cashbox?.statistics?.balance_display || cashboxFormatMinorAmount(balanceMinor));
        return '<div class="cashbox-journal-balance-chip" data-balance-sign="' + escapeHtml(sign) + '">'
          + '<span>' + escapeHtml(cashbox?.name || 'Касса') + '</span>'
          + '<strong>' + escapeHtml(display) + '</strong>'
          + '</div>';
      }).join('');
      const totalMinor = cashJournalCurrentTotalMinor(data);
      const totalSign = totalMinor < 0 ? 'negative' : 'positive';
      return '<div class="cashbox-journal-balance-strip' + (expanded ? ' is-expanded' : '') + '">'
        + '<div class="cashbox-journal-balance-strip__main">'
        + '<div class="cashbox-journal-balance-chip cashbox-journal-balance-chip--total" data-balance-sign="' + escapeHtml(totalSign) + '"><span>Итого</span><strong>' + escapeHtml(cashboxFormatMinorAmount(totalMinor)) + '</strong></div>'
        + '<button class="cashbox-journal-balance-toggle" type="button" data-cash-journal-toggle-balances aria-expanded="' + (expanded ? 'true' : 'false') + '" data-balance-warning="' + (hasNegative ? 'true' : 'false') + '">' + (expanded ? 'Скрыть кассы' : 'Кассы') + '</button>'
        + '</div>'
        + '<div class="cashbox-journal-balance-strip__items">' + rows + '</div>'
        + '</div>';
    }

    function cashJournalSelectOption(value, label, selectedValue) {
      const selected = String(value) === String(selectedValue) ? ' selected' : '';
      return '<option value="' + escapeHtml(value) + '"' + selected + '>' + escapeHtml(label) + '</option>';
    }

    function cashJournalPeriodButton(value, label, filters) {
      const isActive = !filters.periodKind && String(filters.period || 'all') === String(value);
      return '<button class="cashbox-journal-period-button' + (isActive ? ' is-active' : '') + '" type="button" data-cash-journal-period="' + escapeHtml(value) + '" aria-pressed="' + (isActive ? 'true' : 'false') + '">'
        + escapeHtml(label)
        + '</button>';
    }

    function cashJournalActiveFiltersHtml(data) {
      const filters = cashJournalFilters();
      const chips = [];
      const query = String(filters.query || '').trim();
      const cashboxes = Array.isArray(data?.cashboxes) ? data.cashboxes : [];
      const cashbox = cashboxes.find((item) => String(item?.id || '') === filters.cashbox);
      const typeLabels = { income: 'Поступления', expense: 'Списания', transfer: 'Перемещения' };
      const periodLabels = { today: 'Сегодня', '7': '7 дней', '30': '30 дней', all: '3 мес.' };
      if (query) chips.push({ key: 'query', label: 'Поиск: ' + query });
      if (filters.cashbox) chips.push({ key: 'cashbox', label: 'Касса: ' + String(cashbox?.name || 'касса') });
      if (filters.type !== 'all') chips.push({ key: 'type', label: 'Тип: ' + String(typeLabels[filters.type] || filters.type) });
      if (filters.periodKind && filters.periodKey) {
        chips.push({ key: 'period', label: 'Период: ' + String(filters.periodLabel || filters.periodKey) });
      } else if (filters.period !== 'all') {
        chips.push({ key: 'period', label: 'Период: ' + String(periodLabels[filters.period] || filters.period) });
      }
      return '<div class="cashbox-journal-active-filters" data-cash-journal-region="active-filters">'
        + chips.map((chip) => '<button class="cashbox-journal-active-filter" type="button" data-cash-journal-clear-filter="' + escapeHtml(chip.key) + '" title="Снять фильтр: ' + escapeHtml(chip.label) + '">' + escapeHtml(chip.label) + ' ×</button>').join('')
        + '</div>';
    }

    function renderCashJournalFilters(data) {
      const filters = cashJournalFilters();
      const cashboxes = Array.isArray(data?.cashboxes) ? data.cashboxes : [];
      const cashboxOptions = [cashJournalSelectOption('', 'Все кассы', filters.cashbox)]
        .concat(cashboxes.map((cashbox) => cashJournalSelectOption(cashbox?.id || '', cashbox?.name || 'Касса', filters.cashbox)))
        .join('');
      const resetHidden = cashJournalFiltersAreActive(filters) ? '' : ' hidden';
      const resetButton = '<button class="cashbox-journal-reset cashbox-journal-filter-reset" type="button" data-cash-journal-reset title="Сбросить фильтры" aria-label="Сбросить фильтры"' + resetHidden + '>Сбросить</button>';
      return '<div class="cashbox-journal-filters" data-cash-journal-region="filters">'
        + '<label class="cashbox-journal-filter"><span>Поиск</span><input type="search" data-cash-journal-filter="query" value="' + escapeHtml(filters.query) + '" placeholder="ЗН, сумма, комментарий"></label>'
        + '<label class="cashbox-journal-filter"><span>Касса</span><select data-cash-journal-filter="cashbox">' + cashboxOptions + '</select></label>'
        + '<label class="cashbox-journal-filter"><span>Тип</span><select data-cash-journal-filter="type">'
        + cashJournalSelectOption('all', 'Все', filters.type)
        + cashJournalSelectOption('income', 'Поступления', filters.type)
        + cashJournalSelectOption('expense', 'Списания', filters.type)
        + cashJournalSelectOption('transfer', 'Перемещения', filters.type)
        + '</select></label>'
        + '<label class="cashbox-journal-filter cashbox-journal-filter--period"><span>Период</span>'
        + '<div class="cashbox-journal-period-segments" role="group" aria-label="Быстрый период журнала">'
        + cashJournalPeriodButton('today', 'Сегодня', filters)
        + cashJournalPeriodButton('7', '7 дней', filters)
        + cashJournalPeriodButton('30', '30 дней', filters)
        + cashJournalPeriodButton('all', '3 мес.', filters)
        + '</div>'
        + '<select data-cash-journal-filter="period">'
        + cashJournalSelectOption('all', 'Все 3 мес.', filters.period)
        + cashJournalSelectOption('30', '30 дней', filters.period)
        + cashJournalSelectOption('7', '7 дней', filters.period)
        + cashJournalSelectOption('today', 'Сегодня', filters.period)
        + '</select></label>'
        + resetButton
        + '</div>';
    }

    function cashJournalFiltersAreActive(filters = cashJournalFilters()) {
      return Boolean(
        String(filters.query || '').trim()
          || String(filters.cashbox || '').trim()
          || String(filters.type || 'all') !== 'all'
          || String(filters.period || 'all') !== 'all'
          || (String(filters.periodKind || '').trim() && String(filters.periodKey || '').trim())
      );
    }

    function cashJournalOperationCountText(renderedRowCount, visibleRowCount, totalRowCount) {
      const rendered = finiteNonNegativeNumber(renderedRowCount);
      const visible = finiteNonNegativeNumber(visibleRowCount);
      const total = finiteNonNegativeNumber(totalRowCount);
      if (rendered < visible) {
        return String(rendered) + ' из ' + String(visible) + ' операций';
      }
      if (cashJournalFiltersAreActive()) {
        return String(visible) + ' из ' + String(total) + ' операций';
      }
      return String(total) + ' операций';
    }

    function renderCashJournalToolbar(data, renderedRowCount, visibleRowCount, totalRowCount) {
      const meta = data?.meta || {};
      const periodText = String(finiteNonNegativeNumber(meta?.months, 3)) + ' мес.';
      return '<div class="cashbox-journal-toolbar">'
        + '<div class="cashbox-journal-toolbar__status">' + escapeHtml(periodText + ' · ' + cashJournalOperationCountText(renderedRowCount, visibleRowCount, totalRowCount)) + '</div>'
        + '<div class="cashbox-journal-toolbar__total">Общий остаток<strong>' + escapeHtml(cashboxFormatMinorAmount(cashJournalCurrentTotalMinor(data))) + '</strong></div>'
        + '</div>';
    }

    function cashJournalStatsRowHtml(item, periodKind = '') {
      const balanceMinor = finiteNumber(item?.balance_minor);
      const transferMinor = Math.max(Math.abs(finiteNumber(item?.transfer_income_minor)), Math.abs(finiteNumber(item?.transfer_expense_minor)));
      const labelText = String(item?.label || item?.key || 'Период');
      const incomeText = String(item?.external_income_display || cashboxFormatMinorAmount(item?.external_income_minor ?? 0));
      const expenseText = String(item?.external_expense_display || cashboxFormatMinorAmount(item?.external_expense_minor ?? 0));
      const balanceText = String(item?.balance_display || cashboxFormatMinorAmount(balanceMinor));
      const transferText = cashJournalTransferSummaryText(transferMinor, item?.count ?? 0);
      const periodKey = String(item?.key || item?.date || item?.week_key || item?.month_key || '').trim();
      const ariaText = labelText + ': приход ' + incomeText + ', расход ' + expenseText + ', итог ' + balanceText + ', перемещения ' + transferText;
      return '<button class="cashbox-journal-stats-row" type="button" data-cash-journal-period-kind="' + escapeHtml(periodKind) + '" data-cash-journal-period-key="' + escapeHtml(periodKey) + '" data-cash-journal-period-label="' + escapeHtml(labelText) + '" aria-label="' + escapeHtml(ariaText) + '">'
        + '<div class="cashbox-journal-stats-row__label">' + escapeHtml(labelText) + '</div>'
        + '<div class="cashbox-journal-stats-row__value">' + escapeHtml(incomeText) + '</div>'
        + '<div class="cashbox-journal-stats-row__value" data-balance-sign="negative">' + escapeHtml(expenseText) + '</div>'
        + '<div class="cashbox-journal-stats-row__value" data-balance-sign="' + escapeHtml(balanceMinor < 0 ? 'negative' : 'positive') + '">' + escapeHtml(balanceText) + '</div>'
        + '<div class="cashbox-journal-stats-row__meta" title="' + escapeHtml(transferText) + '">' + escapeHtml(transferText) + '</div>'
        + '</button>';
    }

    function cashJournalStatsHeaderHtml() {
      return '<div class="cashbox-journal-stats-head" aria-hidden="true">'
        + '<span>Период</span>'
        + '<span>Приход</span>'
        + '<span>Расход</span>'
        + '<span>Итог</span>'
        + '<span>Перемещения</span>'
        + '</div>';
    }

    function renderCashJournalStatsSection(title, items, periodKind) {
      const hasRows = Array.isArray(items) && items.length;
      const rows = hasRows
        ? cashJournalStatsHeaderHtml() + items.map((item) => cashJournalStatsRowHtml(item, periodKind)).join('')
        : '<div class="cashbox-journal-empty">Данных пока нет.</div>';
      return '<section class="cashbox-journal-stats-section">'
        + '<div class="cashbox-journal-stats-section__head">' + escapeHtml(title) + '</div>'
        + '<div class="cashbox-journal-stats-table">' + rows + '</div>'
        + '</section>';
    }

    function renderCashJournalStats(data) {
      const totals = data?.totals || {};
      const meta = data?.meta || {};
      const shownText = String(totals?.count ?? meta?.returned ?? 0) + ' из ' + String(meta?.total ?? totals?.count ?? 0);
      const balanceMinor = finiteNumber(totals?.balance_minor);
      const transferMinor = Math.max(Math.abs(finiteNumber(totals?.transfer_income_minor)), Math.abs(finiteNumber(totals?.transfer_expense_minor)));
      const summaryHtml = '<div class="cashbox-journal-summary">'
        + cashJournalStatHtml('Период', 'последние ' + String(finiteNonNegativeNumber(meta?.months, 3)) + ' мес.')
        + cashJournalStatHtml('Операции', shownText)
        + cashJournalStatHtml('Поступления', String(totals?.external_income_display || cashboxFormatMinorAmount(totals?.external_income_minor ?? 0)))
        + cashJournalStatHtml('Списания', String(totals?.external_expense_display || cashboxFormatMinorAmount(totals?.external_expense_minor ?? 0)), 'negative')
        + cashJournalStatHtml('Итог периода', String(totals?.balance_display || cashboxFormatMinorAmount(balanceMinor)), balanceMinor < 0 ? 'negative' : 'positive')
        + cashJournalStatHtml('Перемещения', cashJournalTransferSummaryText(transferMinor, totals?.count ?? meta?.returned ?? 0))
        + '</div>';
      return '<div class="cashbox-journal-view cashbox-journal-view--stats">'
        + summaryHtml
        + renderCashJournalStatsSection('По месяцам', data?.months || [], 'month')
        + renderCashJournalStatsSection('По неделям', data?.weeks || [], 'week')
        + renderCashJournalStatsSection('По дням', data?.days || [], 'day')
        + '</div>';
    }

    function cashJournalVisibleRowLimit() {
      const limit = finiteNonNegativeNumber(state.cashboxJournalVisibleRowLimit);
      return Math.max(CASH_JOURNAL_RENDER_BATCH_SIZE, Number.isFinite(limit) ? limit : CASH_JOURNAL_RENDER_BATCH_SIZE);
    }

    function cashJournalRowsToEntries(rows) {
      const entries = [];
      const usedIds = new Set();
      (Array.isArray(rows) ? rows : []).forEach((row) => {
        cashJournalRowItems(row).forEach((item) => {
          const id = String(item?.id || '');
          if (id && usedIds.has(id)) return;
          if (id) usedIds.add(id);
          entries.push(item);
        });
      });
      return entries;
    }

    function renderCashJournalLoadMore(renderedRowCount, filteredRowCount) {
      if (renderedRowCount >= filteredRowCount) return '';
      return '<button class="cashbox-journal-load-more" type="button" data-cash-journal-load-more>'
        + escapeHtml(cashJournalLoadMoreText(renderedRowCount, filteredRowCount))
        + '</button>';
    }

    function cashJournalLoadMoreText(renderedRowCount, filteredRowCount) {
      const remaining = Math.max(0, finiteNonNegativeNumber(filteredRowCount) - finiteNonNegativeNumber(renderedRowCount));
      return 'Показать еще ' + String(Math.min(CASH_JOURNAL_RENDER_BATCH_SIZE, remaining));
    }

    function cashJournalLedgerParts(data) {
      const totalRowCount = cashJournalDisplayRows(cashJournalFlatEntries(data)).length;
      const filteredEntries = cashJournalFilteredEntries(data);
      const filteredRows = cashJournalDisplayRows(filteredEntries);
      const rowLimit = cashJournalVisibleRowLimit();
      const renderedRows = filteredRows.slice(0, rowLimit);
      const renderedEntries = cashJournalRowsToEntries(renderedRows);
      const days = cashJournalRebuildDays(data, renderedEntries);
      const meta = data?.meta || {};
      const visibleRowCount = filteredRows.length;
      const renderedRowCount = renderedRows.length;
      const limitNotice = finiteNonNegativeNumber(meta?.total) > finiteNonNegativeNumber(meta?.returned)
        ? '<div class="cashbox-journal-status-line">Показана часть операций. Для полной выгрузки увеличьте лимит журнала.</div>'
        : '';
      const renderNotice = renderedRowCount < visibleRowCount
        ? '<div class="cashbox-journal-status-line">Показаны первые ' + escapeHtml(String(renderedRowCount)) + ' из ' + escapeHtml(String(visibleRowCount)) + ' операций. Фильтры и сводка считаются по загруженному журналу.</div>'
        : '';
      const headerHtml = renderedRowCount ? cashJournalOperationHeaderHtml() : '';
      const daysHtml = days.length
        ? days.map(renderCashJournalDay).join('')
        : '<div class="cashbox-journal-empty">По выбранным фильтрам движений нет.</div>';
      const loadMoreHtml = renderCashJournalLoadMore(renderedRowCount, visibleRowCount);
      return {
        visibleRowCount,
        renderedRowCount,
        totalRowCount,
        bodyHtml: headerHtml + daysHtml + loadMoreHtml + renderNotice + limitNotice,
      };
    }

    function renderCashJournalLedger(data) {
      const parts = cashJournalLedgerParts(data);
      return '<div class="cashbox-journal-view">'
        + '<div class="cashbox-journal-sticky" data-cash-journal-region="chrome">'
        + '<div data-cash-journal-region="toolbar">' + renderCashJournalToolbar(data, parts.renderedRowCount, parts.visibleRowCount, parts.totalRowCount) + '</div>'
        + renderCashJournalFilters(data)
        + cashJournalActiveFiltersHtml(data)
        + renderCashJournalCurrentBalances(data)
        + '</div>'
        + '<div data-cash-journal-region="body">' + parts.bodyHtml + '</div>'
        + '</div>';
    }

    function renderCashJournal(data) {
      return state.cashboxJournalView === 'stats'
        ? renderCashJournalStats(data)
        : renderCashJournalLedger(data);
    }

    function refreshCashJournalView({ focusFilter = '', selectionStart = null, selectionEnd = null } = {}) {
      if (!state.cashboxJournalData) return;
      els.cashboxJournalText.innerHTML = renderCashJournal(state.cashboxJournalData);
      if (!focusFilter || state.cashboxJournalView === 'stats') return;
      const control = els.cashboxJournalText.querySelector('[data-cash-journal-filter="' + focusFilter + '"]');
      if (!(control instanceof HTMLElement)) return;
      control.focus();
      if (typeof control.setSelectionRange === 'function' && selectionStart !== null) {
        control.setSelectionRange(selectionStart, selectionEnd ?? selectionStart);
      }
    }

    function syncCashJournalFilterControls() {
      const filters = cashJournalFilters();
      const periodSelect = els.cashboxJournalText.querySelector('[data-cash-journal-filter="period"]');
      if (periodSelect instanceof HTMLSelectElement) periodSelect.value = filters.period;
      const resetButton = els.cashboxJournalText.querySelector('[data-cash-journal-reset]');
      if (resetButton instanceof HTMLElement) resetButton.hidden = !cashJournalFiltersAreActive(filters);
      els.cashboxJournalText.querySelectorAll('[data-cash-journal-period]').forEach((button) => {
        if (!(button instanceof HTMLElement)) return;
        const active = !filters.periodKind && String(button.dataset.cashJournalPeriod || '') === filters.period;
        button.classList.toggle('is-active', active);
        button.setAttribute('aria-pressed', active ? 'true' : 'false');
      });
    }

    function refreshCashJournalLedgerBody() {
      if (!state.cashboxJournalData || state.cashboxJournalView === 'stats') return false;
      const toolbarRegion = els.cashboxJournalText.querySelector('[data-cash-journal-region="toolbar"]');
      const activeFiltersRegion = els.cashboxJournalText.querySelector('[data-cash-journal-region="active-filters"]');
      const bodyRegion = els.cashboxJournalText.querySelector('[data-cash-journal-region="body"]');
      if (!(toolbarRegion instanceof HTMLElement) || !(bodyRegion instanceof HTMLElement)) {
        return false;
      }
      const parts = cashJournalLedgerParts(state.cashboxJournalData);
      toolbarRegion.innerHTML = renderCashJournalToolbar(
        state.cashboxJournalData,
        parts.renderedRowCount,
        parts.visibleRowCount,
        parts.totalRowCount
      );
      if (activeFiltersRegion instanceof HTMLElement) {
        activeFiltersRegion.outerHTML = cashJournalActiveFiltersHtml(state.cashboxJournalData);
      }
      bodyRegion.innerHTML = parts.bodyHtml;
      syncCashJournalFilterControls();
      return true;
    }

    function handleCashJournalFilterInput(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const control = target.closest('[data-cash-journal-filter]');
      if (!(control instanceof HTMLInputElement) && !(control instanceof HTMLSelectElement)) return;
      const name = String(control.dataset.cashJournalFilter || '');
      if (!name) return;
      const nextFilters = cashJournalFilters();
      nextFilters[name] = control.value;
      if (name === 'period') {
        nextFilters.periodKind = '';
        nextFilters.periodKey = '';
        nextFilters.periodLabel = '';
      }
      state.cashboxJournalFilters = nextFilters;
      state.cashboxJournalVisibleRowLimit = CASH_JOURNAL_RENDER_BATCH_SIZE;
      const refreshOptions = {
        focusFilter: name,
        selectionStart: typeof control.selectionStart === 'number' ? control.selectionStart : null,
        selectionEnd: typeof control.selectionEnd === 'number' ? control.selectionEnd : null,
      };
      if (state.cashboxJournalFilterTimer) {
        window.clearTimeout(state.cashboxJournalFilterTimer);
        state.cashboxJournalFilterTimer = null;
      }
      if (control instanceof HTMLInputElement) {
        state.cashboxJournalFilterTimer = window.setTimeout(() => {
          state.cashboxJournalFilterTimer = null;
          if (!refreshCashJournalLedgerBody()) refreshCashJournalView(refreshOptions);
        }, CASH_JOURNAL_FILTER_DEBOUNCE_MS);
        return;
      }
      if (!refreshCashJournalLedgerBody()) refreshCashJournalView(refreshOptions);
    }

    function handleCashJournalResetClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const clearButton = target.closest('[data-cash-journal-clear-filter]');
      if (clearButton instanceof HTMLElement) {
        event.preventDefault();
        const name = String(clearButton.dataset.cashJournalClearFilter || '');
        const nextFilters = cashJournalFilters();
        if (name === 'query') nextFilters.query = '';
        if (name === 'cashbox') nextFilters.cashbox = '';
        if (name === 'type') nextFilters.type = 'all';
        if (name === 'period') {
          nextFilters.period = 'all';
          nextFilters.periodKind = '';
          nextFilters.periodKey = '';
          nextFilters.periodLabel = '';
        }
        state.cashboxJournalFilters = nextFilters;
        state.cashboxJournalVisibleRowLimit = CASH_JOURNAL_RENDER_BATCH_SIZE;
        refreshCashJournalView();
        return;
      }
      const button = target.closest('[data-cash-journal-reset]');
      if (!(button instanceof HTMLElement)) return;
      event.preventDefault();
      if (state.cashboxJournalFilterTimer) {
        window.clearTimeout(state.cashboxJournalFilterTimer);
        state.cashboxJournalFilterTimer = null;
      }
      state.cashboxJournalFilters = cashJournalDefaultFilters();
      state.cashboxJournalVisibleRowLimit = CASH_JOURNAL_RENDER_BATCH_SIZE;
      refreshCashJournalView();
    }

    function handleCashJournalBalancesToggle(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const button = target.closest('[data-cash-journal-toggle-balances]');
      if (!(button instanceof HTMLElement)) return;
      event.preventDefault();
      state.cashboxJournalBalancesExpanded = !state.cashboxJournalBalancesExpanded;
      refreshCashJournalView();
    }

    function handleCashJournalPeriodClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const button = target.closest('[data-cash-journal-period]');
      if (!(button instanceof HTMLElement)) return;
      event.preventDefault();
      const period = String(button.dataset.cashJournalPeriod || 'all');
      const nextFilters = cashJournalFilters();
      nextFilters.period = ['today', '7', '30', 'all'].indexOf(period) >= 0 ? period : 'all';
      nextFilters.periodKind = '';
      nextFilters.periodKey = '';
      nextFilters.periodLabel = '';
      state.cashboxJournalFilters = nextFilters;
      state.cashboxJournalVisibleRowLimit = CASH_JOURNAL_RENDER_BATCH_SIZE;
      if (!refreshCashJournalLedgerBody()) refreshCashJournalView();
    }

    function applyCashJournalStatsPeriodFilter(periodKind, periodKey, periodLabel) {
      const nextFilters = cashJournalFilters();
      nextFilters.period = 'all';
      nextFilters.periodKind = String(periodKind || '');
      nextFilters.periodKey = String(periodKey || '');
      nextFilters.periodLabel = String(periodLabel || periodKey || '');
      state.cashboxJournalFilters = nextFilters;
      state.cashboxJournalVisibleRowLimit = CASH_JOURNAL_RENDER_BATCH_SIZE;
      setCashJournalView('journal');
    }

    function handleCashJournalStatsPeriodClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const button = target.closest('[data-cash-journal-period-kind][data-cash-journal-period-key]');
      if (!(button instanceof HTMLElement)) return;
      const periodKind = String(button.dataset.cashJournalPeriodKind || '');
      const periodKey = String(button.dataset.cashJournalPeriodKey || '');
      if (!periodKind || !periodKey) return;
      event.preventDefault();
      applyCashJournalStatsPeriodFilter(periodKind, periodKey, String(button.dataset.cashJournalPeriodLabel || periodKey));
    }

    function handleCashJournalLoadMoreClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const button = target.closest('[data-cash-journal-load-more]');
      if (!(button instanceof HTMLElement)) return;
      event.preventDefault();
      state.cashboxJournalVisibleRowLimit = cashJournalVisibleRowLimit() + CASH_JOURNAL_RENDER_BATCH_SIZE;
      if (!refreshCashJournalLedgerBody()) refreshCashJournalView();
    }

    function syncCashJournalModeButtons() {
      const statsOpen = state.cashboxJournalView === 'stats';
      if (els.cashboxJournalLedgerButton) {
        els.cashboxJournalLedgerButton.classList.toggle('is-active', !statsOpen);
        els.cashboxJournalLedgerButton.setAttribute('aria-pressed', statsOpen ? 'false' : 'true');
      }
      if (els.cashboxJournalStatsButton) {
        els.cashboxJournalStatsButton.classList.toggle('is-active', statsOpen);
        els.cashboxJournalStatsButton.setAttribute('aria-pressed', statsOpen ? 'true' : 'false');
      }
    }

    function setCashJournalView(view) {
      state.cashboxJournalView = view === 'stats' ? 'stats' : 'journal';
      syncCashJournalModeButtons();
      refreshCashJournalView();
    }

    function handleCashJournalModeClick(event) {
      const target = event.currentTarget;
      if (!(target instanceof HTMLElement)) return;
      setCashJournalView(String(target.dataset.cashJournalView || 'journal'));
    }

    function handleCashJournalModeKeydown(event) {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      event.currentTarget?.click?.();
    }

    async function openCashJournalModal() {
      state.cashboxJournalFilters = cashJournalDefaultFilters();
      state.cashboxJournalVisibleRowLimit = CASH_JOURNAL_RENDER_BATCH_SIZE;
      state.cashboxJournalBalancesExpanded = false;
      syncCashJournalModeButtons();
      els.cashboxJournalText.innerHTML = renderCashJournalLoading();
      maybeOpenModal(els.cashboxJournalModal, true);
      try {
        const data = await loadCashJournalData();
        state.cashboxJournalData = data;
        els.cashboxJournalText.innerHTML = renderCashJournal(data);
      } catch (error) {
        els.cashboxJournalText.innerHTML = '<div class="cashbox-journal-empty">' + escapeHtml(String(error?.message || 'НЕ УДАЛОСЬ ЗАГРУЗИТЬ ЖУРНАЛ.')) + '</div>';
        setStatus(String(error?.message || 'НЕ УДАЛОСЬ ЗАГРУЗИТЬ ЖУРНАЛ.'), true);
      }
    }

    function closeCashJournalModal() {
      popModal('cashbox-journal');
    }

    function closeCashboxTransferModal() {
      popModal('cashbox-transfer');
      state.cashboxTransferDraft = {
        sourceId: '',
        targetId: '',
        amount: '',
        note: '',
      };
      if (els.cashboxTransferAmountInput) els.cashboxTransferAmountInput.value = '';
      if (els.cashboxTransferNoteInput) els.cashboxTransferNoteInput.value = '';
    }

    async function downloadCashJournal() {
      try {
        const data = await loadCashJournalData({ includeMarkdown: true });
        const text = String(data?.markdown || data?.text || 'ЗА ВЫБРАННЫЙ ПЕРИОД ДВИЖЕНИЙ НЕТ.');
        const blob = new Blob([text.trim() + '\n'], { type: 'text/markdown;charset=utf-8' });
        const fileName = 'cash-journal-' + new Date().toISOString().slice(0, 10) + '.md';
        triggerBlobDownload(blob, fileName);
        setStatus('ЖУРНАЛ СКАЧАН.', false);
      } catch (error) {
        setStatus(String(error?.message || 'НЕ УДАЛОСЬ СКАЧАТЬ ЖУРНАЛ.'), true);
      }
    }

    async function reorderCashboxes(cashboxId, beforeCashboxId = '') {
      const normalizedId = String(cashboxId || '').trim();
      if (!normalizedId) return;
      const normalizedBeforeId = String(beforeCashboxId || '').trim();
      try {
        const data = await api('/api/reorder_cashboxes', {
          method: 'POST',
          body: {
            cashbox_id: normalizedId,
            before_cashbox_id: normalizedBeforeId || null,
            actor_name: state.actor,
            source: 'ui',
          },
        });
        if (Array.isArray(data?.cashboxes)) {
          state.cashboxes = data.cashboxes;
        } else {
          await loadCashboxes(false);
        }
        if (data?.cashbox?.id && state.activeCashbox?.cashbox?.id === data.cashbox.id) {
          state.activeCashbox.cashbox = data.cashbox;
          state.activeCashbox.statistics = data.cashbox.statistics || state.activeCashbox.statistics || {};
        } else if (state.activeCashbox?.cashbox?.id) {
          const activeCashbox = (Array.isArray(state.cashboxes) ? state.cashboxes : []).find((item) => item.id === state.activeCashbox.cashbox.id);
          if (activeCashbox) {
            state.activeCashbox.cashbox = activeCashbox;
            state.activeCashbox.statistics = activeCashbox.statistics || state.activeCashbox.statistics || {};
          }
        }
        renderCashboxesList();
        renderCashboxDetail();
        setStatus('ПОРЯДОК КАСС ИЗМЕНЕН.', false);
      } catch (error) {
        setStatus(String(error?.message || 'НЕ УДАЛОСЬ ИЗМЕНИТЬ ПОРЯДОК КАСС.'), true);
      } finally {
        resetCashboxDragState();
        state.cashboxDragIgnoreClicksUntil = Date.now() + 250;
        renderCashboxesList();
      }
    }

    async function createCashboxTransfer() {
      const sourceCashbox = state.activeCashbox?.cashbox || null;
      if (!sourceCashbox?.id) {
        setStatus('СНАЧАЛА ВЫБЕРИТЕ КАССУ.', true);
        return;
      }
      const availableCashboxes = (Array.isArray(state.cashboxes) ? state.cashboxes : []).filter((item) => item.id !== sourceCashbox.id);
      if (!availableCashboxes.length) {
        setStatus('НЕТ ДРУГОЙ КАССЫ ДЛЯ ПЕРЕМЕЩЕНИЯ.', true);
        return;
      }
      state.cashboxTransferDraft = {
        sourceId: sourceCashbox.id,
        targetId: availableCashboxes[0]?.id || '',
        amount: '',
        note: '',
      };
      if (els.cashboxTransferAmountInput) els.cashboxTransferAmountInput.value = '';
      if (els.cashboxTransferNoteInput) els.cashboxTransferNoteInput.value = '';
      renderCashboxTransferModal();
      maybeOpenModal(els.cashboxTransferModal, true);
    }

    function cashboxTransferAmountMinor() {
      const parsed = repairOrderParseNumber(els.cashboxTransferAmountInput?.value ?? state.cashboxTransferDraft?.amount ?? '');
      if (parsed === null || parsed <= 0) return null;
      return Math.round(parsed * 100);
    }

    function renderCashboxTransferBalanceRow(label, amountMinor) {
      const sign = cashboxBalanceSign(amountMinor);
      return '<div class="cashbox-transfer-preview__row">'
        + '<span>' + escapeHtml(label) + '</span>'
        + '<strong class="cashbox-transfer-preview__amount" data-balance-sign="' + escapeHtml(sign) + '">' + escapeHtml(cashboxFormatMinorAmount(amountMinor)) + '</strong>'
        + '</div>';
    }

    function renderCashboxTransferPreview(sourceCashbox, targetCashbox) {
      if (!els.cashboxTransferPreview) return;
      const amountMinor = cashboxTransferAmountMinor();
      if (!sourceCashbox?.id || !targetCashbox?.id) {
        els.cashboxTransferPreview.innerHTML = '<div class="cashbox-transfer-preview__label">Выберите кассу для перемещения.</div>';
        return;
      }
      if (amountMinor === null) {
        els.cashboxTransferPreview.innerHTML = '<div class="cashbox-transfer-preview__label">Введите сумму, чтобы увидеть баланс до и после.</div>';
        return;
      }
      const sourceBefore = cashboxBalanceMinor(sourceCashbox);
      const targetBefore = cashboxBalanceMinor(targetCashbox);
      const sourceAfter = sourceBefore - amountMinor;
      const targetAfter = targetBefore + amountMinor;
      els.cashboxTransferPreview.innerHTML = '<div class="cashbox-transfer-preview__label">'
        + escapeHtml(String(sourceCashbox.name || 'Касса') + ' → ' + String(targetCashbox.name || 'Касса'))
        + '</div>'
        + '<div class="cashbox-transfer-preview__rows">'
        + renderCashboxTransferBalanceRow('Откуда сейчас', sourceBefore)
        + renderCashboxTransferBalanceRow('Откуда после', sourceAfter)
        + renderCashboxTransferBalanceRow('Куда сейчас', targetBefore)
        + renderCashboxTransferBalanceRow('Куда после', targetAfter)
        + '</div>';
    }

    function renderCashboxTransferModal() {
      const sourceId = String(state.cashboxTransferDraft?.sourceId || state.activeCashbox?.cashbox?.id || '').trim();
      const sourceCashbox = (Array.isArray(state.cashboxes) ? state.cashboxes : []).find((item) => item.id === sourceId) || state.activeCashbox?.cashbox || null;
      const availableCashboxes = (Array.isArray(state.cashboxes) ? state.cashboxes : []).filter((item) => item.id !== sourceId);
      els.cashboxTransferSourceName.textContent = sourceCashbox?.name || 'КАССА НЕ ВЫБРАНА';
      if (els.cashboxTransferSourceBalance) {
        els.cashboxTransferSourceBalance.textContent = sourceCashbox ? ('Баланс: ' + cashboxBalanceDisplay(sourceCashbox)) : '';
      }
      els.cashboxTransferTargets.innerHTML = availableCashboxes.length ? availableCashboxes.map((item) => {
        const activeClass = item.id === state.cashboxTransferDraft.targetId ? ' is-active' : '';
        return '<button class="cashbox-transfer-target' + activeClass + '" type="button" data-cashbox-transfer-target="' + escapeHtml(item.id) + '">'
          + '<div class="cashbox-transfer-target__name">' + escapeHtml(item.name || '—') + '</div>'
          + '<div class="cashbox-transfer-target__balance">' + escapeHtml(cashboxBalanceDisplay(item)) + '</div>'
          + '</button>';
      }).join('') : '<div class="cashboxes-empty">НЕТ ДРУГИХ КАСС.</div>';
      const selectedTarget = availableCashboxes.find((item) => item.id === state.cashboxTransferDraft.targetId) || availableCashboxes[0] || null;
      if (selectedTarget && selectedTarget.id !== state.cashboxTransferDraft.targetId) {
        state.cashboxTransferDraft.targetId = selectedTarget.id;
      }
      if (els.cashboxTransferConfirmButton) {
        const hasAmount = cashboxTransferAmountMinor() !== null;
        els.cashboxTransferConfirmButton.disabled = !selectedTarget || !sourceCashbox || !hasAmount;
      }
      renderCashboxTransferPreview(sourceCashbox, selectedTarget);
    }

    function setCashboxTransferTarget(cashboxId) {
      const requestedId = String(cashboxId || '').trim();
      const sourceId = String(state.cashboxTransferDraft?.sourceId || '').trim();
      if (!requestedId || requestedId === sourceId) return;
      state.cashboxTransferDraft.targetId = requestedId;
      renderCashboxTransferModal();
    }

    async function submitCashboxTransfer() {
      const sourceCashbox = (Array.isArray(state.cashboxes) ? state.cashboxes : []).find((item) => item.id === state.cashboxTransferDraft.sourceId) || null;
      const targetCashbox = (Array.isArray(state.cashboxes) ? state.cashboxes : []).find((item) => item.id === state.cashboxTransferDraft.targetId) || null;
      if (!sourceCashbox?.id) {
        setStatus('СНАЧАЛА ВЫБЕРИТЕ КАССУ.', true);
        return;
      }
      if (!targetCashbox?.id || targetCashbox.id === sourceCashbox.id) {
        setStatus('УКАЖИТЕ КАССУ ДЛЯ ПЕРЕМЕЩЕНИЯ.', true);
        return;
      }
      const amount = String(els.cashboxTransferAmountInput?.value || '').trim();
      if (!amount) {
        setStatus('УКАЖИТЕ СУММУ.', true);
        return;
      }
      try {
        els.cashboxTransferConfirmButton.disabled = true;
        els.cashboxTransferButton.disabled = true;
        await api('/api/create_cashbox_transfer', {
          method: 'POST',
          body: {
            from_cashbox_id: sourceCashbox.id,
            to_cashbox_id: targetCashbox.id,
            amount,
            note: String(els.cashboxTransferNoteInput?.value || '').trim(),
            actor_name: state.actor,
            source: 'ui',
          },
        });
        if (els.cashboxTransferAmountInput) els.cashboxTransferAmountInput.value = '';
        if (els.cashboxTransferNoteInput) els.cashboxTransferNoteInput.value = '';
        closeCashboxTransferModal();
        await refreshCashboxesAfterMoneyMutation({ openModal: true, deferDetail: false });
        setStatus('ПЕРЕМЕЩЕНИЕ СОХРАНЕНО.', false);
      } catch (error) {
        setStatus(error.message, true);
      } finally {
        els.cashboxTransferConfirmButton.disabled = false;
        els.cashboxTransferButton.disabled = false;
      }
    }

    function handleCashboxTransferAmountInput() {
      state.cashboxTransferDraft.amount = String(els.cashboxTransferAmountInput?.value || '').trim();
      renderCashboxTransferModal();
    }

    function handleCashboxTransferNoteInput() {
      state.cashboxTransferDraft.note = String(els.cashboxTransferNoteInput?.value || '');
    }

    function handleCashboxTransferTargetsClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const button = target.closest('[data-cashbox-transfer-target]');
      if (!button) return;
      setCashboxTransferTarget(button.getAttribute('data-cashbox-transfer-target'));
    }

    function setCashboxNoteInvalid(isInvalid) {
      if (!els.cashboxNoteInput) return;
      els.cashboxNoteInput.classList.toggle('is-invalid', Boolean(isInvalid));
      if (isInvalid) els.cashboxNoteInput.setAttribute('aria-invalid', 'true');
      else els.cashboxNoteInput.removeAttribute('aria-invalid');
    }

    function cashboxExpenseNoteIsValid(note) {
      return String(note || '').trim().length >= CASHBOX_EXPENSE_NOTE_MIN_LENGTH;
    }

    function handleCashboxNoteInput() {
      if (cashboxExpenseNoteIsValid(els.cashboxNoteInput?.value || '')) {
        setCashboxNoteInvalid(false);
      }
    }

    async function createCashboxTransaction(direction) {
      const cashbox = state.activeCashbox?.cashbox || null;
      if (!cashbox?.id) {
        setStatus('СНАЧАЛА ВЫБЕРИТЕ КАССУ.', true);
        return;
      }
      const amount = String(els.cashboxAmountInput.value || '').trim();
      if (!amount) {
        setStatus('УКАЖИТЕ СУММУ.', true);
        return;
      }
      const normalizedDirection = direction === 'expense' ? 'expense' : 'income';
      const note = String(els.cashboxNoteInput.value || '').trim();
      if (normalizedDirection === 'expense' && !cashboxExpenseNoteIsValid(note)) {
        setCashboxNoteInvalid(true);
        els.cashboxNoteInput.focus();
        setStatus('ДЛЯ СПИСАНИЯ УКАЖИТЕ КОММЕНТАРИЙ НЕ КОРОЧЕ 10 СИМВОЛОВ.', true);
        return;
      }
      setCashboxNoteInvalid(false);
      try {
        els.cashboxIncomeButton.disabled = true;
        els.cashboxExpenseButton.disabled = true;
        await api('/api/create_cash_transaction', {
          method: 'POST',
          body: {
            cashbox_id: cashbox.id,
            direction: normalizedDirection,
            amount,
            note,
            actor_name: state.actor,
            source: 'ui',
          },
        });
        els.cashboxAmountInput.value = '';
        els.cashboxNoteInput.value = '';
        await refreshCashboxesAfterMoneyMutation({ openModal: true, deferDetail: false });
        setStatus(direction === 'expense' ? 'СПИСАНИЕ СОХРАНЕНО.' : 'ПОСТУПЛЕНИЕ СОХРАНЕНО.', false);
      } catch (error) {
        setStatus(error.message, true);
      } finally {
        els.cashboxIncomeButton.disabled = false;
        els.cashboxExpenseButton.disabled = false;
      }
    }

    function setCashboxCancelReasonInvalid(isInvalid) {
      if (!els.cashboxCancelReasonInput) return;
      els.cashboxCancelReasonInput.classList.toggle('is-invalid', Boolean(isInvalid));
      if (isInvalid) els.cashboxCancelReasonInput.setAttribute('aria-invalid', 'true');
      else els.cashboxCancelReasonInput.removeAttribute('aria-invalid');
    }

    function closeCashboxCancelPopover() {
      state.cashboxCancelTransactionId = '';
      if (els.cashboxCancelPopover) els.cashboxCancelPopover.hidden = true;
      if (els.cashboxCancelReasonInput) {
        els.cashboxCancelReasonInput.value = '';
        setCashboxCancelReasonInvalid(false);
      }
      if (els.cashboxCancelConfirmButton) els.cashboxCancelConfirmButton.disabled = false;
    }

    function openCashboxCancelPopover(transactionId) {
      const transaction = cashboxTransactionById(transactionId);
      if (!transaction || !cashboxTransactionCanBeCancelled(transaction)) {
        setStatus('ЭТУ ОПЕРАЦИЮ НЕЛЬЗЯ ОТМЕНИТЬ.', true);
        return;
      }
      state.cashboxCancelTransactionId = String(transaction.id || '').trim();
      const amount = cashboxFormatMinorAmount(transaction.amount_minor ?? 0).replace(/^-/, '');
      const note = String(transaction.note || '').trim() || 'Без комментария';
      if (els.cashboxCancelMeta) {
        els.cashboxCancelMeta.textContent = note + ' · ' + amount;
      }
      if (els.cashboxCancelReasonInput) {
        els.cashboxCancelReasonInput.value = '';
        setCashboxCancelReasonInvalid(false);
      }
      if (els.cashboxCancelPopover) els.cashboxCancelPopover.hidden = false;
      window.setTimeout(() => {
        els.cashboxCancelReasonInput?.focus();
      }, 0);
    }

    async function submitCashboxTransactionCancellation() {
      const cashbox = state.activeCashbox?.cashbox || null;
      const transaction = cashboxTransactionById(state.cashboxCancelTransactionId);
      if (!cashbox?.id || !transaction?.id) {
        setStatus('ВЫБЕРИТЕ ОПЕРАЦИЮ ДЛЯ ОТМЕНЫ.', true);
        return;
      }
      const reason = String(els.cashboxCancelReasonInput?.value || '').trim();
      if (reason.length < CASHBOX_CANCEL_REASON_MIN_LENGTH) {
        setCashboxCancelReasonInvalid(true);
        els.cashboxCancelReasonInput?.focus();
        setStatus('ПРИЧИНА ОТМЕНЫ ДОЛЖНА БЫТЬ НЕ КОРОЧЕ 10 СИМВОЛОВ.', true);
        return;
      }
      try {
        if (els.cashboxCancelConfirmButton) els.cashboxCancelConfirmButton.disabled = true;
        await api('/api/cancel_cash_transaction', {
          method: 'POST',
          body: {
            cashbox_id: cashbox.id,
            transaction_id: transaction.id,
            reason,
            actor_name: state.actor,
            source: 'ui',
          },
        });
        closeCashboxCancelPopover();
        await refreshCashboxesAfterMoneyMutation({ openModal: true, deferDetail: false });
        setStatus('ОПЕРАЦИЯ ОТМЕНЕНА.', false);
      } catch (error) {
        setStatus(String(error?.message || 'НЕ УДАЛОСЬ ОТМЕНИТЬ ОПЕРАЦИЮ.'), true);
      } finally {
        if (els.cashboxCancelConfirmButton) els.cashboxCancelConfirmButton.disabled = false;
      }
    }

    async function handleCashboxesListClick(event) {
      if (Date.now() < finiteNonNegativeNumber(state.cashboxDragIgnoreClicksUntil)) return;
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const row = target.closest('[data-cashbox-id]');
      if (!row) return;
      await loadCashboxDetail(row.dataset.cashboxId, { openModal: true });
    }

    async function handleCashboxesListKeydown(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const row = target.closest('[data-cashbox-id]');
      if (!row) return;
      if (event.key !== 'Enter' && event.key !== ' ') return;
      event.preventDefault();
      await loadCashboxDetail(row.dataset.cashboxId, { openModal: true });
    }

    async function handleCashboxTransactionsClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const cancelButton = target.closest('[data-cashbox-transaction-cancel]');
      if (cancelButton instanceof HTMLButtonElement) {
        event.preventDefault();
        openCashboxCancelPopover(cancelButton.getAttribute('data-cashbox-transaction-cancel'));
        return;
      }
      const button = target.closest('[data-cashbox-transactions-load-more]');
      if (!(button instanceof HTMLButtonElement)) return;
      event.preventDefault();
      button.disabled = true;
      try {
        await loadMoreCashboxTransactions();
      } finally {
        button.disabled = false;
      }
    }

    function handleCashboxesListDragStart(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const row = target.closest('[data-cashbox-id]');
      if (!row) return;
      const cashboxId = String(row.dataset.cashboxId || '').trim();
      if (!cashboxId) return;
      state.cashboxDragId = cashboxId;
      state.cashboxDragIgnoreClicksUntil = 0;
      state.cashboxDropBeforeId = '';
      syncCashboxDragClasses();
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
        event.dataTransfer.setData('text/plain', cashboxId);
      }
    }

    function handleCashboxesListDragOver(event) {
      if (!state.cashboxDragId) return;
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const row = target.closest('[data-cashbox-id]');
      event.preventDefault();
      if (!row) {
        if ((Array.isArray(state.cashboxes) ? state.cashboxes.length : 0) > 0) {
          setCashboxDropBeforeId('__end__');
        }
        return;
      }
      const beforeId = cashboxDropBeforeIdFromRow(row, event.clientY);
      if (!beforeId) return;
      setCashboxDropBeforeId(beforeId);
    }

    async function handleCashboxesListDrop(event) {
      if (!state.cashboxDragId) return;
      event.preventDefault();
      const draggedId = String(state.cashboxDragId || '').trim();
      const beforeId = state.cashboxDropBeforeId === '__end__' ? '' : String(state.cashboxDropBeforeId || '').trim();
      if (!draggedId || draggedId === beforeId) {
        resetCashboxDragState();
        renderCashboxesList();
        return;
      }
      await reorderCashboxes(draggedId, beforeId);
    }

    function handleCashboxesListDragEnd() {
      resetCashboxDragState();
      state.cashboxDragIgnoreClicksUntil = Date.now() + 250;
      renderCashboxesList();
    }

    function refreshGptWallView() {
      loadGptWall(false);
    }

    async function archiveActiveCard() {
      if (!state.editingId) return;
      try {
        const data = await api('/api/archive_card', { method: 'POST', body: { card_id: state.editingId, actor_name: state.actor, source: 'ui' } });
        closeCardModal({ force: true });
        if (data?.card && applyArchivedCardPatch(data.card)) return;
        await refreshSnapshot(true);
      } catch (error) {
        const message = String(error?.message || '').trim();
        setStatus(archiveBlockedMessage(message), true);
      }
    }

    function archiveBlockedMessage(message) {
      const text = String(message || '').trim();
      if (text.includes('открыт заказ-наряд')) {
        return text + ' Закройте заказ-наряд или измените статус перед архивированием.';
      }
      return text || 'НЕ УДАЛОСЬ АРХИВИРОВАТЬ КАРТОЧКУ.';
    }

    async function restoreActiveCard() {
      if (!state.editingId) return;
      await restoreCard(state.editingId);
      closeCardModal({ force: true });
    }

    function openStickyModal(sticky = null) {
      const existing = sticky || null;
      state.stickyDraft = existing;
      els.stickyModalTitle.textContent = existing ? ('СТИКЕР / ' + String(existing.id).slice(0, 8).toUpperCase()) : 'НОВЫЙ СТИКЕР';
      els.stickyText.value = existing?.text || '';
      const parts = secondsToParts(existing?.deadline_total_seconds ?? 4 * 3600);
      els.stickyDays.value = parts.days ?? 0;
      els.stickyHours.value = parts.hours ?? 4;
      pushModal('sticky', els.stickyModal);
      setTimeout(() => els.stickyText.focus(), 0);
    }

    function closeStickyModal() {
      popModal('sticky');
      state.stickyDraft = null;
    }

    function handleStickyModalOverlayClick(event) {
      return;
    }

    function handleRepairOrderModalOverlayClick(event) {
      return;
    }

    function handleRepairOrderPaymentsModalOverlayClick(event) {
      return;
    }

    function handleAgentModalOverlayClick(event) {
      return;
    }

    function handleEmployeesModalOverlayClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      if (target === els.employeeShiftAccrualButton) {
        openEmployeeShiftAccrualDialog();
        return;
      }
      if (target === els.employeeShiftAccrualCancelButton) {
        closeEmployeeShiftAccrualDialog();
        return;
      }
      if (target === els.employeeShiftAccrualConfirmButton) {
        handleEmployeeShiftAccrualConfirm();
        return;
      }
      const addButton = target.closest('[data-employee-incentive-add]');
      if (addButton instanceof HTMLElement) {
        const kind = String(addButton.dataset.employeeIncentiveAdd || '').trim();
        setEmployeeIncentiveActive(kind, true);
        return;
      }
      const removeButton = target.closest('[data-employee-incentive-remove]');
      if (removeButton instanceof HTMLElement) {
        if (removeButton.hasAttribute('disabled')) return;
        const kind = String(removeButton.dataset.employeeIncentiveRemove || '').trim();
        setEmployeeIncentiveActive(kind, false);
      }
    }

    function handleAgentQuickActionClick(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const openButton = target.closest('[data-agent-open]');
      if (openButton instanceof HTMLElement) {
        if (String(openButton.dataset.agentOpen || '').trim() === 'tasks') openAgentTasksModal();
        return;
      }
      const button = target.closest('[data-agent-prompt]');
      if (!(button instanceof HTMLElement)) return;
      const prompt = String(button.dataset.agentPrompt || '').trim();
      const template = String(button.dataset.agentTemplate || '').trim();
      if (!prompt || !els.agentTaskInput) return;
      els.agentTaskInput.value = prompt;
      if (template) {
        els.agentTaskInput.dataset.agentPromptTemplate = template;
      } else {
        delete els.agentTaskInput.dataset.agentPromptTemplate;
      }
      syncAgentTaskInputHeight();
      els.agentTaskInput.focus();
    }

    function handleAgentRunSelection(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const row = target.closest('[data-agent-task-id]');
      if (!(row instanceof HTMLElement)) return;
      const taskId = String(row.dataset.agentTaskId || '').trim();
      if (!taskId) return;
      state.agentTaskId = taskId;
      refreshAgentModalState();
    }

    function handleOperatorProfileModalOverlayClick(event) {
      return;
    }

    function handleOperatorAdminModalOverlayClick(event) {
      return;
    }

    function buildStickyPayload() {
      const draft = stickyPayload();
      const deadline = stickyDeadlineInput();
      const placement = state.stickyDraft?.id ? null : getStickyComposerPlacement();
      return {
        sticky_id: state.stickyDraft?.id || null,
        text: draft.text,
        deadline,
        x: state.stickyDraft?.x ?? placement?.x ?? 0,
        y: state.stickyDraft?.y ?? placement?.y ?? 0,
      };
    }

    async function saveSticky() {
      const payload = buildStickyPayload();
      if (!payload.text) return setStatus('УКАЖИ ТЕКСТ СТИКЕРА.', true);
      try {
        let data = null;
        if (payload.sticky_id) {
          data = await api('/api/update_sticky', { method: 'POST', body: { sticky_id: payload.sticky_id, text: payload.text, deadline: payload.deadline, actor_name: state.actor, source: 'ui' } });
        } else {
          data = await api('/api/create_sticky', { method: 'POST', body: { text: payload.text, x: payload.x, y: payload.y, deadline: payload.deadline, actor_name: state.actor, source: 'ui' } });
        }
        closeStickyModal();
        if (applyStickySnapshot(data?.stickies || [])) {
          setStatus('СТИКЕР СОХРАНЕН.', false);
          return;
        }
        await refreshSnapshot(true);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function removeSticky(stickyId) {
      try {
        const data = await api('/api/delete_sticky', { method: 'POST', body: { sticky_id: stickyId, actor_name: state.actor, source: 'ui' } });
        if (applyStickySnapshot(data?.stickies || [])) {
          setStatus('СТИКЕР УДАЛЕН.', false);
          return;
        }
        await refreshSnapshot(true);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function saveBoardScale() {
      const scale = normalizeBoardScale(finiteNumber(els.boardScaleInput.value, 100) / 100);
      applyBoardScale(scale, { syncInput: true });
      persistStoredBoardScale(scale);
      const aiBoardControl = readBoardControlSettingsForm();
      const body = {
        board_scale: scale,
        actor_name: state.actor,
        source: 'ui',
      };
      if (aiBoardControl) body.ai_board_control = aiBoardControl;
      const data = await api('/api/update_board_settings', {
        method: 'POST',
        body,
      });
      if (data?.settings && typeof data.settings === 'object') {
        state.snapshot = state.snapshot && typeof state.snapshot === 'object' ? state.snapshot : {};
        state.snapshot.settings = data.settings;
      }
    }

    async function persistBoardScaleChange() {
      await saveBoardScale();
    }

    function beginStickyDrag(event) {
      if (event.button !== 0) return;
      if (!(event.target instanceof HTMLElement)) return;
      const sticky = event.target.closest('.sticky');
      if (!sticky || event.target.closest('.sticky__close')) return;
      const stickyId = sticky.dataset.stickyId;
      const current = (state.snapshot?.stickies || []).find((item) => item.id === stickyId);
      if (!current) return;
      state.stickyDrag = {
        active: true,
        pointerId: event.pointerId,
        stickyId,
        startX: finiteNonNegativeNumber(current.x),
        startY: finiteNonNegativeNumber(current.y),
        startClientX: event.clientX,
        startClientY: event.clientY,
        moved: false,
      };
      sticky.classList.add('is-dragging');
      event.preventDefault();
    }

    function moveStickyDrag(event) {
      const drag = state.stickyDrag;
      if (!drag.active || drag.pointerId !== event.pointerId) return;
      const scale = normalizeBoardScale(state.boardScale);
      const dx = event.clientX - drag.startClientX;
      const dy = event.clientY - drag.startClientY;
      if (!drag.moved && Math.abs(dx) + Math.abs(dy) > 4) drag.moved = true;
      if (!drag.moved) return;
      const nextX = Math.max(0, Math.round(drag.startX + (dx / scale)));
      const nextY = Math.max(0, Math.round(drag.startY + (dy / scale)));
      const sticky = document.querySelector('.sticky[data-sticky-id="' + CSS.escape(drag.stickyId) + '"]');
      if (sticky) {
        sticky.style.left = stickyRenderPosition(nextX, scale) + 'px';
        sticky.style.top = stickyRenderPosition(nextY, scale) + 'px';
      }
      event.preventDefault();
    }

    async function endStickyDrag(event) {
      const drag = state.stickyDrag;
      if (!drag.active || drag.pointerId !== event.pointerId) return;
      const sticky = document.querySelector('.sticky[data-sticky-id="' + CSS.escape(drag.stickyId) + '"]');
      if (sticky) sticky.classList.remove('is-dragging');
      state.stickyDrag = {
        active: false,
        pointerId: null,
        stickyId: null,
        startX: 0,
        startY: 0,
        startClientX: 0,
        startClientY: 0,
        moved: false,
      };
      if (!drag.moved) return;
      const scale = normalizeBoardScale(state.boardScale);
      const dx = event.clientX - drag.startClientX;
      const dy = event.clientY - drag.startClientY;
      const nextX = Math.max(0, Math.round(drag.startX + (dx / scale)));
      const nextY = Math.max(0, Math.round(drag.startY + (dy / scale)));
      try {
        const data = await api('/api/move_sticky', { method: 'POST', body: { sticky_id: drag.stickyId, x: nextX, y: nextY, actor_name: state.actor, source: 'ui' } });
        if (applyStickySnapshot(data?.stickies || [])) return;
        await refreshSnapshot(true);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function uploadProvidedFiles(files) {
      const selectedFiles = Array.from(files || []).filter(Boolean);
      if (!selectedFiles.length) return;
      if (!requireSavedCardForFiles({ syncDropzone: true })) return;
      try {
        const normalizedFiles = selectedFiles.map((file) => normalizeUploadableAttachmentFile(file));
        for (const file of normalizedFiles) {
          const buffer = await file.arrayBuffer();
          const base64 = arrayBufferToBase64(buffer);
          await api('/api/add_card_attachment', { method: 'POST', body: { card_id: state.editingId, actor_name: state.actor, source: 'ui', file_name: file.name, mime_type: normalizeAttachmentMimeType(file.type) || attachmentMimeTypeFromExtension(attachmentExtension(file.name)) || 'application/octet-stream', content_base64: base64 } });
        }
        await refreshActiveCardFiles();
        state.cardJournalLoadedFor = '';
        setStatus(normalizedFiles.length > 1 ? 'ФАЙЛЫ ЗАГРУЖЕНЫ.' : 'ФАЙЛ ЗАГРУЖЕН.', false);
        await refreshSnapshot(true);
      } catch (error) {
        setStatus(error.message, true);
      } finally {
        els.fileInput.value = '';
        els.fileDropzone.classList.remove('is-active');
      }
    }

    async function uploadFiles() {
      return uploadProvidedFiles(els.fileInput.files);
    }

    function sharedFileById(fileId) {
      const normalizedId = String(fileId || '').trim();
      return (state.sharedFiles || []).find((item) => item.id === normalizedId) || null;
    }

    function activeSharedFile() {
      return sharedFileById(state.sharedFilesActiveId);
    }

    function sharedFileKindLabel(file) {
      const extension = String(file?.extension || '').replace('.', '').toUpperCase();
      if (!extension) return 'FILE';
      if (['JPG', 'JPEG', 'PNG', 'WEBP', 'GIF'].includes(extension)) return 'IMG';
      if (extension.length > 5) return extension.slice(0, 5);
      return extension;
    }

    function sharedFileDownloadUrl(file, { inline = false } = {}) {
      if (!file?.id) return '#';
      const path = '/api/shared_file?file_id=' + encodeURIComponent(file.id) + (inline ? '&disposition=inline' : '');
      return withAccessToken(path);
    }

    function sharedFileMetaParts(file) {
      return [
        sharedFileKindLabel(file),
        formatBytes(file?.size_bytes ?? 0),
        file?.updated_at ? formatDate(file.updated_at) : '',
      ].filter(Boolean);
    }

    function updateSharedFilesActions() {
      const hasActive = Boolean(activeSharedFile());
      [
        els.sharedFilesOpenButton,
        els.sharedFilesDownloadButton,
        els.sharedFilesRenameButton,
        els.sharedFilesCopyButton,
        els.sharedFilesDeleteButton,
      ].forEach((button) => {
        if (button) button.disabled = !hasActive;
      });
      if (els.sharedFilesPasteButton) {
        els.sharedFilesPasteButton.disabled = !state.sharedFilesClipboardId;
      }
      const crmPasteButton = els.sharedFilesContextMenu?.querySelector('[data-shared-files-menu-action="paste-crm"]');
      if (crmPasteButton instanceof HTMLButtonElement) {
        crmPasteButton.disabled = !state.sharedFilesClipboardId;
      }
    }

    function renderSharedFiles() {
      const files = Array.isArray(state.sharedFiles) ? state.sharedFiles : [];
      if (!els.sharedFilesDesktop) return;
      const laidOutFiles = sharedFilesLayout(files);
      if (!files.length) {
        els.sharedFilesDesktop.innerHTML = '<div class="shared-files-empty">ФАЙЛОВ ПОКА НЕТ.</div>';
      } else {
        els.sharedFilesDesktop.innerHTML = laidOutFiles.map((file) => {
          const x = finiteNonNegativeNumber(file.x);
          const y = finiteNonNegativeNumber(file.y);
          const activeClass = file.id === state.sharedFilesActiveId ? ' is-active' : '';
          const name = String(file.original_name || 'Файл');
          const metaParts = sharedFileMetaParts(file);
          const metaText = metaParts.join(' · ');
          return '<button class="shared-file-icon' + activeClass + '" type="button" data-shared-file-id="' + escapeHtml(file.id) + '" style="left:' + x + 'px; top:' + y + 'px" title="' + escapeHtml(name) + '" aria-label="Файл ' + escapeHtml(name + (metaText ? '. ' + metaText : '')) + '">'
            + '<span class="shared-file-icon__glyph">' + escapeHtml(sharedFileKindLabel(file)) + '</span>'
            + '<span class="shared-file-icon__name">' + escapeHtml(name) + '</span>'
            + '<span class="shared-file-icon__meta">' + metaParts.map((item) => '<span class="shared-file-icon__meta-chip">' + escapeHtml(item) + '</span>').join('') + '</span>'
            + '</button>';
        }).join('');
      }
      const storage = state.sharedFilesStorage || {};
      if (els.sharedFilesMeta) {
        els.sharedFilesMeta.textContent = formatBytes(storage.used_bytes ?? 0) + ' / ' + formatBytes(storage.limit_bytes ?? 0) + ' · ' + files.length + ' ФАЙЛ.';
      }
      updateSharedFilesActions();
    }

    function updateSharedFilesSelection() {
      if (!els.sharedFilesDesktop) return;
      const activeId = String(state.sharedFilesActiveId || '').trim();
      for (const icon of els.sharedFilesDesktop.querySelectorAll('[data-shared-file-id]')) {
        if (!(icon instanceof HTMLElement)) continue;
        icon.classList.toggle('is-active', String(icon.dataset.sharedFileId || '') === activeId);
      }
    }

    async function loadSharedFiles({ openModal = false } = {}) {
      try {
        const data = await api('/api/list_shared_files');
        state.sharedFiles = Array.isArray(data?.files) ? data.files : [];
        state.sharedFilesStorage = data?.storage || null;
        if (state.sharedFilesActiveId && !sharedFileById(state.sharedFilesActiveId)) {
          state.sharedFilesActiveId = '';
        }
        renderSharedFiles();
        maybeOpenModal(els.sharedFilesModal, openModal);
      } catch (error) {
        if (els.sharedFilesMeta) els.sharedFilesMeta.textContent = error.message;
        maybeOpenModal(els.sharedFilesModal, openModal);
        setStatus(error.message, true);
      }
    }

    async function openSharedFilesModal() {
      await loadSharedFiles({ openModal: true });
      els.sharedFilesDesktop?.focus?.({ preventScroll: true });
    }

    function selectSharedFile(fileId) {
      state.sharedFilesActiveId = String(fileId || '').trim();
      updateSharedFilesSelection();
      updateSharedFilesActions();
    }

    function normalizeSharedFilesDropPoint(point) {
      const x = finiteNumber(point?.x, NaN);
      const y = finiteNumber(point?.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
      return { x: Math.max(0, Math.round(x)), y: Math.max(0, Math.round(y)) };
    }

    function sharedFilesDropPointFromEvent(event) {
      if (!els.sharedFilesDesktop) return null;
      const rect = els.sharedFilesDesktop.getBoundingClientRect();
      return normalizeSharedFilesDropPoint({
        x: event.clientX - rect.left + els.sharedFilesDesktop.scrollLeft,
        y: event.clientY - rect.top + els.sharedFilesDesktop.scrollTop,
      });
    }

    function sharedFilesUploadPoint(index, baseIndex, dropPoint) {
      const point = normalizeSharedFilesDropPoint(dropPoint);
      if (!point) {
        return sharedFilesGridPointFromSlot(baseIndex + index);
      }
      return sharedFilesGridPointFromSlot(sharedFilesGridSlotFromPoint(point.x, point.y) + index);
    }

    function sharedFilesGridSlotFromPoint(x, y) {
      const col = Math.max(0, Math.round((finiteNumber(x) - 24) / 116));
      const row = Math.max(0, Math.round((finiteNumber(y) - 24) / 126));
      return row * 7 + col;
    }

    function sharedFilesGridPointFromSlot(slot) {
      const index = Math.max(0, Math.floor(finiteNumber(slot)));
      return {
        x: 24 + (index % 7) * 116,
        y: 24 + Math.floor(index / 7) * 126,
      };
    }

    function sharedFilesSnapPointToGrid(x, y) {
      return sharedFilesGridPointFromSlot(sharedFilesGridSlotFromPoint(x, y));
    }

    function sharedFilesLayout(files) {
      const orderedFiles = Array.from(files || []).sort((left, right) => {
        const leftSlot = sharedFilesStoredSlot(left);
        const rightSlot = sharedFilesStoredSlot(right);
        if (leftSlot !== rightSlot) return leftSlot - rightSlot;
        const leftTime = sharedFilesStableTime(left);
        const rightTime = sharedFilesStableTime(right);
        if (leftTime !== rightTime) return leftTime - rightTime;
        return String(left?.id || '').localeCompare(String(right?.id || ''));
      });
      const occupied = new Set();
      return orderedFiles.map((file, index) => {
        const storedX = finiteNumber(file?.x, NaN);
        const storedY = finiteNumber(file?.y, NaN);
        const hasStoredPosition = Number.isFinite(storedX) && Number.isFinite(storedY);
        let slot = hasStoredPosition ? sharedFilesGridSlotFromPoint(file.x, file.y) : index;
        while (occupied.has(slot)) slot += 1;
        occupied.add(slot);
        const point = sharedFilesGridPointFromSlot(slot);
        return {
          ...file,
          x: point.x,
          y: point.y,
          shared_files_layout_slot: slot,
        };
      });
    }

    function sharedFilesStoredSlot(file) {
      if (!file) return Number.MAX_SAFE_INTEGER;
      const x = finiteNumber(file.x, NaN);
      const y = finiteNumber(file.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) return Number.MAX_SAFE_INTEGER;
      return sharedFilesGridSlotFromPoint(x, y);
    }

    function sharedFilesStableTime(file) {
      const createdAt = Date.parse(String(file?.created_at || ''));
      if (Number.isFinite(createdAt)) return createdAt;
      const updatedAt = Date.parse(String(file?.updated_at || ''));
      if (Number.isFinite(updatedAt)) return updatedAt;
      return 0;
    }

    function sharedFilesClipboardFileName(mimeType, index = 0) {
      const normalizedMime = normalizeAttachmentMimeType(mimeType);
      const extension = ATTACHMENT_MIME_TO_EXTENSION[normalizedMime] || '.bin';
      const prefix = normalizedMime.startsWith('image/') ? 'clipboard-image' : 'clipboard-file';
      return clipboardAttachmentName(index > 0 ? prefix + '-' + (index + 1) : prefix, extension);
    }

    function sharedFilesFileNameForUpload(file, index) {
      const fileName = String(file?.name || '').trim();
      return fileName || sharedFilesClipboardFileName(file?.type || '', index);
    }

    function sharedFilesClipboardTypeLooksFile(mimeType) {
      const normalizedMime = normalizeAttachmentMimeType(mimeType);
      if (!normalizedMime) return false;
      return !normalizedMime.startsWith('text/');
    }

    async function readSharedFilesClipboardFiles() {
      if (!navigator.clipboard?.read) {
        throw new Error('БРАУЗЕР НЕ ДАЁТ ПРОЧИТАТЬ ФАЙЛ ИЗ БУФЕРА. ИСПОЛЬЗУЙТЕ CTRL+V ИЛИ ПЕРЕТАСКИВАНИЕ.');
      }
      const items = await navigator.clipboard.read();
      const files = [];
      for (const item of items || []) {
        const types = Array.from(item.types || []);
        for (const type of types) {
          if (!sharedFilesClipboardTypeLooksFile(type)) continue;
          const blob = await item.getType(type);
          if (!blob || !blob.size) continue;
          const mimeType = normalizeAttachmentMimeType(blob.type || type) || 'application/octet-stream';
          files.push(new File([blob], sharedFilesClipboardFileName(mimeType, files.length), { type: mimeType, lastModified: Date.now() }));
          break;
        }
      }
      return files;
    }

    function filesFromSharedFilesPasteEvent(event) {
      const clipboardData = event?.clipboardData;
      const directFiles = Array.from(clipboardData?.files || []).filter(Boolean);
      if (directFiles.length) return directFiles;
      const files = [];
      Array.from(clipboardData?.items || []).forEach((item) => {
        if (item.kind !== 'file') return;
        const file = item.getAsFile();
        if (file) files.push(file);
      });
      return files;
    }

    function sharedFilesClipboardFallbackAllowed(error) {
      const code = String(error?.code || '').trim();
      return !code || code === 'clipboard_empty' || code === 'clipboard_unavailable';
    }

    async function pasteSharedFilesFromLocalClipboard(dropPoint) {
      const point = normalizeSharedFilesDropPoint(dropPoint);
      const pasted = await api('/api/paste_shared_files_from_clipboard', {
        method: 'POST',
        body: {
          actor_name: state.actor,
          source: 'ui',
          x: point?.x ?? 24,
          y: point?.y ?? 24,
        },
      });
      const pastedFiles = Array.isArray(pasted?.files) ? pasted.files : [];
      if (!pastedFiles.length) return false;
      state.sharedFilesActiveId = pastedFiles[pastedFiles.length - 1]?.id || state.sharedFilesActiveId;
      await loadSharedFiles();
      setStatus(pastedFiles.length > 1 ? 'ФАЙЛЫ ВСТАВЛЕНЫ ИЗ БУФЕРА.' : 'ФАЙЛ ВСТАВЛЕН ИЗ БУФЕРА.', false);
      return true;
    }

    async function pasteSharedFilesFromSystemClipboard() {
      const dropPoint = state.sharedFilesContextPoint || null;
      let localClipboardError = null;
      try {
        if (await pasteSharedFilesFromLocalClipboard(dropPoint)) {
          hideSharedFilesContextMenu();
          return;
        }
      } catch (error) {
        localClipboardError = error;
        if (!sharedFilesClipboardFallbackAllowed(error)) {
          setStatus(error.message || 'НЕ УДАЛОСЬ ВСТАВИТЬ ФАЙЛ ИЗ БУФЕРА.', true);
          return;
        }
      }
      try {
        const files = await readSharedFilesClipboardFiles();
        if (!files.length) {
          setStatus(localClipboardError?.message || 'В БУФЕРЕ НЕТ ФАЙЛА ДЛЯ ВСТАВКИ. ИСПОЛЬЗУЙТЕ CTRL+V ИЛИ ПЕРЕТАСКИВАНИЕ.', true);
          return;
        }
        await uploadSharedFiles(files, { dropPoint });
        hideSharedFilesContextMenu();
      } catch (error) {
        setStatus(localClipboardError?.message || error.message || 'НЕ УДАЛОСЬ ВСТАВИТЬ ФАЙЛ ИЗ БУФЕРА.', true);
      }
    }

    async function handleSharedFilesPaste(event) {
      if (!els.sharedFilesModal?.classList.contains('is-open')) return;
      const files = filesFromSharedFilesPasteEvent(event);
      if (!files.length) return;
      event.preventDefault();
      event.stopPropagation();
      await uploadSharedFiles(files, { dropPoint: state.sharedFilesContextPoint || null });
      hideSharedFilesContextMenu();
    }

    function hideSharedFilesContextMenu() {
      if (els.sharedFilesContextMenu) {
        els.sharedFilesContextMenu.hidden = true;
        els.sharedFilesContextMenu.style.left = '';
        els.sharedFilesContextMenu.style.top = '';
      }
      state.sharedFilesContextPoint = null;
    }

    function positionSharedFilesContextMenu(clientX, clientY) {
      if (!els.sharedFilesContextMenu) return;
      const padding = 8;
      els.sharedFilesContextMenu.style.left = Math.max(padding, Math.round(clientX)) + 'px';
      els.sharedFilesContextMenu.style.top = Math.max(padding, Math.round(clientY)) + 'px';
      window.requestAnimationFrame(() => {
        const rect = els.sharedFilesContextMenu.getBoundingClientRect();
        const maxLeft = Math.max(padding, window.innerWidth - rect.width - padding);
        const maxTop = Math.max(padding, window.innerHeight - rect.height - padding);
        els.sharedFilesContextMenu.style.left = Math.min(Math.max(padding, Math.round(clientX)), maxLeft) + 'px';
        els.sharedFilesContextMenu.style.top = Math.min(Math.max(padding, Math.round(clientY)), maxTop) + 'px';
      });
    }

    function handleSharedFilesContextMenu(event) {
      if (!els.sharedFilesDesktop?.contains(event.target)) return;
      event.preventDefault();
      event.stopPropagation();
      const icon = event.target?.closest?.('[data-shared-file-id]');
      if (icon instanceof HTMLElement) selectSharedFile(icon.dataset.sharedFileId);
      state.sharedFilesContextPoint = sharedFilesDropPointFromEvent(event);
      updateSharedFilesActions();
      if (els.sharedFilesContextMenu) {
        els.sharedFilesContextMenu.hidden = false;
        positionSharedFilesContextMenu(event.clientX, event.clientY);
      }
      els.sharedFilesDesktop?.focus?.({ preventScroll: true });
    }

    async function handleSharedFilesContextMenuClick(event) {
      const button = event.target?.closest?.('[data-shared-files-menu-action]');
      if (!(button instanceof HTMLButtonElement) || button.disabled) return;
      event.preventDefault();
      const action = String(button.dataset.sharedFilesMenuAction || '').trim();
      if (action === 'paste-clipboard') {
        await pasteSharedFilesFromSystemClipboard();
        return;
      }
      if (action === 'paste-crm') {
        await pasteSharedFile({ dropPoint: state.sharedFilesContextPoint || null });
        hideSharedFilesContextMenu();
        return;
      }
      if (action === 'upload') {
        hideSharedFilesContextMenu();
        els.sharedFilesInput?.click();
      }
    }

    function handleSharedFilesDocumentClick(event) {
      if (!els.sharedFilesContextMenu || els.sharedFilesContextMenu.hidden) return;
      if (els.sharedFilesContextMenu.contains(event.target)) return;
      hideSharedFilesContextMenu();
    }

    function handleSharedFilesGlobalKeydown(event) {
      if (event.key === 'Escape') hideSharedFilesContextMenu();
    }

    function handleSharedFilesDragOver(event) {
      const types = Array.from(event.dataTransfer?.types || []);
      if (!types.includes('Files')) return;
      event.preventDefault();
      event.dataTransfer.dropEffect = 'copy';
      els.sharedFilesDesktop?.classList.add('is-drop-target');
      els.sharedFilesDesktop?.focus?.({ preventScroll: true });
    }

    function handleSharedFilesDragLeave(event) {
      if (!els.sharedFilesDesktop) return;
      if (event.relatedTarget instanceof Node && els.sharedFilesDesktop.contains(event.relatedTarget)) return;
      els.sharedFilesDesktop.classList.remove('is-drop-target');
    }

    async function handleSharedFilesDrop(event) {
      const files = Array.from(event.dataTransfer?.files || []).filter(Boolean);
      els.sharedFilesDesktop?.classList.remove('is-drop-target');
      if (!files.length) return;
      event.preventDefault();
      event.stopPropagation();
      hideSharedFilesContextMenu();
      await uploadSharedFiles(files, { dropPoint: sharedFilesDropPointFromEvent(event) });
    }

    async function uploadSharedFiles(files, { dropPoint = null } = {}) {
      const selectedFiles = Array.from(files || []).filter(Boolean);
      if (!selectedFiles.length) return;
      try {
        const baseIndex = (state.sharedFiles || []).length;
        const normalizedDropPoint = normalizeSharedFilesDropPoint(dropPoint);
        for (let index = 0; index < selectedFiles.length; index += 1) {
          const file = selectedFiles[index];
          if (file.size > SHARED_FILE_UPLOAD_MAX_SIZE_BYTES) {
            throw new Error('ФАЙЛ СЛИШКОМ БОЛЬШОЙ. ЛИМИТ: 25 МБ.');
          }
          const buffer = await file.arrayBuffer();
          const fileName = sharedFilesFileNameForUpload(file, index);
          const extension = attachmentExtension(fileName);
          const mimeType = normalizeAttachmentMimeType(file.type) || attachmentMimeTypeFromExtension(extension) || 'application/octet-stream';
          const point = sharedFilesUploadPoint(index, baseIndex, normalizedDropPoint);
          const uploaded = await api('/api/upload_shared_file', {
            method: 'POST',
            body: {
              actor_name: state.actor,
              source: 'ui',
              file_name: fileName,
              mime_type: mimeType,
              content_base64: arrayBufferToBase64(buffer),
              x: point.x,
              y: point.y,
            },
          });
          if (uploaded?.file?.id) state.sharedFilesActiveId = uploaded.file.id;
        }
        await loadSharedFiles();
        setStatus(selectedFiles.length > 1 ? 'ФАЙЛЫ ЗАГРУЖЕНЫ.' : 'ФАЙЛ ЗАГРУЖЕН.', false);
      } catch (error) {
        setStatus(error.message, true);
      } finally {
        if (els.sharedFilesInput) els.sharedFilesInput.value = '';
      }
    }

    function openActiveSharedFile() {
      const file = activeSharedFile();
      if (!file) return;
      window.open(sharedFileDownloadUrl(file, { inline: true }), '_blank', 'noopener');
    }

    async function downloadActiveSharedFile() {
      const file = activeSharedFile();
      if (!file) return;
      try {
        await downloadAttachment(sharedFileDownloadUrl(file));
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function renameActiveSharedFile() {
      const file = activeSharedFile();
      if (!file) return;
      const nextName = window.prompt('Новое имя файла', file.original_name || '');
      if (nextName === null) return;
      const normalized = String(nextName || '').trim();
      if (!normalized) return;
      try {
        const data = await api('/api/rename_shared_file', {
          method: 'POST',
          body: { file_id: file.id, file_name: normalized, actor_name: state.actor, source: 'ui' },
        });
        if (data?.file?.id) state.sharedFilesActiveId = data.file.id;
        await loadSharedFiles();
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function copyActiveSharedFile() {
      const file = activeSharedFile();
      if (!file) return;
      try {
        const data = await api('/api/copy_shared_file', {
          method: 'POST',
          body: { file_id: file.id, actor_name: state.actor, source: 'ui' },
        });
        state.sharedFilesClipboardId = data?.clipboard?.source_id || file.id;
        updateSharedFilesActions();
        setStatus('ФАЙЛ СКОПИРОВАН.', false);
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function pasteSharedFile({ dropPoint = null } = {}) {
      if (!state.sharedFilesClipboardId) return;
      const source = sharedFileById(state.sharedFilesClipboardId);
      const point = normalizeSharedFilesDropPoint(dropPoint);
      const basePoint = point
        ? point
        : {
            x: Math.max(24, finiteNumber(source?.x, 24) + 32),
            y: Math.max(24, finiteNumber(source?.y, 24) + 32),
          };
      const snappedPoint = sharedFilesSnapPointToGrid(basePoint.x, basePoint.y);
      try {
        const data = await api('/api/paste_shared_file', {
          method: 'POST',
          body: {
            source_id: state.sharedFilesClipboardId,
            x: snappedPoint.x,
            y: snappedPoint.y,
            actor_name: state.actor,
            source: 'ui',
          },
        });
        if (data?.file?.id) state.sharedFilesActiveId = data.file.id;
        await loadSharedFiles();
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    async function deleteActiveSharedFile() {
      const file = activeSharedFile();
      if (!file) return;
      if (!window.confirm('Удалить файл "' + String(file.original_name || '').trim() + '"?')) return;
      try {
        await api('/api/delete_shared_file', {
          method: 'POST',
          body: { file_id: file.id, actor_name: state.actor, source: 'ui' },
        });
        if (state.sharedFilesClipboardId === file.id) state.sharedFilesClipboardId = '';
        state.sharedFilesActiveId = '';
        await loadSharedFiles();
      } catch (error) {
        setStatus(error.message, true);
      }
    }

    function beginSharedFileDrag(event) {
      const icon = event.target?.closest?.('[data-shared-file-id]');
      if (!(icon instanceof HTMLElement) || event.button !== 0) return;
      const fileId = String(icon.dataset.sharedFileId || '').trim();
      if (!fileId) return;
      hideSharedFilesContextMenu();
      selectSharedFile(fileId);
      const desktopRect = els.sharedFilesDesktop.getBoundingClientRect();
      const iconRect = icon.getBoundingClientRect();
      state.sharedFilesDrag = {
        fileId,
        pointerId: event.pointerId,
        offsetX: event.clientX - iconRect.left,
        offsetY: event.clientY - iconRect.top,
        moved: false,
      };
      icon.classList.add('is-dragging');
      icon.setPointerCapture?.(event.pointerId);
      event.preventDefault();
      void desktopRect;
    }

    function moveSharedFileDrag(event) {
      const drag = state.sharedFilesDrag;
      if (!drag || drag.pointerId !== event.pointerId) return;
      const icon = els.sharedFilesDesktop?.querySelector('[data-shared-file-id="' + CSS.escape(drag.fileId) + '"]');
      if (!(icon instanceof HTMLElement)) return;
      const desktopRect = els.sharedFilesDesktop.getBoundingClientRect();
      const nextX = Math.max(
        0,
        Math.round(event.clientX - desktopRect.left + els.sharedFilesDesktop.scrollLeft - drag.offsetX),
      );
      const nextY = Math.max(
        0,
        Math.round(event.clientY - desktopRect.top + els.sharedFilesDesktop.scrollTop - drag.offsetY),
      );
      const snappedPoint = sharedFilesSnapPointToGrid(nextX, nextY);
      icon.style.left = snappedPoint.x + 'px';
      icon.style.top = snappedPoint.y + 'px';
      icon.dataset.dragX = String(snappedPoint.x);
      icon.dataset.dragY = String(snappedPoint.y);
      drag.moved = true;
      event.preventDefault();
    }

    async function finishSharedFileDrag(event) {
      const drag = state.sharedFilesDrag;
      if (!drag || drag.pointerId !== event.pointerId) return;
      state.sharedFilesDrag = null;
      const icon = els.sharedFilesDesktop?.querySelector('[data-shared-file-id="' + CSS.escape(drag.fileId) + '"]');
      if (icon instanceof HTMLElement) icon.classList.remove('is-dragging');
      if (!(icon instanceof HTMLElement) || !drag.moved) return;
      const x = finiteNonNegativeNumber(icon.dataset.dragX);
      const y = finiteNonNegativeNumber(icon.dataset.dragY);
      try {
        const data = await api('/api/update_shared_file_position', {
          method: 'POST',
          body: { file_id: drag.fileId, x, y, actor_name: state.actor, source: 'ui' },
        });
        if (data?.file?.id) {
          const file = sharedFileById(data.file.id);
          if (file) {
            file.x = data.file.x;
            file.y = data.file.y;
          }
        }
      } catch (error) {
        setStatus(error.message, true);
        await loadSharedFiles();
      }
    }

    function handleSharedFilesDesktopClick(event) {
      els.sharedFilesDesktop?.focus?.({ preventScroll: true });
      hideSharedFilesContextMenu();
      const icon = event.target?.closest?.('[data-shared-file-id]');
      if (icon instanceof HTMLElement) selectSharedFile(icon.dataset.sharedFileId);
    }

    function handleSharedFilesDesktopDoubleClick(event) {
      hideSharedFilesContextMenu();
      const icon = event.target?.closest?.('[data-shared-file-id]');
      if (!(icon instanceof HTMLElement)) return;
      selectSharedFile(icon.dataset.sharedFileId);
      openActiveSharedFile();
    }

    async function addRepairOrderRowFromButton(section, event) {
      event.preventDefault();
      event.stopPropagation();
      await addRepairOrderRow(section);
    }

    function handleRepairOrderModalInput(event) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      if (target.matches('[data-repair-order-cell="executor_id"]')) {
        const row = target.closest('tr[data-repair-order-row]');
        if (row instanceof HTMLElement) {
          row.dataset.repairOrderSalaryMode = '';
          row.dataset.repairOrderBaseSalary = '';
          row.dataset.repairOrderWorkPercent = '';
          row.dataset.repairOrderSalaryAmount = '';
          row.dataset.repairOrderSalaryAccruedAt = '';
          if (state.repairOrderWorkSalaryRow === row && els.repairOrderWorkSalaryMeta) {
            const normalized = readRepairOrderRowElement(row);
            els.repairOrderWorkSalaryMeta.textContent = normalized.executor_name ? ('ИСПОЛНИТЕЛЬ: ' + normalized.executor_name) : 'ИСПОЛНИТЕЛЬ НЕ ВЫБРАН';
          }
        }
      }
      if (target.closest('tr[data-repair-order-row]')) syncRepairOrderTotals();
      scheduleRepairOrderSaveDirtyStateSync();
    }

    function saveRepairOrderDraft() {
      return saveRepairOrder(false);
    }
